INSERT INTO `messages2` (`id`, `url`, `page_title`, `info`, `search_terms`, `page_desc`, `text1`, `text2`, `image`, `video`, `meta_title`, `bottomtext`, `date`, `whatvideo`, `alt`, `rating`, `twitter`, `hometext`, `santa`, `ntext1`, `ntext2`, `ntext3`, `ntext4`, `nimage1`, `nimage2`, `nimage3`, `nimage4`) VALUES
(1, 'pirate-voiceover', 'Pirate Voiceover', '<p>Here is a sample of my Pirate voiceover. One of the featured voices on my website as I\'m asked for it so much.</p>', 'captain kids toys', 'Pirate Voiceover - Looking for a great Pirate voice? Let ye treasure be a booking with Guy Harris. The gold is right here at voiceoverguy.co.uk', '<h2>Captain of this style</h2>\r\n<p>Looking for a great pirate? Let ye treasure be a booking with my pirate voiceover. The TV ad for this great game called Pirate Bridge aired on TV in 2013. The pirate voice is one of the regular voice styles I\'m asked for, along with my <a href=\"david-attenborough-voice\"  title=\"David Attenborough Voiceover\">David Attenborough voice</a> and my <a href=\"santa-voice\"  title=\"Santa Voiceover\">Santa voice</a>.</p>', '<br><h2>Voice of a Pirate</h2>\r\n<p>Yarrrrrgh! Working with some great brand names, I\'ve been asked to voice for some really fun projects including <a href=\"lego-minifigures-pirate\" title=\"Lego Pirates Voiceover\">Lego Pirates</a>, <a href=\"pop-up-pirate-voiceover\" title=\"Popup Pirate Game Voiceover\">Popup Pirate</a> and <a href=\"cbbc-pirate-week-voice\"  title=\"CBeebies Pirate Week Voiceover\">CBeebies\' Pirate Week</a>.</p>', 'pirate-voiceover.jpg', 'Egnp8ZWrojI', 'Pirate Voiceover - Need a Pirate? - VoiceoverGuy XXX', '<h2>Get in touch</h2>\r\n<p>If I can help provide you with a pirate voice for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV ad</a>, let me know more details about the project and usage so that I can better quote. Please get in touch if you\'d like to work with me. I\'d be very happy to send a short sample of your script before you book me. \r\nPlease send a few lines of the script first so you can be sure I\'m right for your brand. \r\nI make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'March 2013', '1', 'Pirate Voiceover', '0', '%23PirateVoice %23pirateBridge', 'How to get a great Pirate voice?', '', '', '', '', '', '', '', '', ''),
(466, 'silly-moo-voiceover', 'Silly Moo Voiceover', '<p>Another crazy toy by Ideal Toys with a crazy silly moo voiceover to go with it. \"Udder pulling dice rolling cow milking fun\"</p>', 'TVC', 'Silly Moo Voiceover - Another crazy toy by Ideal Toys - Udder pulling dice rolling cow milking fun - Voiced by Guy Harris - www.voiceoverguy.co.uk', '<h2>TV Advert voice</h2>\r\n<p>As a voice over, I\'m constantly asked where people might have heard my work. When I mention kids\' toys on TV, the penny drops and when I mention <a href=\"doggie-doo-voice-over\"  title=\"Doggie Doo\">Doggie Doo</a>, <a href=\"gooey-louie-voiceover\"  title=\"Gooey Louie\">Gooey Louie</a> and this crazy game: Silly Moo.  I think my best excited, enthusiastic voice is just a good fit with children\'s commercials, as I get asked to provide voiceover for countless kids\' ads every year. A lot of kid\'s toys are a little strange to me, but I think Silly Moo might be one of the strangest I\'ve seen yet. But \'strange\' is certainly a good thing!</p>', '<h2>What is Silly Moo?</h2>\r\n<p>Silly Moo is the \'udderly\' funny game where you milk the cow! Milk cartons score pints but watch out for the pats as they lose you pints. When Silly Moo\'s eyes pop out she is fully milked so count up the score the one with the most pints wins! It\'s hard to think of a sillier game concept, and i love it! I wonder why so many kids games involve poo or snot..? Hmm. Anyway, this promo was a lot of fun to voice and the game is clearly a lot of fun to play!</p>', 'silly-moo-voiceover.jpg', 'XsV-0ovRCK0', 'Silly Moo Voiceover - voiceoverguy - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for a voice style similar to Silly Moo for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a>? Please get in touch. I\'d be very happy to send a short sample of your script before you book me. \r\nPlease send a few lines of the script first so you can be sure I\'m right for your brand. \r\nThe whole process is easy, with 99% of the jobs delivered the same day.</p>\r\n', 'June 2013', '1', 'Silly Moo Voiceover', '0', '', 'Crazy Voiceover for Silly Moo!', '', '', '', '', '', '', '', '', ''),
(467, 'wren-kitchens-voiceover', 'Wren Kitchens Voiceover', '<p>This is an awesome viral video for Wren Kitchens. </p>', 'viral characters', 'Wren Kitchens Voiceover - This is an awesome viral with over 3 million views on their channel. both voices by Guy Harris - www.voiceoverguy.co.uk', '<h2>Wren Kitchens Viral Video</h2>\r\n<p>One of many great projects I get to work on.  Wren Kitchens are a well-known brand here in the UK, so naturally, when they asked me to work with them I said yes immediately. The two characters in the video were based on an old VW advert from many years ago. Both characters of thisÂ wren kitchens voiceover hadÂ over 5.3 million views on  the Wren Kitchens\' YouTube channel. Not too shabby. I like working with bigger UK brands, and if you\'d like a few examples of the other big voiceover jobs I\'ve done for UK companies, check out my Tesco and <a href=\"morrisons-wonky-in-store-voiceovers\" title=\"Morrison\'s Voiceover\">Morrison\'s</a> videos.</p>', '<h2>A Little more about Wren Kitchens\' viral video</h2>\r\n<p>During the peak of it\'s time on YouTube, it amassed an incredible amount of hits. 5.3million is an impressive number. What makes it even better? Some nice comments too! Wren Kitchens is a pretty big company, but that\'s nowhere near enough to ensure your video will go viral. I think they did a great job with the script and I\'m proud of the part I played in it. <br>\r\nSince this was voiced I am also one of the voices inshore at Wren now advertising their offers to customers shopping.\r\n</p>', 'wren-kitchens-voiceover.jpg', 'C5WFjmzV4kI', 'Wren Kitchens voiceover - viral - voiceoverguy - Guy Harris', '<h2>Get in touch</h2>\r\n<p>It\'s a pleasure working with some of the world\'s best brands. So, if you are looking for characterÂ voices similar to this Wren Kitchens\' voiceover for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a>, please <a href=\"contact-guy\" title=\"Get in touch\">get in touch</a>. If you can send me aÂ smallÂ piece of the script, I\'ll gladlyÂ send you a short voice a sample first to see if my voice is right for your promoÂ or viral.</p>', 'Aug 2013', '1', 'Wren Kitchens voiceover', '3', '', 'WREN kitchens viral that went LARGE!!!', '', '', '', '', '', '', '', '', ''),
(468, 'turtle-strike-voiceover', 'Turtle Strike Voiceover', '<p>Turtle Strike. A great App. Fantastic graphics on this game. I got to voice it in my Movie Trailer Voice.<p>', 'movie trailer', 'Turtle Strike voiceover - Turtle Strike. A great App for iOS, Android and Amazon.. Fantastic graphics on this game. I voiced it in my Movie Trailer Voice', '<h2>The movie trailer voice</h2>\r\n<p>As you can tell by my blog, I like to voice <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailers</a>. I feel very lucky to work with some amazing production houses who create these videos. This one needed that all-American <a href=\"movie-trailer-voice\" title=\"Movie Trailer Voiceover\">movie trailer voiceover</a> style and I had a lot of fun with it. Essentially, the style for this was the classic in-a-world voice and it\'s something I rarely get to say. If you\'d like to hear more of my game trailers, check out my <a href=\"warwings-game-trailer-voice\" title=\"Warwings Trailer Voiceover\">Warwings</a> and <a href=\"worms-wmd-character-voices\" title=\"Worms WMD Trailer Voiceover\">Worms WMD</a> trailers.<p>', '<h2>What is Turtle Strike?</h2>\r\n<p>Turtle Strike is a free-to-play multiplayer strategy game with live turn-based mechanics developed by the Prague-based eeGon Games. Both players have limited time to plan their moves and then the moves of both players are processed simultaneously. <br> This game clearly has a lot of humour packed into it, and this humour definitely made its way onto the trailer script. It\'s always easier for me when the script is well written!</p>', 'turtle-strike-voiceover.jpg', 'IEqODwRGQig', 'Turtle Strike Voiceover - movie trailer voice - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for a movie voice for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a>? Something like this for a project? Please <a href=\"contact-guy\" title=\"Get in touch\">get in touch</a>. I\'d be very happy to send a short sample before you book me. Just send a few lines of the script first so you can be sure I\'m right for your brand. I\'ll make the whole process easy, with 99% of the jobs delivered the same day.</p>', 'Sep 2013', '1', 'Turtle Strike Voiceover', '3', '', 'The Big Movie Trailer Voice...', '', '', '', '', '', '', '', '', ''),
(469, 'gooey-louie-voiceover', 'Gooey Louie Voiceover', '<p>Voiceover of the TV Advert for the crazy kids toy from Ideal Toys - Gooey Louie</p>', 'kids toys games tv', 'Guy Harris is the voice of Gooey Louie, the wacky nose-picking game for kids! See how he brought silly, snot-filled fun to life with this classic toy VO.', '<h2>Christmas Toys for Kids</h2>\r\n<p>As you can tell, I do a lot of kids toys voiceovers for TV. I guess my energetic voice is a great fit with this industry. I also  have a popular <a href=\"santa-voice\" title=\"Santa Voiceover\">Santa voiceover</a> that is used every year.\r\nI actually recorded this particular Gooey Louie voiceover a few years ago now, but due to it\'s popularity at Christmas, it\'s on every year. <br>As a voice you can\'t say no to re-licence fees. ðŸ˜<br>\r\nThere were several new toys launched around this time including <a href=\"doggie-doo-voice-over\" title=\"Doggie Doo TV Advert\">Doggie Doo</a> and <a href=\"pig-goes-pop-voiceover\" title=\"Pig goes Pop\">Pig goes Pop</a>. And if you\'d like to hear even more of my kid\'s toy voiceovers, check out my <a href=\"pop-up-pirate-voiceover\" title=\"Pop-up Pirate\">Pop-up Pirate</a> and <a href=\"bugs-in-kitchen-voice\" title=\"Bugs in the Kitchen Voiceover\">Bugs in the Kitchen</a> videos too. \r\n</p>', '<h2>What is Gooey Louie?</h2>\r\n<p>This gruesome <a href=\"https://www.smythstoys.com/uk/en-gb/toys/games-puzzles-and-books/board-games/children-s-board-games/gooey-louie-board-game/p/199638\" target=\"_blank\" title=\"Gooey Louie GameE\">Gooey Louie Game</a> will have you laughing for hours. Take it in turns to stick your finger up poor Louie\'s nose and pull out many stretch gooeys, eurgh! Be careful if you pull out the wrong gooey then his eyes will bulge and his brain will explode!<br> Pull out one of Louie\'s many stretchy gooeys, it could be short or it could be long! This is such a fun, delightfully gross board game and it was a lot of fun to provide the voiceover for the TV ad!</p>', 'gooey-louie-voiceover.jpg', 'YtTD1k-AGJY', 'Gooey Louie Voiceover - voiceoverguy - Guy Harris', '<h2>Need this style?</h2>\r\n<p>Are you looking for this energetic voice style for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV ad</a>, or perhaps even for a more specialist <a href=\"explainer-video-voice\"  title=\"Explainer Video Voiceover\">explainer video</a>? Please <a href=\"contact-guy\" title=\"Get in touch\">get in touch</a>. I\'d be very happy to send a short sample before you book me. Please send a few lines of the script first so you can be sure I\'m right for the brand or project. I make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Sept 2013', '1', 'Gooey Louie Voiceover', '3', '%23GooeyLouie', 'TV Advert for Gooey Louie', '', '         ', '', '', '', '', '', '', ''),
(470, 'minecraft-handbook-voiceover', 'Minecraft Handbook Voiceover', '<p>Nice to try out this Deep Voice style for the trailer. My English Movie trailer voice. </p>', 'deep english', 'Minecraft Handbook Voiceover - My English movie trailer voice over was used on a fun video for the popular sandbox game. The essential guide for fans.', '<h2>English movie trailer voice</h2>\r\n<p> I love voicing game trailers and other games-related promos. Having watched my nieces and nephew play Minecraft and create some amazing worlds, I was intrigued by the game and more than up for voicing something for Minecraft sometime. Then this beginner\'s guide came along! Created in the UK and the audio mixed and mastered over in the UAE, it\'s turned out really great and I\'ve loved being part of this project! Minecraft is one of the biggest videogames ever and I don\'t mind any association with the brand... Following this trailer release, I voiced several more trailers in this style including <a href=\"kings-road-voiceover\" target=\"_blank\" title=\"Kings Road\">Kings Road</a>, <a href=\"lifeless-game-trailer-voice\" target=\"_blank\" title=\"Lifeless Game Trailer Voiceover\">Lifeless</a>, and <a href=\"robocide-game-trailer-voice\" target=\"_blank\" title=\"Robocide Game Trailer\">Robocide</a>.</p>', '<br><h2>What is the Minecraft Handbook?</h2>\r\n<p>Minecraft, the game, might not need an introduction for some readers â€” given its popularity. It\'s a huge, procedural-generated game where the players explore the world and build whatever they want. but the game can be a little complicated. This is where the beginner\'s guide comes in! Learn how to build a fort, craft armour and weapons with the Minecraft Handbook.<br>This handy user guide will teach any fan of the popular sandbox game everything they need to know about defending themselves and building the best structures.</p>', 'minecraft-handbook-voiceover.jpg', 'TISd_9l7ZvA', 'Minecraft Handbook Voiceover - voiceoverguy - Guy Harris', '<h2>Do get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover</a> or <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailer</a>? Please get in touch and we can discuss how we can work together! I\'d be very happy to send a short sample before you book me. Please send a few lines of the script first so you can be sure I\'m right for the brand or project. I make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Sep 2013', '1', 'Minecraft Handbook Voiceover', '3', '%23minecraft', 'The Minecraft Handbook Voiceover...', '', '', '', '', '', '', '', '', ''),
(471, 'voiceover-character', 'Domestos Wacky Character Voiceover', '<p>This isÂ my character voiceover for a Domestos TV advert. I was asked to come up with the voices and this is what I gave them.</p>', 'michael caine animation', 'Domestos Character Voiceover - Voiced the characters for a Domestos TV ad. Asked to come up with the voices, this is what I gave them.... www.voiceoverguy.co.uk', '<h2>Multiple characters</h2>\r\n<p>Character voice work is a large part of what I do on a daily basis. I\'ve done too many characters to possibly take stock of them all, and I\'ve just added a bunch more for Domestos! It\'s always fun with a brand gives you creative reign and this is exactly what Doemstos did. Did you\'d like to hear some more characters, check out my <a href=\"character-voiceover\" title=\"Character Voiceover\">character showreel</a>. I was also asked to provide most of the worms\' voices for <a href=\"worms-wmd-character-voices\" title=\"Worms WMD Character Voices\">Worms WMD</a> and I\'ve provided the voice of Santa for the <a href=\"https://www.youtube.com/watch?v=yi-4Fm40nmE\" target=\"_blank\" title=\"GoJetter\'s Chrsitmas Special Santa Voiceover\">GoJetter\'s Christmas special</a>.</p>', '<br><h2>Character creation</h2>\r\n<p>People use <a href=\"https://www.domestos.com/uk/home.html\" target=\"_blank\" title=\"Domestos\">Domestos</a> and this ad was broadcast across the UAE. It is very similar to the UK version.<br>\r\nI\'m thinking one of the creatures sounds a little like <a href=\"michael-caine-voiceover\" title=\"Michael Caine Voiceover\">Michael Caine </a>for some reason...<br>Always fun when there are multiple voices to come up with. I was really pleased how it turned out.<br>\r\nWhat can I come up with for you? Let\'s create something completely unique (or with one Michael Caine voice in there too).</p>', 'character-voiceover.jpg', '4z5YmovEb9E', 'Domestos Character Voiceover - VoiceoverGuy - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for a character voice for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a>? Please get in touch if you\'d like to work with me! I\'m more than happy to send a short sample of your script. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make the whole process as easy as possible with 99% of the jobs delivered the same day!</p>', 'Nov 2013', '1', 'Character Voiceover', '3', '', 'Character voiceovers - Domestos TV advert', '', '', '', '', '', '', '', '', ''),
(472, 'a-team-voice', 'A-Team Voice', '<p>This is myÂ A-Team Voice Style. I loved voicing this trailer for Smash Bandits. Â Maybe you can hire.... Me!</p>', 'character american', 'A-Team Voice - I love this trailer for the game Smash Bandits. Great Trailer Voice. If you are looking for a movie voice? Get in touch. Same day delivery.', '<h2>Character voices</h2>\r\n<p>I\'d already voiced a trailer for the previous game, so it was awesome to be asked back for the new one.<br>\r\nMy A-Team voice impression had already been used on <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">radio commercials</a> over the years, so it was nice to use it somewhere different. Mixed and mastered in the UAE, I\'m really proud to have this on my portfolio. I love voicing game trailers, and I like the tough, American angle too. If you\'d like to hear a little more like this, check out my <a href=\"worms-wmd-character-voices\" target=\"_blank\" title=\"Worms WMD Trailer\">Worms WMD</a> and <a href=\"the-escapists-game-trailer\" target=\"_blank\" title=\"The Escapists Game Trailer\">The Escapists</a> game trailers.</p>', '<br>\r\n<h2>What is Smash Bandits?</h2>\r\n<p>Well, this is Smash Bandits by <a href=\"https://www.hutch.io\" target=\"_blank\">Hutch Games</a>?<br>\r\nThis time the players are outrunning the cops and smash their way through a stunning procedurally-generated open world where everything becomes destroyable.<br>\r\nThey get to hop between cars, tanks and boats, doing whatever it takes to get the cops off their tail and keep the action going.<br>\r\nThis game looks like a lot of fun and it was also lots of fun to provide the voiceover for this promotion!</p>', 'a-team-voice.jpg', '4hHuiPqQkvs', 'A-Team Voice - VoiceoverGuy - Smash Bandits - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Just another of the many <a href=\"/character-voiceover\">characters</a> I get to voice on a daily basis. If you are looking for a voice similar to thisÂ A-Team Voice or something else for your upcoming <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a>, then do get in touch. Let me know the usage and a few more details and I\'ll give you a quote. Even better if you can send some of the script too. This way I can read part of to see if I match your product or brand.</p>', 'Nov 2013', '1', 'A-Team Voice', '3', '%23TheATeam', 'Maybe you can hire... myÂ A-Team Voice', '', '', '', '', '', '', '', '', ''),
(473, 'apple-voiceover', 'That Apple Style VoiceOver?', '<p>A couple of years ago I was asked if I\'d like to be theÂ voice of Apple on the iPhone television commercials. WhenÂ you look at Apple\'s marketing and see it\'s celebrity endorsed,Â would I like to do them? Absolutely.</p>', 'natural explainer conversational real Jonathan Ives jony', 'Sleek and minimal Apple-style voiceovers voiced by Guy Harris. Used in iPhone ads and explainer content â€” calm, clear, and polished to perfection.', '<h2>Check out the video</h2>\r\n<p>The session was awesome and the client approved the audio immediately.Â To this day I have a framed copy of the script in my studio. \r\nMyÂ <a href=\"apple-voice-style\" target=\"_blank\" title=\"natural style\">natural style</a> has been in demand ever since. From corporate voice work to <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a> and <a href=\"on-hold-voice\" target=\"_blank\" title=\"on Hold Voiceover\">on hold messages</a>. When setting out on this journey, I didn\'t think my regular speaking voice would overtake everything else I\'m booked for, but there\'s been a huge influx of companies asking for the natural voice. You might also like to check out my <a href=\"because-i-see-voiceover\" target=\"_blank\" title=\"Because I See Voiceover\">Because I See</a> and <a href=\"save-water\" target=\"_blank\" title=\"Save Water Voiceover\">Save Water</a> videos.</p>', '<br>\r\n<h2>The Apple Voice over style</h2>\r\n<p>\r\nThese adverts completely changed the direction my career as a voice over was going. Several times a week I\'m asked for the Apple voice style. Including Stormfront, the Apple reseller.<br>I think clients are referring to the natural and conversational tone, often understated and soft but with short meaningful script writing, can have a huge impact. This style is often used for <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a>, so take a look at my <a href=\"hotels-dot-com-what-else-could-go-wrong-voiceover\" target=\"_blank\" title=\"Hotels.com\">Hotels.com</a> videos for a better idea of how effective my natural voiceover can be.</p>', 'apple-voice-style.jpg', 'V6HuBB4WqxQ', 'Voice of Apple - iPhone 5 TV Adverts - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo video</a>? One similar to this Apple voice over style? Please get in touch if you\'d like to work with me. I\'d be very happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Nov 2013', '1', 'Apple Voiceover', '5', '%23Apple', 'TheÂ Apple Voice - TV across the UAE.', '', '', '', '', '', '', '', '', ''),
(474, 'good-game-empire-trailer-voice', 'Good Game Empire deep trailer voice', '<p>Good Game Empire comes to the UK with a great NEW deep voice promo voice</p>', '', 'Guy Harris provides the dramatic voiceover for Goodgame Empire â€“ a medieval strategy trailer filled with energy, battles, and cinematic flair for gamers.', '<h2>British Movie Trailer Voice</h2>\r\n<p>You need a great strategy to become a great king in Goodgame Empire! Turn an insignificant spot on the world map into a mighty kingdom. Produce resources to build your magnificent castle. Recruit an army to protect it and conquer other kingdoms to expand your power. Fight epic battles against other players or forge strategic alliances to help you on your path to the ultimate goal: becoming the most powerful king of all! I love voicing <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailers</a> and if you\'d like to hear a few more examples of my work, check out my <a href=\"lifeless-game-trailer-voice\" target=\"_blank\" title=\"Lifeless Game Trailer\">Lifeless</a>, and <a href=\"robocide-game-trailer-voice\" target=\"_blank\" title=\"Robocide Game Trailer\">Robocide</a> videos.</p>', '<br>\r\n<h2>A little more about Goodgame Empire</h2>\r\n<p> <a href=\"https://empire.goodgamestudios.com\" target=\"_blank\" title=\"Good Game Empire\">Good Game Empire</a> is a beautiful-looking strategy game with plenty of complexity for gamers to get their teeth into. You can play it on mobile or as a flash game on you browser. I really like the way this game trailer turned out and I think the deep British voice is a great fit with this kind of video. We\'d been doing American movie voices for some time but this felt it needed something with a British voice. Staying deep, we tried this version with an British twist. Having seen the first cut, we refined the voice and the end result is rather... good!</p>', 'good-game-empire-trailer-voice.jpg', 'z6WhxrAwfWw', 'Good Game Empire Trailer Voice - Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this deep voice promo voice for your next trailer or <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV ad</a>? Please get in touch if you\'d like to work with me. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Dec 2013', '1', 'Good Game Empire Trailer', '3', '', 'Epic British Movie Trailer Voice', '', '', '', '', '', '', '', '', ''),
(479, 'sick-bricks-advert-voiceover', 'Sick Bricks Advert Voiceover', '<p>This is my Sick Bricks advert voiceover as seen on UK television in 2016. </p>', 'kids toys', 'Sick Bricks advert voiceover for tv - An outrageous world filled with crazy characters. All sorts of wacky folk inhabit the many neighbourhoods in Sick City', '<h2>TV Adverts</h2>\r\n<p>Once again I work on lots of the kids toys TV ads. Youthful, excited and fun is the brief. Piece of cake. I\'ll just be me! If you\'d like to see a few more examples of my kid\'s toy adverts, check out my <a href=\"bugs-in-kitchen-voice\" target=\"_blank\" title=\"Bugs in the Kitchen\">Bugs in the Kitchen</a> and <a href=\"pig-goes-pop-voiceover\" target=\"_blank\" title=\"Pig Goes Pop\">Pig Goes Pop</a> videos!<br>\r\nDo you have a TV advert for a kids product? How something like this Sick Bricks advert voiceover? Please get in touch via the contact page. </p>', '<h2>What is Sick City?</h2>\r\n<p>What is Sick City? It\'s the outrageous world of Sick Bricks filled with even crazier characters. Ninjas, Monsters, Aliens, Zombies, and all sorts of other wacky folk inhabit the many neighbourhoods in Sick City. But now this once peaceful city is being threatened by the vile Overlord Omega, and it is up to you and the heroic citizens to fight back against his goons to rebuild and restore every corner of the city to its former glory. Itâ€™s time for you to get sucked into the Sick Bricks game and battle to save Sick City!</p>', 'sick-bricks-advert-voiceover.jpg', 'tCv4y8q9Q78', 'Sick Bricks advert voiceover | TV Advert voiced by Guy', '<h2>Get in touch</h2>\r\n<p>Are you looking for a high energy voiceover artist for your next <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV ad</a>? or perhaps something a little more natural for an <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>? Please don\'t hesitate to get in touch if you\'d like to work with me. To make the process even easier, just let me know the intended length and usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice is right for your project. Please do get in touch today.</p>', 'Dec 2016', '1', 'Sick Bricks Advert Voiceover', '5', '%23SickBricks %23TVAdvert', 'Sick Bricks advert voiceover - seen on TV', '', '', '', '', '', '', '', '', ''),
(481, 'cloud-voiceover', 'Cloud voiceover', '<p>Heard of the Cloud? Check out the voiceover Explainer video for Microsoft</p>', 'microsoft explainer natural conversational', 'Conversational, natural tone for explainer videos and web content. Guy Harris voices daily for brands like Microsoft with fast WAV delivery.', '<h2>Explainer video voiceovers</h2>\r\n<p>On a weekly basis I voice stacks of these simple website videos. I love them. A well written script of no more than 2 minutes and great visuals will have your audience spending longer on your website than just a page of text.<br>\r\nThis Microsoft Cloud Explainer is one of my most referenced samples I get asked for. Alongside my <a href=\"apple-voice-style\" title=\"Apple TV adverts\"> Apple </a>and <a href=\"save-water\" title=\"Save Water Explainer\">Save Water</a> videos.\r\n</p>\r\n', '<br><h2>What is the Cloud?</h2>\r\n<p>\r\nThe Cloud makes it possible for IT to introduce new business-enhancing capabilities in less time and with lower cost. 80% of businesses experience a steady increase in productivity within the first six months in the cloud.<br>The cloud is a network of servers, and each server has a different function. Some servers use computing power to run applications or \"deliver a service.\"\r\n</i></p>', 'cloud-voiceover.jpg', 'LRvWnpX_c9g', 'Cloud voiceover - Cloud computing voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for a natural voice style like this for your own <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a>? Or perhaps you\'re working on a more energetic <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV ad</a>?  Please get in touch and let\'s work together. I\'d be very happy to send a short sample before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make the whole process as easy as possible with 99% of the jobs delivered back to you the same day.</p>', 'Jan 2014', '1', 'Cloud voiceover', '5', '%23TheCloud %23Microsoft %23ExplainerVideo', 'Voiceover Explainer video for Microsoft...', '', '', '', '', '', '', '', '', ''),
(492, 'vegetarian-society', 'Vegetarian society videos', '<p>Voiced a series of short videos with some cool animation for the Vegetarian society.</p>', 'explainer natural soft', 'Vegetarian society - Voiced a series of short videos with some cool animation for the Vegetarian society. Have you thought about being vegetarian?', '<br>\r\n<h2>A conversational delivery.</h2>\r\n<p>The script came to me and opened my eyes a lot more to what they stand for. The animation was also really well done. This was part of a series of films made to highlight the vegetarian lifestyle. I do love doing <a href=\"micropolitics-under-14-handball-team\" title=\"More info films\">information films</a> not only because of my fast turnaround and high quality delivery but also I get to learn everyday too. Check out my <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer videos page</a> to see a few more examples.\r\n</p>', '<br>\r\n<h2>Who are the Vegetarian society?</h2>\r\n<p>The Vegetarian Society is a registered educational charity offering support, advice and free resources. They influence, inspire and support people to embrace and maintain a vegetarian lifestyle. Working constructively with businesses, government agencies, policy makers and professionals, whilst always remaining independent. \r\n</p>', 'vegetarian-society.jpg', '3lXjR9PHaRg', 'Vegetarian society - Explainer Voiceovers by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for an explainer video or perhaps just for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV ad</a>? Please get in touch. I\'d be very happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Mar 2014', '1', 'Vegetarian society Videos', '0', '', 'The Vegetarian society Voice', '', '', '', '', '', '', '', '', ''),
(494, 'northern-gas-advert', 'Northern Gas Gameshow Voice', '<p>A short run on the TV for the Northern Gas Heating tv advert. I was asked for my British Gameshow voice.</p>', 'host cheesy', 'Northern Gas Advert - The client wanted a gameshow voice for their next television commercial. Super hero, Gameshow, Voice of God? Check out my site.', '<h2>Ladies and Gentlemen... Mr Gameshow!</h2>\r\n<p>I do plenty of character voices and although I could probably say I can do over 100 different styles, I like to focus on my stronger ones. One of which is my <a href=\"gameshow-host\" target=\"_blank\" title=\"Gameshow Host\">Gameshow host voice</a>. That cheesy 1980s style that was the backbone of a quiz shows as I grew up. <br>Today it\'s changed a bit and has less fromage, however, for comic effect, this does work nicely. As heard also on BBC Radio 1.\r\n</p>', '<br>\r\n<h2>Who are Northern Gas Heating?</h2>\r\n<p><a href=\"https://www.northerngasheating.com\" target=\"_blank\" title=\"Northern Gas Heating\">Northern Gas Heating</a> is a large energy company that has been around for over 15 years. They have a team of technical advisors experienced & qualified to design your individual heating system. They work with trusted companies to give you the highest quality of products. Confident about their service that all boilers come with a 10 year warranty. Choose from a variety of payment methods, all designed to suit your circumstances. This includes buy now/pay later and easy payment options.\r\n</p>', 'northern-gas-advert.jpg', 'M5BFBo3lF-4', 'Northern Gas Advert - Gameshow voice by Guy Harris', '<h2>Need some cheese?</h2>\r\n<p>Are you looking for a cheesy gameshow host voice? Perhaps something a little different for your next <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV ad</a>? Get in touch opposite and let\'s figure out what kind of voice you need for your next project! I\'d be very happy to send a sample before you book. Send a few lines of the script first so you can be sure I\'m right for your brand. I make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Mar 2014', '1', 'Northern Gas Advert', '0', '', 'Northern Gas Heating Gameshow voice', '', '', '', '', '', '', '', '', ''),
(499, 'save-water', 'Save Water Explainer', '<p>Every Last Drop. Another great Explainer Video Voiceover in use in an awesome animation</p>', 'natural soft conversational chatty every last drop', 'Voiceover for UK-wide water-saving campaign. Guy Harris brings a calm, clear, and friendly tone to encourage households to use less water and save energy.', '<h2>The search stops here</h2>\r\n<p>One of the most referenced demos on my website. So many emails start with \"Can we have it in the style of the Save Water demo?\"<br>\r\nIt was a great script to read and the producer was a joy to work with. He knew what he wanted and steered me to it.<br>The end result I couldn\'t wait to showcase here on my site. If you\' like to hear a few more explainer videos, check out my <a href=\"explainer-video-voice\" title=\"Explainer Videos\">Explainer Videos Page.</a></p>', '<br>\r\n<h2>Every last drop</h2>\r\n<p>This explainer video is part of the United Nations Save Water Campaign and it\'s such a great way to put such an important message across to all generations.<br>Saving water is so important and certainly something all generations need to consider. Now more than ever. I think this video has a very important message and I\'m glad my voiceover could play a part in getting this message out.</p>', 'save-water.jpg', 'YKIi_JvTB1Q', 'Save Water - Explainer Video Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this natural conversational voice style for your own explainer video? Or perhaps something a little more energetic for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a> ? Please get in touch. I\'d be very happy to send a short sample to you before you book me. Just send a few lines of the script first so you can be sure I\'m right for your brand. I make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'April 2014', '1', 'Save Water', '5', '%23savewater', 'Explainer Video voice about water', '', '', '', '', '', '', '', '', ''),
(512, 'land-of-eyas-voiceover', 'Land of Eyas Voiceover', '<p>Land of Eyas Voiceover, An unusual game playing around with the physics of gaming technology</p>', 'trailer', 'Land of Eyas Voiceover - An unusual game playing around with the phsyics of gaming technology - Voiced by Guy Harris - www.voiceoverguy.co.uk', '<h2>Another video game trailer for me</h2>\r\n<p>I voice a lot of game trailers across Xbox, Play Station, PC, and mobile platforms. So many great games are being made every week and good developers (with good marketing teams) know that they need to make a game trailer with a high production value. This is where I come in, as voiceover is the most important part of any game trailer. Otherwise, it\'s just footage from the game... If you\'d like to check out my voice on some other game trailers, watch the <a href=\"warwings-game-trailer-voice\" target=\"_blank\" title=\"Warwings\">Warwings</a>, and <a href=\"worms-wmd-character-voices\" target=\"_blank\" title=\"Worms WMD\">Worms WMD</a> game trailers.</p>\r\n', '<h2>A little more about Land of Eyas</h2>\r\n<p><a href=\"https://store.steampowered.com/app/299800/The_Land_of_Eyas/\" target=\"_blank\" title=\"Land of Eyas\">Land of Eyas</a> is a Steam and Xbox game that plays with gravity, and physics in general, in many different ways. This is very much a game built for big fans of the platform and action adventure genres. It\'s a game for people who\'ve played lots of these kinds of games and want something fresh that distorts and plays with the genre in several clever ways. It was great fun providing a slightly eccentric voiceover for this trailer, but then this seems appropriate as the game is more than a little eccentric itself!</p>', 'land-of-eyas-voiceover.jpg', '439KyoB033w', 'Land of Eyas Voiceover - voiceoverguy - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailer</a>? Please get in touch. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'May 2014', '1', 'Land of Eyas Voiceover', '0', '', 'Deep strange British VoiceOver ', '', '', '', '', '', '', '', '', ''),
(517, 'viva-cinema-voiceover', 'Viva Cinema Voiceover', '<p>In Bahrain you can now  skip the long queues at the cinema when you buy tickets online using VIVA Cinema website. Nice to voice for these guys.</p>', 'promo', 'Viva Cinema Voiceover - Now you can skip the long queues at the cinema when you buy tickets online using VIVA Cinema - Guy Harris - www.voiceoverguy.co.uk', '<h2>Voicing this explainer video for Viva Cinema, Bahrain</h2>\r\n<p>I do a surprising amount of work for companies based in the Middle East, such as this explainer for Viva Cinema and the work I did for Dubai Advantage. English is used as the lingua franca for so many countries around the World, which means that English voiceover artists like me can get a lot of work if they have a nice website and are easy to work with... I really liked working on this explainer video for Viva Cinema and I think it turned out really nicely. Explainers are becoming the main type of video I work on and I can see why. if you\'d like a few more examples of them, check out my <a href=\"eze-group-explainer-voice\" target=\"_blank\" title=\"Eze Group\">Eze Group</a> and <a href=\"batelco-wifi-voice\" target=\"_blank\" title=\"Batelco Explainer\">Batelco</a> (another company in Bahrain!) explainer videos. ', '<h2>A little more about Viva Cinema</h2>\r\n<p>Viva Cinema is Bahrain\'s leading cinema company, with six different cinemas scattered around the country. Viva Bahrain has done a lot to make sure their customers have access to all of the last films from around the World. They have also introduced the skip-the-line online feature I\'m describing in this explainer video. I think Viva Cinema is getting its branding and advertising just right and I\'m very pleased that my voiceover is being used in their ads. I\'d love to work with them again.</p>', 'viva-cinema-voiceover.jpg', 'E4IlxYsd90s', 'Viva Cinema Voiceover - Voice Over by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>? Please get in touch. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'May 2014', '1', 'Viva Cinema Voiceover', '0', '', 'Simple Step by step explainer voice', '', '', '', '', '', '', '', '', ''),
(519, 'minecraft-combat-voiceover', 'Minecraft Combat Voiceover', '<p>Another book from the Epic game Minecraft. This time I voice the trailer for the combat handbook. Still not played it yet.</p>', 'quirky', 'Minecraft Combat Voiceover - Another book from the Epic game Minecraft. This time it\'s the combat handbook - Voiced by Guy Harris - www.voiceoverguy.co.uk', '<h2>A Quirky voice</h2>\r\n<p> They wanted this one to have a little quirkiness to the read style. Almost a little bit like Simon from the InBetweeners. So, I sent a few voice samples and this is the one they approved. The script was very witty and well put together so it was a breeze to voice for them. Minecraft is one of the most successful games ever, so they had the budget to put great quality visuals and great music as well. I always like working with big companies because the higher production quality just makes my voiceover look even better. I think it turned out rather well. If you want to see more examples of game trailers and ads voiced by me, check out my <a href=\"siegecraft-commander-trailer-voice\" target=\"_blank\" title=\"Siegecraft Commander\">Siegecraft Commander</a>, <a href=\"the-escapists-game-trailer\" target=\"_blank\" title=\"The Escapists\">The Escapists</a>, and <a href=\"penarium-game-trailer-voice\" target=\"_blank\" title=\"Penarium\">Penarium</a> game trailers. </p>', '<br>\r\n<h2>What is the Minecraft Combat Handbook?</h2>\r\n<p><i>\r\n<a href=\"https://www.minecraft.net/en-us\" target=\"_blank\" title=\"Minecraft\">Minecraft</a> is a multi-platform block-based gaming sensation available on Xbox, PlayStation, PC and mobile devices. Whether you\'re in Creative, Survival or Hardcore Mode, the Minecraft books contain all the advice you need to survive and thrive! In Minecraft, youâ€™re never alone! There are dangers lurking around each and every corner. The Minecraft Combat Handbook is essential reading for Minecraft warriors.</i> There\'s something really fun about flicking through a physical gaming guide rather than just searching online and this book is the perfect present for anyone you know who loves Minecraft. It\'s an incredible game with so much depth to it. It was also great to work with Mojang, the company behind Minecraft.</p>', 'minecraft-combat-voiceover.jpg', 'TISd_9l7ZvA', 'Minecraft Combat Voiceover - voiceoverguy - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailer</a>? Please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a> if you\'d like to work with me. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'June 2014', '1', 'Minecraft Combat Voiceover', '5', '', 'Quirky voice for a Minecraft trailer', '', '', '', '', '', '', '', '', ''),
(521, 'animation-voiceovers', 'Animation Voiceovers', '<p>I have a plethora of animation voiceovers and I used several on this animation for Dreamcatchers.</p>', '', 'Animation Voiceovers - A plethora of character voices and several used on this animation: Dreamcatchers - Voiced by Guy Harris - www.voiceoverguy.co.uk', '<h2>Check out the video</h2>\r\n<p>The animation on this is awesome, so I\'m really happy <a href=\"https://www.youtube.com/watch?v=8P28Et7bPFI\" target=\"_blank\" title=\"Dreamcatcher\">Dreamcatcher</a> got in touch with me! This is only a pilot, but I\'d love to see the full movie. They asked me to pull a bunch of wacky character voices out of the bag and I think I did exactly what they asked for. Take a look at my <a href=\"character-voiceover\" target=\"_blank\" title=\"Character Voiceover\">character showreel</a> to hear more examples of what I can do. The voice session was really fun and while in most animations the characters are voiced first and then animated to match, this time we had to lip sync to the animation â€” which was a fun challenge.</p>', '<br><h2>Creating character voices.</h2>\r\n<p>As a voiceover artist, this is one of the most unpredictable jobs I\'ve ever had. I never know what work is going to come in and that means that I never do the same day\'s work twice! It does have many rewards. Being sent a script and character visuals and then asked to create a voice for it is an absolute pleasure. I\'ve done lots of voices for other cartoons, such as the <a href=\"santa-voice\" target=\"_blank\" title=\"Santa Voiceover\">voice of Santa</a> for the <a href=\"https://www.youtube.com/watch?v=yi-4Fm40nmE\" target=\"_blank\" title=\"Cbeebies GoJetter Christmas Special\">Cbeebies GoJetter Christmas Special</a>.</p>', 'animation-voiceovers.jpg', '8P28Et7bPFI', 'Animation Voiceovers - voiceoverguy - Guy Harris', '<h2>Get in touch</h2>\r\n<p>DoÂ you have an animationÂ or <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a> thatÂ needs a character voice ? Maybe I can help with someÂ animation voiceovers? Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the production to quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. This way you can check if my voice isÂ right for your show or project.</p>', 'June 2014', '1', 'Animation Voiceovers', '0', '', 'A plethora of animation voiceovers', '', '', '', '', '', '', '', '', '');
INSERT INTO `messages2` (`id`, `url`, `page_title`, `info`, `search_terms`, `page_desc`, `text1`, `text2`, `image`, `video`, `meta_title`, `bottomtext`, `date`, `whatvideo`, `alt`, `rating`, `twitter`, `hometext`, `santa`, `ntext1`, `ntext2`, `ntext3`, `ntext4`, `nimage1`, `nimage2`, `nimage3`, `nimage4`) VALUES
(523, 'best-male-voiceover', 'Best Male Voiceover', '<p>Nominated for the VOX Awards 2014 and won Best male voiceover. </p>', 'award winner winning', 'Award-winning British male voiceover by Guy Harris. Trusted by brands like Disney, Apple and ITV. Listen to demos across radio, TV, apps and trailers.', '<br><h2>Award winning voice</h2>\r\n<p>Amazing! Last time I won was 2011. I won with a promo I voiced for Sport Relief on BBC Radio 1. The VOX Awards are recognised in our industry and have been running for 20 years. The competition is organised by <a title=\"Voiceovers.co.uk\" href=\"https://www.voiceovers.co.uk\" target=\"_blank\">Voiceovers.co.uk</a> and I follow it every year, so I\'m so pleased that they\'ve given me the award for Best Male Voiceover this year! I think any voiceover artist gets work off the back of their portfolio, but it always helps to be recognised by the most prestigious awards! </p>', '<h2>A Little Information about the VOX Awards</h2>\r\n<p>The VOX Awards run every year, and they\'re usually held in October. What makes the  VOX Awards so special is that they focus on voiceover, celebrating and focusing on the industry\'s various different areas. Here\'s a rough, but not exhaustive list of the awards: <br>\r\n- Best Male Voiceover Performance <br>\r\n- Best Female Voiceover Performance <br>\r\n- Best Use of Humour <br>\r\n- Best Character Performance <br>\r\n- Best Use of Music <br>\r\n- Best Visual Advertising Campaign</p>\r\n', 'best-male-voiceover.jpg', '', 'Best Male Voiceover - Winner at Vox Awards 2014', '<h2>Get in touch</h2>\r\n<p>Are you looking for a voice over for your next big <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">advertisement</a>? One with credibility and experience? One with all kinds of impressive VOX Awards to their name? Please feel free to fill in the form and get in touch. I\'d be veryÂ happy to send a sample of your script before you book me. Simply send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'June 2014', '2', 'Best Male Voiceover', '0', '', 'VOX Awards - WON Best male voiceover.', '', '<h2>A Little More about Voiceover Awards</h2>\r\n<p>As I said before, it\'s mainly a voiceover artist\'s showreels that secure most of our work. It\'s my numerous <a href=\"santa-voice\" target=\"_blank\" title=\"Santa Voiceover\">Santa voiceover jobs</a>, for example, that ensure I get asked to do more work the following Christmas! And it\'s my extensive experience with <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a> that have encouraged new clients to get in touch. However, the awards can help some us shine a little brighter than the others and it\'s always great to be recognised by my peers. I have won 3 VOX Awards in the past and I\'ve even been a finalist on three different occasions for the larger SOVAS (the Voice Arts Awards in Hollywood).', '', '', '', '', '', '', ''),
(525, 'joker-voice', 'The Joker Voice', '<p>Love The Dark Knight? So did I â€” thatâ€™s why I had to master Heath Ledgerâ€™s legendary Joker voice. Whether itâ€™s a Halloween promo, twisted trailer or character parody, Iâ€™ve got the cackle covered.</p>', 'joker voice, dark knight voice, halloween voiceover, batman villain', 'Need a Joker-style voiceover for Halloween or a twisted promo? Hereâ€™s my tribute to Heath Ledgerâ€™s iconic villain in The Dark Knight â€“ ready 2 haunt your script', '<h2>What a Joker!</h2>\r\n<p>I couldnâ€™t resist syncing my voice to one of the most iconic villains of all time. Iâ€™ve studied the laughs, the chaos, and the eerie calm. Jokerâ€™s a character with depth â€” and voicing him has been one of my favourite challenges.<br>\r\nYouâ€™ll also find me bringing creepy voices to life for <a href=\"halloween-voice\" target=\"_blank\" title=\"Halloween Voiceovers\">Halloween campaigns</a> across TV and radio. Want something similar? Check out my <a href=\"character-voiceover\" target=\"_blank\" title=\"Character Voiceover Showreel\">character showreel</a> for more.</p>', '<h2>Incredible Bad Guys</h2>\r\n<p>Heath Ledger gave us one of the most iconic villains of all time. And while Iâ€™m no Oscar-winner, Iâ€™ve been lucky to voice some truly twisted characters over the years. From <a href=\"scary-movie-ghost-face-voice\" title=\"Ghost Face Scream Voice\">Ghost Face in Scream</a> to <a href=\"https://www.voiceoverguy.co.uk/dracula-voiceover-for-halloween\" title=\"Dracula Voiceover\">Count Dracula</a>, my Halloween roster is full of creepy legends.<br><br>\r\n\r\nIf you\'re planning a promo, trailer or haunted event, I can provide a Joker-style voice or something even more terrifying. Why not pair it with a <a href=\"https://www.voiceoverguy.co.uk/spooky-halloween-laughs\" title=\"Spooky Laughs\">signature spooky laugh</a> or go full <a href=\"https://www.voiceoverguy.co.uk/evil-character-voiceover\" title=\"Evil Character Voice\">evil villain</a>? Letâ€™s give your audience the creeps â€” in the best possible way.</p>', 'joker-voice.jpg', 'aSkVQ6lNwH4', 'Joker Voice â€“ Dark Knight Style Voiceover | Guy Harris', '<h2>Letâ€™s put a smile on that script</h2>\r\n<p>Need a spooky Joker voice for a Halloween promo or a villainous campaign? Iâ€™ll record it fast from my broadcast studio. Send over the script or just your idea â€” Iâ€™ll make it sinister. <a href=\"contact-guy\" title=\"Contact VoiceoverGuy\">Get in touch</a> and letâ€™s add a little chaos to your next project.</p>', 'July 2014', '1', 'Heath Ledger Joker Voice â€“ Scary Halloween Voiceover', '3', '%23Joker %23batman', 'Chilling Joker Voiceover â€“ Heath Ledger Tribute', '', '<h2>More Scary Voices Where That Came From</h2>\r\n<p>My Joker impression is just one trick from my spooky bag of voiceover treats. Iâ€™ve also been the <a href=\"https://www.voiceoverguy.co.uk/david-attenborough-impression\" title=\"David Attenborough Voice Spoof\">David Attenborough of the undead</a>, voiced <a href=\"https://www.voiceoverguy.co.uk/alton-towers-scarefest-spooky-voice\" title=\"Alton Towers Scarefest Voice\">Alton Towers Scarefest</a> promos, and created bone-chilling <a href=\"https://www.voiceoverguy.co.uk/wilhelm-scream-shreek-shout-sfx-voiceover-film\" title=\"Wilhelm Scream\">screams and horror SFX</a> for trailers and games.</p>', '', '', '', 'character-voiceovers.jpg', '', '', ''),
(528, 'thomas-friends-voiceover', 'Thomas Friends Voiceover', '<p>Tale of the Brave the colouring and sticker book. This ad plays in UK Cinemas to Thomas fans</p>', 'TVC energetic happy', 'Thomas Friends Voiceover - Tale of the Brave the colouring and sticker book. This ad plays in UK Cinemas to Thomas fans - www.voiceoverguy.co.uk', '<h2>Working with trains.</h2>\r\n<p>I grew up with Thomas and my <a href=\"http://www.voiceoverbaby.co.uk\" target=\"_blank\" title=\"VoiceoverBaby\">daughter</a> is starting to get fascinated with trains so I\'m sure he\'ll play a big part in my life again for years to come. So when I was asked to voice this, I couldn\'t resist to add <a href=\"https://www.egmont.com\" target=\"_blank\" title=\"Egmont Website\">Egmont</a> to my CV. They wanted a upbeat and energetic read for this and thats what they got. I do seem to get a lot of this kind of work. Thank you Mr Tank Engine.\r\n</p>', '<br>\r\n<h2>Thomas the Tank Engine</h2>\r\n<p>The colouring and sticker book. Thomas discovers a mysterious footprint in the clay pits and everyone is curious about where it came from. Poor Percy is just scared! Can a new friend convince Percy there is no such thing as monsters or will his fear lead him to leave Sodor Island forever?!\r\n</p>', 'thomas-friends-voiceover.jpg', 'LUZo3iLO-xI', 'Thomas Friends Voiceover - voiceoverguy - Guy Harris', '<h2>Can I voice for you?</h2>\r\n<p>Got a project that needs a voice? Do get in touch and lets chat. I\'d be veryÂ happy to send a short sample of your script before you book me, so you can be sure I\'m right for your brand. TheÂ whole process is easy with 99% of the jobs delivered the same day.</p>', 'July 2014', '1', 'Thomas Friends Voiceover', '3', '', 'Tale of the Brave sticker book...', '', '', '', '', '', '', '', '', ''),
(534, 'judgment-apocalypse-survival-voice', 'Judgment Apocalypse Survival', '<p>The Judgment Apocalypse Survival Voice over for the trailer. You can pretty much gather I love voicing trailers.</p>', 'Soft American', 'Judgment Apocalypse Survival Voice - The Apocalypse is here. Demons all around. Build, manage and defend your base in a post apocalyptic colony simulation', '<h2>Game Trailer Voice</h2>\r\n<p>So, as a native British male voiceover artist it\'s fun to bring out the <a href=\"https://www.voiceoverguy.co.uk/character-voiceover\" target=\"_blank\" title=\"character voices\">character voices</a> like this dark menacing one for Judgement Apocalypse Survival. I love providing voiceover for <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailers</a> and this especially fun because I got to try my most grizzled American voice. In fact, this voice sounds a lot like the \'In a world...\' <a href=\"movie-trailer-voice\" target=\"_blank\" title=\"Movie Trailer Voiceover\">movie trailer voice</a> we all know and love so much. The game looks pretty good and the reviews seem positive, which makes it all the more fun to be part of. If you\'d like to hear a couple more examples of similar work, check out my <a href=\"warwings-game-trailer-voice\" target=\"_blank\" title=\"Warwings\">Warwings</a> and <a href=\"lifeless-game-trailer-voice\" target=\"_blank\" title=\"Lifeless Game Trailer\">Lifeless</a> videos. </p>', '<h2>What is the game all about?</h2>\r\n<p><i>The Apocalypse is here. Demons all around. Now, itâ€™s time to fight back! Build, manage and defend your base in a post apocalyptic colony simulation. <br>\r\nWill you survive Judgment day?</i> <a href=\"https://www.judgmentgame.com/\" target=\"_blank\" title=\"Judgement Apocalypse Survival\">Judgement Apocalypse Survival</a> is an extremely impressive new game from Suncrash Studios. The game is available on Steam and it has very high critic scores, so it\' must be as good as it looks!</p>', 'judgment-pocalypse-survival-voice.jpg', '6YcpADKL15U', 'Judgment Apocalypse Survival Voice | Trailer by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Do you have a <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">trailer</a> or <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo</a> in need of a voice?<br>\r\nHow something like this Judgment Apocalypse Survival Voice? Please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a><br>\r\nTo make the process even easier, just let me know the intended length and usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice is right for your project. <br>\r\nPlease do get in touch today.</p>', 'Dec 2016', '1', 'Judgment Apocalypse Survival Voice', '3', '%23Judgement %23gametrailer', 'Deep Soft American Trailer Voice', '', '', '', '', '', '', '', '', ''),
(536, 'spiderman-car-voiceover', 'Spiderman Car Voiceover', '<p>Working with Smyths Toys Superstores again this month on another TV adverts - The awesome Spiderman Car</p>', 'kids toys', 'Spiderman car Voiceover - Working with Smyths Toys Superstores again on more TV adverts - Spiderman Car - Voiced by Guy Harris - www.voiceoverguy.co.uk', '<h2>My voice on Smyths\' Spiderman car advertisement</h2>\r\n<p>I get a lot of work in the toy industry, voicing the <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo videos</a> for dozens of kids\' toy ads each year, and it\'s great to add this Spiderman car ad to the list. I guess I have the right kind of voice for this type of ad because more and more companies are getting in touch to ask me to work with them. I\'ve worked with Smyths Toys a few times before and we seem to have a good working relationship. So I\'m sure we\'ll work with each other plenty of times in the future. If you\'d like to hear a few more examples of my kids\' toy commercial voiceover, check out my <a href=\"girafun-voiceover\" target=\"_blank\" title=\"Giraf Fun\">Giraf Fun</a> and <a href=\"pig-goes-pop-voiceover\" target=\"_blank\" title=\"Pig Goes Pop Voiceover\">Pig Goes Pop</a> videos.</p>', '<h2>A little more about Smyths Toys</h2>\r\n<p><a href=\"https://www.smythstoys.com\" target=\"_blank\" title=\"Smyths Toys\">Smyths Toys</a> is the biggest chain of toy stores in Ireland and the UK right now. Its headquarters are in Galway, in Ireland, and it has over 110 stores dotted around the UK and Ireland. Anyone who\'s been in a Smyths store knows how special they are. There\'s always a huge range of the latest toys and they are always updating their collection. This Spiderman car is one such update and it looks great. Smyths do some really great ads and it\'s always a pleasure to work with them.</p>', 'spiderman-car-voiceover.jpg', 'kQlB8iO4ZUc', 'Spiderman car Voiceover - Smyths Toys - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a> or perhaps for an <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>? Please get in touch. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'July 2014', '1', 'Spiderman Car Voiceover', '0', '', 'British Promo voice for Smyths', '', '', '', '', '', '', '', '', ''),
(538, 'fruitella-voiceover', 'Fruitella Quirky TV adverts', '<p>A really funny series of the TV adverts for sweets Fruitella. \"You can Tella it\'s Fruitella\"</p>', '', 'Guyâ€¯Harris voices the Fruitella TV adverts. Bright, fun, memorable â€” ideal if your brand wants a voice that smiles.', '<h2>Voicing the hilarious Fruitella TV ads</h2>\r\n<p>I had a few friends call me up to ask if it was my voice on the hilarious Fruitella ads. I was very pleased to tell them that it was. As is often the case for sweets and kids\' toys promos, I was asked for a wacky, fun voice and I think I\'ve delivered that. These ads are a lot of fun and they seem to be going down a treat. I love a bit of comedy and I\'m always happy when a voiceover script is full of gags. If you want to hear similar examples of my voiceover work, check out my <a href=\"domino-express-voice-over\" target=\"_blank\" title=\"Dominoes Express\">Dominoes Express</a>, <a href=\"https://www.youtube.com/watch?v=tXTUPXCCwd8\" target=\"_blank\" title=\"Disney Parks\">Disney Parks</a>, and <a href=\"farm-heroes-saga-voiceover\" target=\"_blank\" title=\"Farm Heroes Saga\">Farm Heroes Saga</a> videos. </p>', '<h2>A little more about Fruitella</h2>\r\n<p><a href=\"https://www.fruittella.co.uk\" target=\"_blank\" title=\"Fruitella\">Fruitella</a> barely needs an introduction. It\'s one of the most popular sweets in the UK and it is well known for it\'s hilarious TV ads. Most of us remember the iconic \'I\'m too juicy\' adverts that took the song by Right Said Fred and changed the word \'sexy\' to \'juicy\'. I daresay some people even preferred Fruitella\'s version of the song... It was great to work with this great brand and I\'d be more than happy to work with them again in the future. </p>', 'fruitella-voiceover.jpg', 'hI0n9aVFaTw', 'Fruitella Voiceover - The TV Adverts 2014 - Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo video</a>? Please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Aug 2014', '1', 'Fruitella Voiceover', '0', '', 'Slight MAD voice for Fruitella...', '', '', '', '', '', '', '', '', ''),
(541, 'saturday-night-takeaway-voice', 'Saturday Night Takeaway Voice of God', '<p>My most exciting voice over gig. The Saturday Night Takeaway Tour Voice of God. Front row tickets in Leeds thrown in too.</p>', 'ITV ant dec ', 'Saturday Night Takeaway voice - Such an awesome show with Ant & Dec OBE\'s - I provided the Voice of God Voice elements for the Takeaway Tour Aug - Sept 2014', '<h2>Voice of God Announcer</h2>\r\n<p>Every week I\'m asked to provide my voice for events, shows or award ceremonies. Whilst the work steps up towards the end of the year, through the rest of the 12 months there is always something to voice or be a part of.<br>The <a href=\"voice-of-god\" target=\"_blank\" title=\"Voice of God Voiceover\">Voice of God</a> is the name for that big, booming announcer\'s voice you hear at large events and it\'s something I\'ve provided for numerous events such as the Pure Beauty Awards and The Voice of God for Butlins shows and announcements for the last 8 years.</p>', '<br>\r\n<h2>Cost effective voice over</h2>\r\n<p>It was great fun providing the voiceover for Saturday Night Takeaway\'s live show, which I recorded ahead of time. <br>I\'m more than happy to provide LIVE voice-of-god services, however, pre-recording can save you money.<br>\r\nWith a full <a href=\"voiceover-studio\" target=\"_blank\" title=\"Guy\'s Studio\">professional studio</a> and high-quality recording equipment, let me record the audio and send as a WAV or mp3.<br>\r\nEven if the event line up changes at the last minute, it\'s not a problem to record new lines ahead of the event.\r\n</p>', 'saturday-night-takeaway-voice.jpg', 'W99pMUr6G8Q', 'Saturday Night Takeaway voice - Tour Voice of God', '<h2>How can I get a Voice of God?</h2>\r\n<p>Are you looking for a voice of God? Or perhaps you need something softer and more natural for a <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV ad</a> or <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>.  Please get in touch. I\'d be veryÂ happy to send a short sample of your script before you book me. Just send a few lines of the script first so you can be sure I\'m right for your event. 99% of the jobs delivered the same day.</p>', 'Aug 2016', '1', 'Saturday night takeaway voice of God', '5', '', 'Live across UK Arenas', '', '', '', '', '', '', '', '', ''),
(544, 'gibtelecom-voiceover', 'Malta\'s Gibtelecom Voice', '<p>This time, a much softer voiceover for this great telecommunications company in Gibraltar</p>', '', 'Gibtelecom Voiceover - A softer voiceover for this telecommunications company in Gibraltar - More styles and character Voices... check out VoiceoverGuy.co.uk', '<h2>Gibtelecom TV and web promo</h2>\r\n<p>I\'ve done a lot of voiceover jobs for companies in different countries. It doesn\'t matter whether it\'s <a href=\"viva-bahrain-voiceover\" target=\"_blank\" title=\"Viva Bahrain Voiceover\">telecoms in Bahrain</a> or an <a href=\"air-malta-voiceover\" target=\"_blank\" title=\"Air Malta\">airline based in Malta</a>, brands all over the World need good English voiceover to sell their products and services to a global market. And that\'s what Gibetelcom has done here. Gibraltar is a British territory and they speak English, but they speak other languages too. They needed my voiceover to be crisp, clean, and clear for their message â€” which is usually the case with internet and telecoms companies. </p>', '<h2>A little more about Gibtelecom</h2>\r\n<p>Gibtelecom is Gibraltar\'s leading telecoms provider and their quite a big deal on this small island. It\'s important for countries with smaller populations to have the same access to high-speed internet as the rest of the World, and this is  exactly what Gibtelecom has achieved. This is a great company and it was a pleasure to work with them on this promo video. \r\n<br>\r\nI love working with companies all over the World, so I\'m always happy to receive a call with a dialing code I don\'t recognise.</p>', 'gibtelecom-voiceover.jpg', 'x6a3cQ35KyE', 'Gibtelecom Commercial Voiceover - Guy â€“ Trusted UK VO', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your next <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover</a> or <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>? Please get in touch. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Aug 2014', '1', 'Gibtelecom Voiceover', '0', '', 'Deep Calm Male Voiceover', '', '', '', '', '', '', '', '', ''),
(545, 'domino-express-voice-over', 'Energetic English voice over', '<p>I was asked to provide the Domino Express voice over on the television advert. </p>', 'kids toys Energetic', 'Energetic, playful delivery for kidsâ€™ toys and TV ads. As the voice of John Adamsâ€™ Domino Express, Guy Harris brings fun and excitement to every read.', '<h2>Kids toys on TV</h2>\r\n<p>Looking for an energetic read for your kid\'s toy advert? If you go back through this blog and type \'kids\', you\'ll see I voice a lot of <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV ads</a> for children toy companies. I think my voice is a great fit for this market, and it\'s why I keep getting jobs in the toy industry. Normally by the end of the voice session I\'m exhausted due to how hyper I\'m needed to be but it\'s always a pleasure. If you\'d like a few more examples of my toy commercials, check out my <a href=\"bugs-in-kitchen-voice\" title=\"Bugs in the Kitchen Voiceover\">Bugs in the Kitchen</a> and <a href=\"pop-up-pirate-voiceover\" title=\"Pop-up Pirate Voiceover\">Pop-up Pirate</a> videos. When my daughter is older, I\'ll be kicking myself that I\'m directly selling to her and making me broke in the process!\r\n</p>\r\n', '<br>\r\n<h2>Domino Express the Game</h2>\r\n<p>Stack them up and tumble them down.; Race 2 domino tracks head to head.; With 150 dominoes, including easy set, flip up speed sections, a staircase grid start, 2 x 360Â° loopers, 2 domino race cars, a ball dropper and a ring of fire. You\'ll find Domino Express at all the best toy stores.</p>', 'domino-express-voiceover.jpg', '_he4Cnt2VxA', 'Domino Express voiceover - Kids Toys TV Advert Voice', '<h2>Get in touch</h2>\r\n<p>Are you looking for a style similar to this voice? Perhaps a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial voiceover</a> or <a href=\"game-trailer-voice\"  title=\"Game Trailer Voiceover\">game trailer voiceover</a> with the same kind of energy? Please get in touch. I\'d be veryÂ happy to send a short sample before you book me. Just send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Aug 2014', '1', 'Domino Express Voiceover', '0', '', 'Domino Express voice over on Telly!', '', '', '', '', '', '', '', '', ''),
(553, 'pig-goes-pop-voiceover', 'Pig goes Pop Voiceover', '<p>I love working with John Adams Toys on their tv commercials.</p>', 'promo kids toys', 'Pig goes Pop Voiceover - Voicing for John Adams Toys on their TV Ads. From Doggie Doo, Silly Moo and Gooey Louie and now a new one - VoiceoverGuy.co.uk', '<h2>Kids tv adverts</h2>\r\n<p>If you\'d had the television on over Christmas, there is no doubt you would have heard me on the many Children\'s tv commercials. <br>\r\n From <a href=\"doggie-doo-voice-over\" title=\"Doggie Doo\">Doggie Doo</a>, <a href=\"silly-moo-voiceover\" title=\"Silly Moo\">Silly Moo</a> and <a href=\"gooey-louie-voiceover\" title=\"Gooey Louie\">Gooey Louie</a>, to this crazy new one.<br>I can bring that fun and energy to the ad that it requires. I can\'t wait till my daughter is old enough to recognise them. <br>\r\nOf course I hope I am still voicing them.\r\n</p>', '<br>\r\n<h2>What is Pig goes Pop?</h2>\r\n<p>With <a href=\"https://www.smythstoys.com/uk/en-gb/toys/games-puzzles-and-books/board-games/children-s-board-games/pop-the-pig-board-game/p/199637\"_blank\" title=\"Pig Goes Pop\">Pig Goes Pop</a>, the tension will mount as you continuously feed burgers to the greedy pig. Watch his stomach get bigger and bigger and be prepared for when he finally goes pop! A fun-filled game which will have your children shrieking with laughter!<br>\r\nFeed burgers to the pig and watch his tummy grow until he pops.<br>\r\nHis arms snap out and his jacket flys open!</p>', 'pig-goes-Pop-Voiceover.jpg', 'z9wcz5wr4vM', 'Pig Goes Pop Game â€“ Toy Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a>? Perhaps you have a toy you\'d like to promote with the help of the <a href=\"santa-voice\" title=\"Santa Voiceover\">voice of Santa</a>?  Or one with a similar amount of energy to this for pig goes pop? Please <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a>. Let me send a short sample of your script to you before you book me. Send a few lines of the script, so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Sep 2014', '1', 'Pig goes Pop Voiceover', '3', '', 'Quirky British Voiceover', '', '', '', '', '', '', '', '', ''),
(555, 'boom-beach-hammerman-voice', 'Boom Beach Hammerman Voiceover', '<p>Voicing Hammerman for Boom Beach was a blast. As a character voice artist, Iâ€™ve worked on many gaming projects, but bringing this blackguard commander to life for SuperCell was a standout. Here\'s how it all came together.</p>\r\n', 'character', 'Meet Hammerman. Guy Harris voices Boom Beachâ€™s iconic baddie with energy and menace. Game villainy at its finest, straight from the battlefield.', '<h2>Voicing Boom Beach Videos</h2>\r\n<p>This was one of my favourite voiceover sessions. Not only am I a fan of the game, but I kept seeing Boom Beach trailers pop up on my socials â€” and always wanted to voice one of them. Then along came the chance.</p>\r\n\r\n<p>It was brilliant fun having to lip-sync Hammermanâ€™s lines so the animators could match the characterâ€™s mouth to mine. Seeing the final version confirmed what I already suspected â€” <strong>SuperCell</strong> are absolute legends when it comes to game development and animation.</p>\r\n\r\n<p>Iâ€™ve voiced a few <a href=\"https://www.voiceoverguy.co.uk/character-voiceover\" title=\"Character voiceover sessions\">character voices</a> over the years, and this one stands out. If you\'re casting a new project, you might also enjoy my work on <a href=\"https://www.voiceoverguy.co.uk/lifeless-game-trailer-voice\" title=\"Lifeless Game Trailer Voice\">Lifeless</a> or the brilliantly chaotic <a href=\"https://www.voiceoverguy.co.uk/penarium-game-trailer-voice\" title=\"Penarium Game Trailer Voice\">Penarium</a>.</p>\r\n\r\n<p>Want something voiced in this style? Take a look at my <a href=\"https://www.voiceoverguy.co.uk/game-trailer-voice\" title=\"Game trailer voiceover demos\">Game Trailer Voice</a> page, or <a href=\"https://www.voiceoverguy.co.uk/contact-guy\" title=\"Contact VoiceoverGuy\">get in touch</a> if you\'d like to hear a short sample first. I\'m more than happy to help.</p>\r\n', '<h2>Who is Hammerman in Boom Beach?</h2>\r\n<p>Hammerman is the blackguard commander and one of the key villains in Boom Beach. With a blocky square nose, a battle-scarred left eye, and a military-grade scowl, heâ€™s not exactly what youâ€™d call approachable.</p>\r\n\r\n<p>Hammerman is known for launching full-scale attacks from multiple enemy bases scattered across the archipelago, dubbed â€œHammermanâ€™s HQ.â€ Heâ€™s the thorn in every playerâ€™s side, turning up uninvited and smashing your base to bits.</p>\r\n\r\n<p>If you fancy diving deeper into his evil escapades, youâ€™ll find a full breakdown on <a href=\"https://boombeach.fandom.com/wiki/Lt._Hammerman\" target=\"_blank\" title=\"Hammerman Boom Beach Fandom\">Boom Beach Fandom</a> and on <a href=\"https://supercell.com/en/games/boombeach/\" target=\"_blank\" title=\"Official Boom Beach site\">Supercellâ€™s official site</a>.</p>\r\n\r\n<p>Iâ€™ve voiced Hammerman in several versions over the years, including the gloriously bizarre <a href=\"/boom-beach-hammerman-hot-tub-voice\" title=\"Hammermanâ€™s Hot Tub Voice\">Hot Tub edition</a>. Yep, heâ€™s a villain who apparently enjoys a soak. Honestly, voicing characters like this is what makes <a href=\"/character-voiceover\" title=\"Character voiceover work\">character voiceover work</a> so much fun.</p>\r\n', 'boom-beach-hammerman-voice.jpg', 'JId2ODYrXq4', 'Boom Beach Hammerman Voice â€“ Guy Harris Character VO', '<h2>Need a Character Voice Like Hammerman?</h2>\r\n<p>If youâ€™re creating a game or animation and need a memorable <a href=\"/character-voiceover\" title=\"Character voiceover\">character voiceover</a>, Iâ€™d love to help. Voicing characters like Hammerman is always a joy â€“ whether it\'s for villains, heroes, or something completely off-the-wall. If you\'re not quite sure what voice you need, I\'m happy to offer a short demo before you book me.</p>\r\n\r\n<p><a href=\"mailto:guy@voiceoverguy.co.uk?subject=Character%20Voice%20Enquiry\" title=\"Contact Guy\">Drop me a line</a>, let me know what youâ€™re working on, and weâ€™ll see if my voice is the right fit. Iâ€™ve worked with brilliant teams like Supercell, and I aim to turn around most projects within 24 hours.</p>\r\n\r\n<p>And if you\'re just browsing, feel free to explore more of my <a href=\"/character-voiceover\" title=\"Character Voiceover Styles\">character voiceover styles</a> and <a href=\"/game-trailer-voice\" title=\"Game Trailer Voiceovers\">game trailer voiceovers</a>. You might find just the tone youâ€™re after!</p>\r\n', 'Sep 2014', '1', 'Boom Beach Hammerman character voice by Guy Harris', '5', '', 'Boom Beach video Hammerman Voice', '', '', '', '', '', '', '', '', ''),
(558, 'pathe-news-voiceover', 'Pathe News Voiceover', '<p>Working with Film maker Natasha Stanbridge this is a fine example of my Pathe News Voice. Try this 1940\'s voice.</p>', '', 'Pathe News Voiceover - Working with Film maker Natasha Stanbridge this is a fine example of my Pathe News Voice. Try this 1940\'s voice - VoiceoverGuy.co.uk', '<h2>Pathe News Voice</h2>\r\n<p>The voice of Pathe News ran for years and years. It\'s certainly a distinctive sound. Some people often simply think of this voice as the classic BBC voice. If you\'re searching for the right voice to bring some magic to a production that has a vintage look or feel to it, maybe we can work together. I\'m always happy to audition a few lines first to check its right for your product or production. I also have a dedicated <a href=\"pathe-news-voice\" target=\"_blank\" title=\"Pathe new Voice\">Pathe News Voice</a> with more examples of my work, such as when I worked with <a href=\"horlicks-promo-voice\" target=\"_blank\" title=\"Horlicks\"> Horlicks </a></p>', '<h2>A little more about the Pathe News voice<h2>\r\n<p>The Pathe Voice was the main sound of Britain during the early-to-mid 20th century and its sound is incredibly evocative of WWI and WWII as it was used a lot in war films in the decades after WWII. There is something nostalgic about this voice style that seems old-fashioned (but in a good, wholesome way) and this makes it perfect for <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo videos</a> selling products that tap into any sense of British nostalgia. i love doing this voice and I\'m always happy to bring it out of the box for a new project.</p>', 'pathe-news-voiceover.jpg', 'WwezBdZv2F4', 'Pathe News Voiceover â€“ 1940s Style by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style? Perhaps for an <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a> instead of a commercial? Please get in touch. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Nov 2014', '1', 'Pathe News Voiceover', '0', '', 'A splendid 1940\'s Pathe News Voice', '', '', '', '', '', '', '', '', ''),
(563, 'michael-caine-voiceover', 'Michael Caine Voiceover', '<p>Warner Bros approved my impression of Michael Caine as the voice of Alfred for the latest slots game for the Dark Knight Trilogy.</p>', 'character impression', 'Michael Caine Voiceover Impression - Officially Warner Bros approved as the voice of Alfred for the latest slots game by IGT for the Dark Knight Trilogy.', '<h2>Michael Caine Impression</h2>\r\n<p>I am so excited to see the result of this. Having watched Rob Brydon and Steve Coogan battle it out as to who had the best Michael Caine impersonation prior to my session, I was really feeling the vibe for the character. Michael\'s voice has slowed down over the years, and he now delivers a softer more laid back approach. Anyway, let me \"blow ya bloody doors off\". It\'s always nice to try a different impression and add it to my repertoire. You might also like to check out my <a href=\"david-attenborough-voice\" target=\"_blank\" title=\"David Attenborough Voiceover\">David Attenborough impression</a>.</p>', '<br><h2>Dark Knight Slots by IGT</h2>\r\n<p>Back in 2015 I voiced the 1st version for the game in the USA for IGT. This video shows the 1st game in action. <br>Found stateside, one of these machines sits in one of the big casinos in Las Vegas.<br>The next time I\'m over there, I need to find it and play it. I was led to believe these were staying only in the USA. This isn\'t the kind of game I\'m used to voicing; check out my <a href=\"robocide-game-trailer-voice\" target=\"_blank\" title=\"Robocide Trailer\">Robocide</a> and <a href=\"the-escapists-game-trailer\" target=\"_blank\" title=\"The Escapists\">The Escapists</a> game trailers. </p>', 'michael-caine-voiceover.jpg', 'VUJK7CTLZyI', 'Michael Caine impression - voiceover by Guy Harris', '<h2>Do say hello</h2>\r\n<p>Are you looking for an impression? A voice of Michael Caine? Or perhaps one of my <a href=\"character-voiceover\" target=\"_blank\" title=\"Character Voiceover\">character voiceovers</a> or one of my <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailer voiceovers</a>? Please get in touch. I\'d be veryÂ happy to send a short sample before you book me. Simply send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Jan 2015', '1', 'Michael Caine Voiceover', '0', '', 'Authentic Michael Caine for Warner Bros', '', '', '', '', '', '', '', '', ''),
(564, 'kings-road-voiceover', 'Kings Road Voiceover', '<p>Another awesome game using my <a href=\"movie-trailer-voice\" target=\"_blank\" title=\"Movie Trailer Voiceover\">UK Movie trailer voice</a>.</p>', 'movie trailer english', 'Kings Road Voiceover - Another awesome game and my English Movie Trailer trailer voice fits nicely. Click for a stack of other movie trailer voiceovers USA & UK', '<h2>English Movie Trailer Voice</p>\r\n<p>The client wanted something deep, dark and with impact. <br>\r\nWe auditioned various styles in the session, however this deep British voice seemed to suit the trailer.<br>\r\nThis is just another of the many <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">video game trailers</a> I am asked to voice regularly. If you\'d like to see more examples, check out my <a href=\"warwings-game-trailer-voice\" title=\"Warwings Game Trailer\">Warwings</a>, <a href=\"the-escapists-game-trailer\" title=\"The Escapists Game Trailer\">The Escapists</a>, and <a href=\"penarium-game-trailer-voice\" title=\"Penarium Game Trailer\">Penarium</a> game trailers.</p>', '<br>\r\n<h2>What is King\'s Road?</h2>\r\n<p><i>Team up to save Alderstone and battle against the forces of darkness with seamless drop-in, drop-out cooperative play. <br>\r\nPlay with your friends or quickly find a game in matchmaking.\r\nKings Road is a browser-based massively multiplayer online role-playing game made by Rumble Entertainment. The story line of the game is similar to a fairy tale. In the absence of the king, a kingdom was captured by some evil enemies.</i> I think this game looks great and I\'m very pleased with the deep, gravelly voice me and my clients settled on for the trailer. I think it\'s the perfect fit.</p>', 'kings-road-voiceover.jpg', 'Af5szC15B_8', 'Kings Road Voiceover - Game trailer by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for your upcoming <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailer</a> or <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a>? Please <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a> if you\'d like to work with me. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Jan 2015', '1', 'Kings Road Voiceover', '3', '', 'A UK Movie Trailer Voiceover', '', '', '', '', '', '', '', '', ''),
(567, 'sage-one-payroll-voiceover', 'Sage One Payroll Voiceover', '<p>This is the Sage One Payroll Voiceover following signing up with SAGE to continue into 2015 with more voiceovers for their web and explainer videos. </p>\r\n', '', 'Sage One Payroll Voiceover - Signed up with SAGE to continue into 2015 with more voiceovers for their product web & explainer videos - Voiced by Guy Harris', '<h2>Check out the video</h2>\r\n<p>This is a pretty nifty little explainer video from Sage One Payroll. For companies like Sage One who have complex products and services, often the best way to advertise their products is to make a video that explains what exactly is so good about your products. This is exactly what an <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a> is and it\'s a perfect fit for a company like Sage One. With a normal <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV ad</a>, there might not be time to do justice to your product or service, so opt for an explainer instead. I really like how Sage One approached this project and I\'m pleased with my voiceover performance.</p>', '<h2>A little more about Sage</h2>\r\n<p>Sage Group is a huge corporation responsible for a vast selection of business, accounting, and financial services. The payroll software they describe in this video is designed to make it as easy as possible for companies to process their staffmembers\' salaries and taxes.  This service is especially useful because Real Time Information (RTI) legislation requires all employers in the UK to submit their tax and National Insurance information to HMRC every time they run a payroll and not just at payroll year end. If not, they risk a fine of Â£100 or more. Sounds scary and complicated? It\'s not with Sage One Payroll. Check out the Sage You Tube Channel for more great videos and to hear more of my voiceovers in action with sage.</p>', 'sage-one-payroll-voiceover.jpg', 'mtjIXuqIiJw', 'Sage One Payroll Voiceover - Voices by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Looking for a voiceover for your <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>? Please get in touch. Let me know what you need and when you need it. I am also more than happy to read a sample of your script for free, to help you figure out whether my voice is right for your brand. When the approved script is ready, send it over. 99% of jobs are delivered back the same day.</p>', 'Dec 2014', '1', 'Sage One Payroll Voiceover', '0', '', 'Sage One Payroll Voiceover', '', '', '', '', '', '', '', '', ''),
(568, 'virgin-holidays-voice', 'Virgin Holidays Voice', '<p>The Virgin Holidays Voice continues as we discover more of their fabulous destinations - This time... Tennessee.</p>', 'american soft', 'Virgin Holidays Voice - Continuing with Virgin Holidays as we discover more of their fabulous destinations -This time... Tennessee - Voice by Guy Harris', '<h2>A soft American delivery</h2>\r\n<p>The was part of a series of videos that appeared on Virgin Holidays website. Once again, slightly outside my comfort zone but when working with great producers, we can achieve good things together. For a whole bunch of other destinations check out Virgin Holidays very ownÂ You Tube ChannelÂ which also features Ben Fogle exploring.</p>', '<br><h2>Virgin Holidays Voice</h2>\r\n<p>I\'ve voiced a stack of other destinations in this series. More to come too.\r\n\r\nA pleasure to work with it\'s been a challenge going from my regular British voice to switch to that deep rich American voice style. <br>For other character accents and voices please check out some of my <a href=\"character-voiceover\" title=\"Character Voices\"  >character demos</a></p>', 'virgin-holidays-voice.jpg', 'dKsJlpT-dHA', 'Virgin Holidays Voice - Tennessee voiced by Guy Harris', '<h2>Need a soft voice?</h2>\r\n<p>Are you looking for this close mic voice style? Please get in touch and lets chat. I\'d beÂ happy to send a short sample of your script before you book me. Just send a few lines of the script so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Dec 2014', '1', 'Virgin Holidays Voice', '0', '', 'Low USA Voice for Virgin', '', '', '', '', '', '', '', '', ''),
(570, 'rac-car-passport-voiceover', 'RAC Car Passport Voiceover', '<p>A great little explainer for the RAC</p>', 'Explainer', 'RAC Car Passport Voiceover - RAC Car Passport gives the vehicle history unique to the car and essential advice from motoring experts - Voiced by Guy Harris', '<h2>Check out the video</h2>\r\n<p>Great to do the RAC Car Passport Voiceover. I used a softer voice for this explainer video and I think it turned out really well. I think this is a really good service, and it always helps me sell a performance if I completely believe in it. If you\'d like to hear a few more examples of voiceover work like this, check out my <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer videos</a> page.</p>', '<h2>A little more about the RAC</h2>\r\n<p>The <a href=\"https://www.rac.co.uk\" target=\"_blank\" title=\"RAC\">RAC</a> don\'t really need an introduction. They are the UK\'s biggest roadside assistance service, with a host of other automotive services thrown in for good measure. The RAC have got many of us through some pretty unhappy situations and they have a special place in our hearts as a result. The RAC Car Passport is a great Idea: whether buying or selling a car, they provide the most comprehensive car check in the UK. RAC Car Passport gives the vehicle history unique to the car and essential advice from motoring experts. </p>', 'rac-car-passport.jpg', '5ROzh5xEmdQ', 'RAC Car Passport Voiceover - Voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style for an upcoming <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a> or <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a>? Please get in touch. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Dec 2014', '1', 'RAC Car Passport Voiceover', '0', '', 'Simple English explainer Voiceover. ', '', '', '', '', '', '', '', '', ''),
(573, 'dragon-city-voiceover', 'Dragon City Voiceover', '<p>Another TV Advert with the Dragon City Voiceover. Build a magical world in Dragon City! Gain hundreds of dragons, breed them and make them level up in order to become a Dragon Master.</p>', '', 'Dragon City Voiceover - Build a magical world in Dragon City! Gain hundreds of dragons, breed them and make them level up in order to become a Dragon Master', '<h2>Check out the video</h2>\r\n<p>Great to work on another game trailer. Check out my other <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailer voiceovers</a> or my <a href=\"lifeless-game-trailer-voice\" title=\"Lifeless Game Trailer Voiceover\">Lifeless trailer</a> and <a href=\"worms-wmd-character-voices\" title=\"Worms WMD Trailer\">Worms WMD</a> videos if you\'d like to hear more examples of my game trailer voice. It was great working with Social Point developers; they have an award winning sound engineer  who help me get the sound just right.</p>', '<h2>Who are Social Point?</h2>\r\n<p><a href=\"https://www.socialpoint.es\" target=\"_blank\" title=\"Socialpoint\">Socialpoint</a> is a very successful app and game development company based in Barcelona. Socialpoint is a very young, trendy company and they are making huge waves in the mobile gaming industry. The folks at Socialpoint are incredibly professional and it was especially satisfying for me to work with their expert sound team. I\'m always happy to work with good clients and I fully expect to hear from Socialpoint in the future.</p>', 'dragon-city-voiceover.jpg', 'ZtkYHKpKomM', 'Dragon City Promo Voiceover â€“ Guy Harris Reads', '<h2>Get in touch</h2>\r\n<p>If you have a game trailer, <a href=\"movie-trailer-voice\" title=\"Movie Trailer Voiceover\">movie trailer</a>, or <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV ad</a> that needs this voice style, then please get in touch. Always happy to audition the lines of your project first. Let\'s see if I\'m right for your brand.</p>', 'Dec 2014', '1', 'Dragon City Voiceover', '0', '', 'Magical Promo voice for tv advert', '', '', '', '', '', '', '', '', ''),
(579, 'find-locksmith-app-voiceover', 'Find Locksmith App Voiceover', '<p>This cool app allows you to view information such as addresses, telephone numbers, opening times and more! </p>', '', 'Find Locksmith App Voiceover - Download the Tradelocks Find a Locksmith app, and search for your local auto, domestic and safe locksmiths! - Guy Harris', '<h2>Product video voiceovers.</h2>\r\n<p>Product and explainer videos are rapidly changing the way people build websites. People actually spend twice as long on a site with a video and explainer videos like this one are a great way to explain exactly why your products or services are so good. Get the video and then choose the voice. Don\'t let money stand in the way</a>Â of choosing your voice either. This is the voice of your brand so pick based on experience and credibility. This style is one I\'m asked for daily. Let the pictures and your product do the talking and have the voice simply guide it along.</p>', '<h2>What is the Find a Locksmith App?</h2>\r\n<p>You can call the locksmith at the touch of a button, so no more trying to remember telephone numbers! <br>Working with an award winning audio engineer in Dubai offered the full service, providing the voice, the custom music and sound effects for this exciting new product. If you\'d like a couple more examples of explainer videos with a similar style, check out my <a href=\"bbk-travel-insurance-voiceover\" target=\"_blank\" title=\"BBK Travel Insurance Voiceover\">BBK Travel Insurance</a> explainer video.</p>', 'find-locksmith-app-voiceover.jpg', 'i2E6ehYiYM8', 'Find Locksmith App Voiceover - Explainer voice Guy Harris', '<h2>Unlock your frustration!</h2>\r\n<p>If you are looking for this type of voice delivery for your next <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a> or <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a>?  Do get in touch via the form. I\'ll gladly send you a short voice a sample first to see if my voice is right for your project or brand. Tell me more about your project and let\'s see what we can achieve.</p>', 'April 2015', '1', 'Find Locksmith App Voiceover', '0', '', 'Find Locksmith App Voice', '', '', '', '', '', '', '', '', '');
INSERT INTO `messages2` (`id`, `url`, `page_title`, `info`, `search_terms`, `page_desc`, `text1`, `text2`, `image`, `video`, `meta_title`, `bottomtext`, `date`, `whatvideo`, `alt`, `rating`, `twitter`, `hometext`, `santa`, `ntext1`, `ntext2`, `ntext3`, `ntext4`, `nimage1`, `nimage2`, `nimage3`, `nimage4`) VALUES
(581, 'character-voices-showreel', 'Character Voices Showreel', '<p>A section of some of the voices I can deliver for you animation or project.</p>', '', 'Character Voices Showreel - A collection of just some of my character voice work. TV & Promos, animation & web characters - Character Voices by Guy Harris', '<h2>A voice for every occasion.</h2>\r\n<p>Welcome to my new character voices showreel. One of the things about this industry that I really love is the chance to play with characters or unique styles for odd projects.<br> On a daily basis I never know quite what jobs are going to come in, but when a script calls for a <a href=\"penarium-opening-credits\" title=\"Penarium Game voice\">unique voice</a> for a game, <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailer</a>, an app, a trailer, <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer</a>, or a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a>, it\'s always fun dreaming up a style to suit.</p>', '<h2>Character Voices Showreel</h2>\r\n<p>With more and more apps arriving daily to the smart phone app stores, there is a huge chance to create and develop more characters. It\'s certainly a part of this crazy world of voiceover that I love being part of. <br>It\'s a massive help if I have a picture of the character I\'m creating for. It helps to understand quite how they could talk. Then, working with the producer the fun part comes deciding on what it sounds like. I hope you enjoy my showreel.</p>', 'guy-harris-character-showreel.jpg', 'Ad85PPvSfbc', 'Character Voices Showreel - Voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Maybe you have a project that needs a character voice? Please <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a>. I\'m more than happy to send you a short voice a sample first based on your brief to see if my voice is right for your project. Tell me more about your brand and let\'s see if we can find the find character voice for your project..</p>', 'April 2015', '1', 'Character Voices Showreel', '5', '', 'My new character voices showreel...', '', '', '', '', '', '', '', '', ''),
(582, 'homepage-showreel-voiceover', 'Homepage Showreel Voiceover', '<p></p>', '', 'Homepage Showreel Voiceover - Working with an innovative production and creative agency in Edinburgh, it was a pleasure to voice their showreel - Guy Harris', '<h2>Homepage Showreel Voiceover</h2>\r\n<p>I\'ve been working with 20/20 Productions (an innovative production and creative agency in Edinburgh) for a while now. We\'ve been working on a series of videos for a major retail brand, so it was a pleasure to be asked to voice their homepage showreel. They put together a fantastic 1-minute animated explainer video for their homepage and were looking for a natural conversational voiceÂ to suit the flow of the piece. I get more explainer video voiceover jobs than anything else these days and it\'s something I always like doing. If you\'d like a couple more examples of my explainer videos, check out my <a href=\"crowd-hub-x-explainer-video-voiceover\" title=\"Crowd Hub X\">Crowd Hub X</a> video.</p>', '<h2>Who are 20/20?</h2>\r\n<p>20/20 Productions has over 25 yearsâ€™ experience delivering successful communication projects , using the latest technologies and techniques to ensure that your message is delivered clearly. They\'re an extremely impressive and professional company and a pleasure to work with. This relaxed tone is a style  I\'m asked for daily. It feels much more suitedÂ than the hard sell for these explainer videos. Let the pictures and your product do the talking and have the voice simply guide it along.</p>', 'homepage-showreel-voice.jpg', 'NfoJJpELeQc', 'Homepage Showreel Voiceover - Explainer by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for this type of voice delivery for an <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a> or <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">advertisement</a>, please get in touch. I\'ll gladlyÂ send you a short voice a sample first to see if my voice is right for your project or brand.</p>', 'April 2015', '1', 'Homepage Showreel Voiceover', '0', '', 'Friendly male VoiceOver', '', '', '', '', '', '', '', '', ''),
(587, 'because-i-see-voiceover', 'Because I see Voiceover', '<p>This is a stunning film. So when I was asked by the director Rovero Impiglia if i would like to voice it, i jumped at the chance.</p>', 'Natural soft', 'Because I see Voiceover - A beautifully stunning video by director Rovero Impiglia for E9 URBAN & CLIMBING Clothes - natural voice style by Guy Harris', '<h2>Check out the video</h2>\r\n<p>I\'d seen some of Rovero Impiglia\'s work before and really wanted an opportunity to work with him. Great writing, great direction, and (I hope) great voiceover. I think we absolutely nailed it in just a few takes. I understood the direction he wanted to take and the music and the visuals instantly made it easy to understand the direction the voice should take. As a voiceover artist, I think I can make most scripts sound good, but good scripts help us sound so much better! This kind of inspirational <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo video</a> can be a powerful marketing tool and I hope it gets lots of exposure. </p>', '<h2>Welcome to \'Because I see\'</h2>\r\n\r\n<p><em>They used to tell me that youâ€™ll never stop learning and they were right.Â </em>\r\n<em>I have internalized new skills on the rock, with devotion and constancy, until they became my dance, my self-expression.</em>\r\nIt\'s a nice contrast to some of my other work. It\'s actually quite refreshing to have a chance to \'tone it down\' for some thing. Personally, I think it\'s turned out really nice. Rovero and <a title=\"Enove official Website\" href=\"https://www.e9planet.com\" target=\"_blank\">E9 URBAN &amp; CLIMBING Clothes</a> agree.</p>', 'because-i-see-voiceover.jpg', '5_eVJQndGD0', 'Because I see Voiceover - Voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Maybe you have a project that needs this kind of delivery? Perhaps a <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a> or <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>.  Please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. I\'m more than happy to send you a short voice a sample first to see if my voice is right for your project. Tell me more about your project and let\'s see what we can achieve together!</p>', 'March 2015', '1', 'Because I see Voiceover', '3', '', 'This is a stunning film. I love this..', '', '', '', '', '', '', '', '', ''),
(588, 'boov-pop-game-trailer', 'Boov Pop Game Trailer', '<p>When I was asked if I wanted to voice the Boov Pop Game Trailer, can you imagine what I said? Yes, I shook their hand.</p>', 'American  USA movie', 'Boov Pop Game Trailer - A puzzle game that defies the laws of physics! Based on the DreamWorks Animation film, HOME - Game Trailer Voiceover by Guy Harris', '<h2>Working with the big boys</h2>\r\n<p>Working with <a href=\"https://www.dreamworks.com\" target=\"_blank\" title=\"Dreamworks Website\">Dreamworks</a> was an opportunity I didn\'t want to miss. <br>My white board in the Studio has a list of clients I want to work with. This allowed my to tick the box next to Dreamworks animations.<br>Voiced in the UK and audio mastered in the UAE, I couldn\'t have been more happy with the end result. <br>The trailer aired for the first time in Times Square New York too! Other than just working with big companies like Dreamworks, I just love working on <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailers</a> like this <a href=\"war-friends-army-voice\" target=\"_blank\" title=\"War Friends\">War Friends.</a> I wonder what jobs I\'ll get next!</p>', '<br>\r\n<h2>So what is Boov Pop?</h2>\r\n<p>It\'s a puzzle game that defies the laws of physics!<br>Based on the DreamWorks Animation film, HOME: Boov Pop! offers a new twist to the puzzle genre, by adding a unique gravity-based physics mechanism and out of this world 3D graphics!. You\'ll find it on both iOS and Android. I love providing voiceover for mobile games; it\'s the fastest-growing gaming market right now as pretty much everyone has a smart phone. I\'m always happy to voice game trailers as no two games are ever the same!</p>', 'boov-pop-game-trailer.jpg', 'yYJYxKKF7ac', 'Boov Pop Game Trailer â€“ Animated Voiceover', '<h2>Get in touch</h2>\r\n<p>If your looking for thisÂ <a href=\"movie-trailer-voice\" target=\"_blank\" title=\"Movie Trailer Voiceover\">movie trailer voice</a> for a Game Trailer or promo, then please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. I\'m always more than happy to send a short voice a sample first to see if I\'m right for your project. Tell me more about your brand and your project and let\'s see what we can achieve together!</p>', 'March 2015', '1', 'Boov Pop Game Trailer', '3', '', 'Boov Pop Game Trailer Voice', '', '', '', '', '', '', '', '', ''),
(589, 'cities-talking-explainer-voiceover', 'Cities Talking Explainer Voiceover', '<p>This time working with a  great production company in Dubai I was asked to add the Cities Talking Explainer Voiceover.</p>', '', 'Cities Talking Explainer Voiceover - Cities Talking is the perfect travel app for smartphones and tablets (Android & Apple) - Explainer Voice by Guy Harris', '<h2>Check out the video</h2>\r\n<p><em>For many years, art galleries and museums have offered â€˜audio toursâ€™ which provide an expert commentary through a pair of headphones as you walk around. Now, thanks to a savvy combination of GPS navigation and smartphones, Cities Talking offers the same principle of an expert audio guide talking you round and letting you go at your own pace.</em> Say goodbye to your bulky, out-of-date,city guide books... Cities Talking is the perfect travel app for smartphones and tablets (Android and Apple).</p>', '<h2>Cities Talking Explainer Voiceover</h2>\r\n<p>On a daily basis I can voice several <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer videos</a> or <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">web video</a> along side the daily radio ads, e-learning, TV commercials, on hold and others. It\'s a growing market since websites benefit from having great visual content, and since voicing the Apple iPhone TV ads, that\'s the voice style I get asked for most. For a couple more examples, check out my <a href=\"crowd-hub-x-explainer-video-voiceover\" title=\"CrowdHub X Explainer\">CrowdHub X</a> and <a href=\"rise-project-explainer-video-voiceover\" title=\"Rise Project Explainer\">Rise Project</a> explainer videos.</p>', 'cities-talking-explainer-voiceover.jpg', 'YXlOKxHpS7U', 'Cities Talking Explainer Voiceover - Voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a voice for an Explainer Video for a web ad or company product, then please get in touch. I\'m more than happy to send a short voice a sample first to see if I\'m right for your project or brand. Tell me more about your brand and your project and let\'s see what we can achieve together!</p>', 'March 2015', '1', 'Cities Talking Explainer Voiceover', '0', '', 'Natural English Explainer Vocie', '', '', '', '', '', '', '', '', ''),
(590, 'the-escapists-game-trailer', 'The Escapists Game Trailer', '<p>A new, Ray-Winston-style voice for Team 17 Digital\'s new game: The Escapists!</p>', '', 'The Escapists Game Trailer - The Escapists lets you experience a light-hearted insight into everyday prison life with the added main objective of escaping!', '<h2>Check out the video</h2>\r\n<p>I\'d worked with Team 17 Digital previously on the WORMS franchise voicing lots of <a href=\"worms-wmd-character-voices\" target=\"_blank\" title=\"Worm voices\">Worms</a> and the <a href=\"worms-wmd-character-voices\" target=\"_blank\" title=\"Worms WMD trailer\">Worms WMD trailer</a>. This time they were collaborating with Mould Toof Studios on The Escapists. Would I like to voice the trailer? But of course! Can you give us a nasty cockney voice? Yes, I think I can. I like my cockney voice, and it\'s only an accident that it sounds more than a little like Ray Winston! It\'s great to see a wave of games using Sprites again. It reminds me of my days growing up with my ZX Spectrum computer. Sitting playing Manic Miner and Jet Set Willy for hours on end. I love voicing <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailers</a>; if you\'d like to hear a couple more of my game trailers, check out <a href=\"warwings-game-trailer-voice\" target=\"_blank\" title=\"Warwings Game Trailer\">Warwings</a> and <a href=\"siegecraft-commander-trailer-voice\" target=\"_blank\" title=\"Seigecraft Game Trailer\">Seigecraft</a> trailers!</p>', '<h2>The Escapists Game Trailer</h2>\r\n<p>I seem to be carving out nice niche for voicing Game Trailers. Lots of incredible production companies are using my characters and Movie Trailer voice to add to the production. I respect the time an effort that goes in to making them so it\'s a pleasure to be the final touch on the project. The Escapists provides players the opportunity of experiencing a light-hearted insight into everyday prison life with the main objective being that of escaping!\r\nThe Escapists is available on Steam so go download it.</p>', 'the-escapists-game-trailer.jpg', 'yq3bttMIbuI', 'The Escapists Game Trailer - Voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If your looking for a voice similar to The Escapists Game Trailer voiceover, or something else from my <a href=\"character-voiceover\" target=\"_blank\" title=\"Character Voiceover\">range of characters</a>, then please get in touch. I\'m always more than happy to send a short voice a sample first to see if I\'m right for your project.</p>', 'March 2015', '1', 'The Escapists Game Trailer', '0', '', 'Team 17 Digital Voice and WORMS.', '', '', '', '', '', '', '', '', ''),
(596, 'dead-daises-album-promo', 'Dead Daises Album Promo', '<p>Performing at Rockavaria Munich, this is my hard sell Voiceover for the amazing Dead Daises Album Promo.</p>', '', 'Dead Daises Album Promo - Performing at Rockavaria Munich, this is my hard sell Voice for the Album. This played on screens during their set at the event', '<h2>Check out the video</h2>\r\n<p>This played on screens during their set at the event. The event is huge and well attended so it was awesome to be asked to voice this. I like a bit of rock as much as the next guy and I\'ve heard lots of the album promo videos over the years. <br>I do like to voice in this harder style and am always available for more imaging work. If you\'d like to hear another example of this kind of voiceover, check out my Versuz video. Or click voice demos and then <a href=\"voiceover-imaging\" target=\"_blank\" rel=\"noopener\" title=\"Imaging voice\">Imaging voice</a>.</p>\r\n\r\n', '<h2>Dead Daises Album Promo</h2>\r\n<p><em><a href=\"https://thedeaddaisies.com/\" target=\"_blank\" title=\"The Dead Daisies\">The Dead Daisies</a> is an Australian American rock band and musical collective formed in 2012. Musicians Richard Fortus (Guns N\' Roses), Jon Stevens (INXS, Noiseworks) and David Lowy (Mink) have been involved at various times along with a rotation of top rock musicians</em><br>Influenced by 70â€™s and early 80â€™s rock, The Dead Daisies sound is soulful and accessible â€“ equal parts of Aerosmith, Bad Company and Foreigner: muscular vocals, bluesy riffs, big choruses, powerful melodies and strong hooks. With stellar musicianship and pulverizing live shows, fans across the globe are discovering the band that is bringing back Rock & Roll!!</p>', 'dead-daises-album-promo.jpg', 'uwydFoVNN4g', 'Dead Daises Album Promo - voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a hard sell promo voice style for your next <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a>, please get in touch. I\'ll gladly send you a short bespoke voice sample first to see if my voice is right for your promo or trailer. <br>I really only like to take on work my voice is suited for.<br>Tell me more about your project and let\'s see what we can do together.</p>', 'May 2015', '1', 'Dead Daises Album Promo', '0', '', 'Hard sell voice. The Dead Daises Album', '', '', '', '', '', '', '', '', ''),
(597, 'character-voices-song', 'Character Voices Song', '<p>Back in 2004 I put together a little audio demo of some of my character voices. </p>', 'wonderful world', 'Character Voices Song - Back in 2004 I put together a little audio demo of some of my character voices. Well, now I thought it deserved to be made into HD', '<h2>Check out the video</h2>\r\n<p>Now whilst I realise some of these are a little dated, I thought it deserved to be made into HD as a couple of producers reminded me of it and how much they liked it. This was a while ago, but I still like a lot of these impressions. Most of them were pretty bang on, even back in 2004! Give it a watch and see what you think. If you\'d like to listen o more of my character voices, check out my <a href=\"character-voiceover\" title=\"Character Voiceover\">character showreel</a> and perhaps my most famous impression: my <a href=\"david-attenborough-voice\"  title=\"David Attenborough Voiceover\">David Attenborough voice</a>.</p>', '<h2>Character Voices Song</h2>\r\n<p>This is something thats on my list of things to update and produce a new version with some of the newer characters I can now do. However, I think there are plenty in here that are still pretty relevant and popular today as they were back then. When work slows down and I find several hours spare to write, voice, and record it, I will do. A lot of people ask me how I do impressions and the quickest answer is practice. The longer answer is that I listen to everyone and just have a lot of fun trying to sound like them. If you\'re having fun, practice never really feels like practice!</p>', 'character-voices-song.jpg', 'k7DZFWnOcvo', 'Character Voices Song â€“ by Guy Harris, 2004', '<h2>Get in touch</h2>\r\n<p>Are you looking for some impressions for your next show or <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV ad</a>? Just <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a> and tell me more about your project. If it helps, I can provide you with a sample of your script to help you hear whether I\'m right for your project.</p>', 'June 2015', '1', 'Character Voices Song', '3', '', '2004 - My character voices to music...', '', '', '', '', '', '', '', '', ''),
(600, 'seat-hidden-heroes', 'Seat Hidden Heroes', '<p>A pleasure to be working with SEAT on a series of videos.</p>', 'soft natural', 'Seat Hidden Heroes - Mario Hurtado - HOW THIS MAN HAS SAVED LIVES WITH SEAT FOR OVER 25 YEARS - A look at some of the incredible people behind the scenes.', '<h2>Check out the video</h2>\r\n<p> The Hidden Heroes will reveal some of the incredible people working behind the scenes to bring you their incredible vehicles.<em>Mario Hurtado is the Head of Passive Safety at SEAT and is dedicated to making the motoring world a safer place. Discover how he has protected the everyday journeys of thousands of SEAT drivers.</em> The voice I provided for SEAT here is smooth, soft, and natural. The overall style feels a lot like a high-quality documentary voiceover. This tone suits the subject matter perfectly. This video is part history, part <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a>, getting across a lot of information in a short period of time. You might also like to watch my follow up <a href=\"seat-hidden-heroes-adrian\" target=\"_blank\" title=\"SEAT Hidden Heroes Adrian Voiceover\">SEAT Hidden Heroes Adrian video</a>.</p>', '<h2>Seat Hidden Heroes</h2>\r\n<p><em>It could be said that some people quite literally owe their lives to Mario Hurtado. That\'s because 26 years ago he set up his safety department at the Spanish car firm\'s headquarters to ensure every SEAT car that leaves the factory does so with the highest-possible standards. In fact, each SEAT has the acclaimed EuroNCAP five-star safety rating the maximum award possible. In this video, Mario reveals how his job makes an impact to drivers and pedestrians all over the world.</em></p>', 'seat-hidden-hereos.jpg', 'VCqsGpNxPqk', 'SEAT Hidden Heroes â€“ Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for this casual narration voice delivery, please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. I\'ll gladly send you a short voice a sample first to see if my voice is right for your film or brand. Tell me more about your product, service, or project and let\'s see what we can achieve together!</p>', 'June 2015', '1', 'Seat Hidden Heroes', '3', '', 'English, conversational warm voiceover', '', '', '', '', '', '', '', '', ''),
(601, 'sage-one-bank-feeds-voice', 'Sage one Bank feeds voice', '<p>I\'ve been providing voiceovers to Sage for quite a while and you\'ll hear me on numerous videos. </p>', '', 'Sage one Bank feeds voice - I\'ve been providing voiceovers to Sage for quite a while. This time it\'s Sage one Bank feeds. www.voiceoverguy.co.uk', '<h2>Check out the video</h2>\r\n<p>Another big brand as a client. This time it\'s Sage one Bank feeds Have a watch and learn a little more about the service. This kind of financial service is complex enough that a shorter <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a> might not do it justice. A longer <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a> like this one takes its time giving all of the information to its audience, doing justice to the service\'s nuanced offering. Explainer videos are becoming very popular, and I can see why. If you\'d like to see a couple more examples of my explainer videos, check out my <a href=\"wirecard-male-voice-over\" title=\"Wirecard Explainer Video\">Wirecard</a> video.</p>', '<h2>A little more about Sage One Bank Feeds</h2>\r\n<p>Enjoy free automatic bank feeds with Sage One. Securely connect Sage One to your online bank account so you always have an accurate overview of your business finances within Sage One. With bank feeds in place you\'ll no longer need to download and import bank statements manually into Sage One, giving you more time to manage and grow your business\'. As I said, I\'ve done a lot of work with Sage One, including their <a href=\"sage-one-accounting\" title=\"Sage One Accounting\">Sage One Accounting</a> and <a href=\"sage-one-payroll-voiceover\" title=\"Sage One Payroll\">Sage One Payroll</a> videos. \r\n</p>', 'sage-one-bank-feeds.jpg', 'mtjIXuqIiJw', 'Sage Bank Feeds â€“ Finance Voiceover - Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a clear explainer voice, do get in touch. I\'ll gladly send you a short voice a sample first to see if my voice is right for your promo or trailer. Tell me more about your project and let\'s see what we can do when we work together!</p>\r\n', 'June 2015', '1', 'Sage one Bank feeds voice', '0', '', 'The voice of Sage One bank feeds', '', '', '', '', '', '', '', '', ''),
(603, 'dapper-dan-voiceover', 'Dapper Dan Voiceover', '<p>Dapper Dan asked for a 50s American TV Infomercial? Why not? Let\'s try it.</p>', 'informercial 1950 american', 'Dapper Dan Voiceover - A fun retro 50\'s american infomercial for this great hair product. Check the site for fun character voice styles. voiceoverguy.co.uk', '<h2>Another retro character voice</h2>\r\n<p>This script came in with a request for a retro 1950s American infomercial voice â€” a little like the American equivalent to my <a href=\"pathe-news-voice\" target=\"_blank\" title=\"Pathe Voiceover\">Pathe News voice</a> . I\'ve provided this voice style for many radio commercials and the script cracked me up, so it seemed like a great job. With a bit of top end EQ, I think the finished product sounds pretty good. In 2017, this voice style led to a job for GFuel. Look and listen out for some fun retro style ads on their social media. Always fun to try new things. Try me. Lets see what we can do next. </p>', '<br>\r\n<h2>Let\'s find out more about Dapper Dan</h2>\r\n<p><a href=\"https://dapperdanbrand.com\" target=\"_blank\" title=\"Dapper Dan\">Dapper Dan</a> was established in Sheffield, England in 2011. Born of frustration with the less than adequate products available to men to fulfill their styling needs. <br>Dapper Dan Ltd have been diligently developing men\'s hair products for the last 10 years in order to provide the finest product options, no matter what the styling requirements. Their range of three stylers offers absolute flexibility. I love when a company chooses an absolute specialism and commits. I must admit, I\'m impressed with Dapper Dan\'s products and I\'m more impressed with their great taste when it comes to selecting voiceover artists for their promo videos...</p>', 'dapper-dan-voiceover.jpg', 'glbrITdhwSo', 'Dapper Dan Grooming â€“ Voiceover by Guy Harris', '<h2>Can I help?</h2>\r\n<p>If you are looking for a voice similar to this for Dapper DanÂ with a retro twist to it, please get in touch. Mail over me some of the script, I\'ll gladlyÂ send you a short sample to see if my voice is right for your creation. Tell me more about your product or project and let\'s see if we can work together!</p>', 'June 2015', '1', 'Dapper Dan Voiceover', '0', '', 'Dapper Dan -USA retro 50\'s voice...', '', '', '', '', '', '', '', '', ''),
(604, 'lego-minifigures-pirate', 'Lego Minifigures Pirate', '<p>Great to bring out my Pirate voice for Lego Minifigures. The Pirate style is one of my favourites to do.</p>', 'captain', 'Lego Minifigures Pirate - Bringing out my Pirate Voice again. An epic online adventure where you get to explore colorful locations such as Pirate World.', '<h2>Need a Pirate Captain?</h2>\r\n<p><em>Get ready to meet the <a href=\"https://www.lego.com/en-gb/themes/minifigures\" target=\"_blank\" title=\"Minifigures\">Minifigures</a>! Collect them all and bring them with you on grand adventures in LEGO Minifigures Online â€” an epic online adventure where you get to explore colorful locations such as Pirate World, Space World and Medieval World!Â <br>In this new Pirate adventure I also play the voice of the Pirate captain in the game too</em>. In fact, I\'ve provided quite a few <a href=\"pirate-voice\" target=\"_blank\" title=\"Pirate Voiceover\"> pirate voiceovers</a>, including <a href=\"cbbc-pirate-week-voice\" title=\"CBBC Pirate Week\">CBBC Pirate Week</a>, <a href=\"pop-up-pirate-voiceover\" title=\"Pop-up Pirate Promo\">the Pop up Pirate Trailer</a>, and <a href=\"pirate-voiceover\" target=\"_blank\" title=\"Pirate Bridge Voiceover\">the Pirate Bridge promo</a>.</p>', '<h2>Lego Minifigures Pirate</h2>\r\n<p><em>Play together with thousands of other players and battle your way through monstrous riff-raff as you develop your Minifiguresâ€™ unique and powerful abilities. Smash, build and collect - thousands of exciting adventures are just a brick away in LEGO Minifigures Online!</em> It was great working with Lego again; I also worked with them for their Deep Sea Explorers promo video. Lego is a huge brand and I always get excited to work with them.</p>', 'lego-minifigures-pirate.jpg', 'JgMjQ2lo9oo', 'Lego Minifigures Pirate - voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a pirate voice, please get in touch. I\'ll gladly send you a short voice a sample first to see if my voice is right for your promo or trailer. Tell me more about your product or promo project and let\'s trade gold for vocals.</p>', 'June 2015', '1', 'Lego Minifigures Pirate', '0', '', 'Avast ye! My Pirate voice for Lego Minifigures.', '', '', '', '', '', '', '', '', ''),
(605, 'horlicks-promo-voice', 'Horlicks Promo Voice', '<p>Proud to work with this great brand for the Horlicks Promo Voice. Celebrating 140 years. This Pathe News style fits quite nicely.</p>', 'pathe news', 'Horlicks Promo Voice - Without it\'s loyal drinkers around the world, we would never have made it to over 140 years old', '<h2>Check out the video</h2>\r\n<p>So, lets find out more about this iconic brandÂ Horlicks. I get a lot of requests for the <a href=\"pathe-news-voice\" target=\"_blank\" title=\"Pathe Voiceover\">Pathe</a> voice style. Mostly radio commercials. There is a really fun series of sketches on <a href=\"https://www.jackfm.co.uk\" target=\"_blank\" title=\"JackFM\">JackFM </a> Oxfordshire in this style giving tips on everything British. This is so much fun to voice and it obviously comes with loads of nostalgia for that old BBC aesthetic. As this promo is so long and covers so much information, it\'s almost a hybrid between an <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a> and a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a>.\r\n</p>', '<br>\r\n<h2>Horlicks Voice</h2>\r\n<p><em>With 140 years of rich history, <a href=\"https://www.horlicks.co.uk\" target=\"_blank\" title=\"Horlicks\">Horlicks</a> is proud to be the original malted milk drink containing 14 essential vitamins and minerals.</em> Most people who have grown up in the UK will have fond memories of drinking Horlicks, and it\'s safe to say that it\'s a national treasure. This video goes into some of  the brand\'s fascinating history and it was a pleasure to provide my Pathe News-style voice for the video.</p>', 'horlicks-promo-voice.jpg', 'Hp8-la1KL6E', 'Horlicks Advert â€“ Promo Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a voice similar to thisÂ HorlicksÂ promo voice, please do get in touch. SendÂ me some of the script. I\'ll gladlyÂ send you a short voice a sample first to see if my voice is right for what you are creating. Tell me more about your project and let\'s see if we can work together!</p>', 'July 2015', '1', 'Horlicks Promo Voice', '3', '', 'Pathe News style voice for Horlicks', '', '', '', '', '', '', '', '', ''),
(606, 'tv-smiles-voice', 'TV Smiles Voice', '<p>Another ad with this TV Smiles Voice. Running as part of a SKY Ad smart campaign.</p>', '', 'TV Smiles Voice - Makes ad-breaks rewarding! TVSMILES turns this idea on its head and makes you a guaranteed winner every time you play - VoiceoverGuy.co.uk', '<h2>TV Smiles Voice</h2>\r\n<p>My TV Smiles voice was as quirky and wacky as possible. That\'s what the video producers asked for and I think I more than delivered! I drew on a lot of my experience providing voiceover for children\'s TV and toy advertisements, such as my <a href=\"bugs-in-kitchen-voice\" target=\"_blank\" title=\"Bugs in the Kitchen\">Bugs in the Kitchen</a>, <a href=\"greedy-granny-tv-commercial\" title=\"Greedy Granny\">Greedy Granny</a>, and <a href=\"pirate-voiceover\" title=\"Pirate Bridge\">Pirate Bridge</a>. My voice and natural bright tone seems to be a great fit for children\'s toys and shows and it was a brilliant fit for this TV Smiles promo.</p>\r\n', '<br>\r\n<h2>So, What is TV Smiles</a>?</h2>\r\n\r\n<p><em><a href=\"https://twitter.com/tvsmiles\" target=\"_blank\" title=\"TV Smiles\">TV SMILES</a> â€“ Makes ad-breaks rewarding! Do you love doing quizzes but find it unfair that itâ€™s always someone else who wins at Who Wants to be a Millionaire? TVSMILES turns this idea on its head and makes you a guaranteed winner every time you play.</em> This idea is a lot of fun and I think it\'s going to be a huge success. There\'s the added bonus of keeping yourself entertained during the ad breaks, which definitely appeals to me! I\'ve voiced quite a few apps and games recently and this is probably only going to increase in the near future!</p>', 'tv-smiles-voice.jpg', '132487644', 'TV Smiles Advert Voiceover â€“ British Male VO', '<h2>Get in touch</h2>\r\n<p>If you are looking for a voice similar to the TV SmilesÂ Voice, perhaps something from my <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover showreel</a>, please get in touch. Ping me some of the script. I\'ll gladlyÂ send you a short voice sample first to see if my voice is right for what you are creating. Tell me more about your project and let\'s see if we can work together.</p>', 'July 2015', '0', 'TV Smiles Voice', '0', '', 'Quirky voice of TV Smiles.', '', '', '', '', '', '', '', '', ''),
(607, 'robocide-game-trailer-voice', 'Robocide Game Trailer Voice', '<p>I really love doing this voice style,  so here is the amazing Robocide game trailer voice.</p>', '', 'Robocide Game Trailer Voice - Robocide is a brand new Micro RTS, in which players can control hundreds of robots and wage war with the touch of a finger.', '<h2>Check out the Robocide trailer</h2>\r\n<br>\r\n<p>This game looks great and I love getting to use my best American Military voice for the trailer. Most of my other <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailers</a> use some variation of the epic <a href=\"movie-trailer-voice\" title=\"Movie Trailer Voiceover\">movie trailer voice</a>, so it\'s nice to try something different. Games, especially mobile games, are becoming more and more popular, so I expect to get even more game trailer jobs in the near future!</p>', '<br>\r\n<h2>So, lets find out more about Robocide</h2>\r\n<p>Robocide is a brand-new Micro RTS in which players can control hundreds of robots and wage war with the touch of a finger. It\'s available for iOS and Android and it\'s as good as mobile games can get!</em> It\'s always fun to try new things and this trailer was definitely new for me. For more of my game trailers, check out my <a href=\"siegecraft-commander-trailer-voice\" title=\"Siegecraft Commander\">Siegecraft Commander</a> and <a href=\"worms-wmd-character-voices\" title=\"Worms WMD\">Worms WMD</a> game trailers.</p>', 'robocide-game-trailer-voice.jpg', '7PAXKApMYy8', 'Robocide Game Trailer â€“ Sci-Fi Voiceover - Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a voice or trailer similar to Robocide, please get in touch. Ping me some of the script. I\'ll gladlyÂ send you a short voice a sample first to see if my voice is right for what you are creating. Tell me more and get in touch.</p>', 'July 2015', '1', 'Robocide Game Trailer Voice', '0', '', 'Game Trailer voice for Robocide', '', '', '', '', '', '', '', '', ''),
(610, 'my-corporate-video-voice', 'My Corporate Video voice', '<p>I was asked to provide the My Corporate Video voice. I have been working with this company for a number of years so jumped at the chance to be their voice.</p>', '', 'My Corporate Video voice - Need a 60 second animated corporate video for your business for Â£299? Another explainer video voiceover for an awesome company.', '<h2>Watch the video</h2>\r\n<p>I\'ve been working with My Corporate Video for a while now; they need good voiceover work and I\'m always up for a new challenge. So, it was an extra special treat when they asked me to provide the voiceover for their own company video. There\'s something very novel about a company who makes corporate videos making a video for itself.  Needless to say, they\'re very good at what they do. As a voiceover artist, it\'s always better when I\'m working with a great script. If you\'d like a few examples of my work, check out my <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a> my <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceovers</a> and some of my more fun <a href=\"character-voiceover\" target=\"_blank\" title=\"Character Voiceover\">character voiceovers</a>.</p>', '<h2>So, who were My Corporate Video</h2>\r\n\r\n<p><em>A corporate video for your business in just 5 days and for an amazing price!\r\nImagine being able to create a 60 second animated corporate video for your business, including:\r\nyour logo branding\r\nprofessional scripting\r\nprofessional animation\r\nprofessional voiceover\r\nproduction grade music</em>\r\n\r\nI\'ve worked with these guys for a long time now and I\'m very impressed with the quality of their work.</p>', 'my-corporate-video-voice-over.jpg', 'jG2pDSCwg70', 'Corporate Video Voiceover by British Artist Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a styleÂ similar to this for My Corporate Video, please get in touch. Send me part of the script. I\'ll gladlyÂ send you a short voice a sample first to see if my voice is right for what you are creating. Feel free to get in touch and tell me more.</p>', 'July 2015', '1', 'My Corporate Video voice', '0', '', 'My Corporate video voice...', '', '', '', '', '', '', '', '', ''),
(613, 'shooting-business-voice', 'Shooting Business Voice', '<p>My voice on a very short explainer video for Shooting business.</p>', 'natural explainer', 'Shooting Business Voice - Full â€œOn-Locationâ€ Business Video Production That Gets Results. An explainer video that gets the message across in 30 seconds', '<h2>Shooting Business Voice</h2>\r\n<p>When I first got the script, I thought some of it was missing. Then I realised they really had been able to say everything concisely in such a compact way. In July I became the Shooting Business Voice on their explainer video. What I absolutely love about this video is, they said it all in 30 seconds. Short and concise. It really doesn\'t need any more to get the message across. Great animation and even if I do say so myself... great voice... With most of my other <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a>, companies usually spend a minute or two explaining their message but this video illustrates perfectly that this just isn\'t always necessary. If you\'d like to check out a couple more, watch my <a href=\"rise-project-explainer-video-voiceover\" title=\"Rise Project\">Rise Project</a> explainer video.</p>\r\n', '<h2>So who are Shooting Business?</h2>\r\n<p>ShootingBusiness.com created compelling business videos. They were different to most other video production companies because they are driven by your underlying marketing requirements and desired business results. Only when they fully understood what you want to achieve, your target market and what makes you tick, did they work with you on the scripts for your compelling videos.<br>They are now closed.</p>', 'shooting-business-voice-over.jpg', 'jV6PKw42mJA', 'Shooting Business Voiceover â€“ British Narration', '<h2>Get in touch</h2>\r\n<p>So, if you requireÂ a voice for an explainer video or your very own website video, then please <a href=\"contact-guy\"  title=\"Contact Guy\">get in touch.</a> To make the whole process easier, just send a sample of the script and the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script so I canÂ send you anÂ audition for the part too.</p>', 'July 2015', '1', 'Shooting Business Voice', '3', '', 'Simple British explainer voice', '', '', '', '', '', '', '', '', ''),
(614, 'kelloggs-origins-voiceover', 'Kelloggs Origins Voiceover', '<p>Providing the Kellogg\'s origins voiceover was another tick off my list. I\'d always wanted to do something for this iconic brand. A great session and the client did a great job on the animation.</p>', 'character', 'Kelloggs Origins Voiceover - An educational campaign that teaches children where their food originates from and how it is transformed into breakfast cereal', '<h2>So what isÂ Kellogg\'s origins?</h2>\r\n\r\n<p>Kelloggâ€™s Origins is an educational campaign aimed at teaching children where their food originates from and how it is transformed into breakfast cereal. The animations are a micro series, and tell a story over the course of two morning breakfasts. A father, and farmer, enthusiastically explains to his daughter how her bowl of cereal is made and ends up on the table. It was a pleasure to provide the voice of the farmer and my experience with <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a> made me feel right at home with this project.</p>', '<h2>Kelloggs Origins Voiceover</h2>\r\n\r\n<p>Mummu created two animations for Trinity Mirror to feature online and as part of a social media campaign. They appeared on the Kelloggâ€™s website and social media profiles, as well as being rolled out nationally on The Mirrorâ€™s website, and additional regional news sites.</p>\r\n\r\n<p>It was great to work with a brand like Kellogg\'s and to provide the voiceover was good fun too.</p>\r\n\r\n\r\n', 'kelloggs-origins-voiceover.jpg', '134446532', 'Kelloggâ€™s Origin Voiceover â€“ Cereal Advert by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you requireÂ a voice for an explainer video, <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo video</a>, or animation on your own website video, then doÂ <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. To make the whole process easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I canÂ send you a short audition to check if i\'m right for your brand.</p>', 'July 2015', '0', 'Kelloggs Origins Voiceover', '3', '', 'Nice to work on Kelloggs origins', '', '', '', '', '', '', '', '', ''),
(621, 'air-malta-voiceover', 'Air Malta Voiceover', '<p>Let\'s talk about Air Malta, whose motto is \'We Care More\' â€“ Offering More Choice and Flexibility to Customers</p>\r\n', '', 'Air Malta Voiceover - By introducing three Economy Class products and three Business Class products there will be more choice for customers... Air Malta', '<h2>Check out the video</h2>\r\n<p>I\'ve provided Air Malta with a good, crisp, clean voiceover for this explainer video. I\'m being asked for more and more <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video voiceovers</a>, perhaps even more than standard <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover</a>. The biggest advantage to this kind of video is clarity: if you have a detailed or otherwise complicated idea that you\'d like to get across to your potential customers, then an explainer video (with clear voiceover and clean animation/video) can get the message across better than any other medium. Just check out my <a href=\"rise-project-explainer-video-voiceover\" target=\"_blank\" title=\"Rise Project\">Rise Project</a> explainer videos.</p>', '<br>\r\n<h2>A little more about Air Malta</h2>\r\n<p>Air Malta was Malta\'s main airline and they worked hard to develop a well-known brand that is trusted all around the World. The thing that set Air Malta apart from its contemporaries was its dedication to offering customers more choice. By introducing three Economy Class products and three Business Class products there was more choice for customers. Even in the lowest price product - Simply Fly - this still included one piece of hand luggage and a small snack, in contrast to what most other carriers offer.</p>\r\n', 'air-malta-voiceover.jpg', '136878613', 'Air Malta Commercial Voiceover â€“ Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you requireÂ a clean voice, or perhaps a more dramatic <a href=\"movie-trailer-voice\" target=\"_blank\" title=\"Movie Trailer Voiceover\">movie trailer voice</a> for aÂ promoÂ or animation on your own website similar to this, then please get in touch. To make the whole process easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I canÂ send you a short audition to check if my voice isÂ right for your brand.</p>', 'Aug 2015', '0', 'Air Malta Voiceover', '0', '', 'Some Air Malta offers needed a voice...', '', '', '', '', '', '', '', '', ''),
(626, 'penarium-game-trailer-voice', 'Penarium Game Trailer Voice', '<p>I got the call from Self Made Miracle and Team 17 asking if I\'d like to be a part of this new project and of course I said yes. Would you like to be the Penarium game trailer voice? I said \"of course\". Session booked, mic live and away we went.</p>', 'spooky scary evil creepy quirky', 'Penarium Game Trailer Voice - I love this part of the voiceover business, the trailers. Self made miracle and TEAM 17 are launching this awesome game.', '<h2>So, what is Penarium?</h2>\r\n\r\n<p><em>Penarium is a frantic 2D arena arcade game where you control quirky anti-hero Willy. Willy is a kid trapped inside a sinister circus called the Penarium. Willy\'s only hope of ever returning to his beloved father\'s farm is to run, jump and avoid an array of killer deathtraps while being cheered on by a sadistic crowd that is out for blood; his blood.</em> I\'ve provided the voice for quite a few <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailers</a>, including <a href=\"warwings-game-trailer-voice\" target=\"_blank\" title=\"Warwings\">Warwings</a> and <a href=\"worms-wmd-character-voices\" target=\"_blank\" title=\"Worms WMD\">Worms WMD</a>.</p>', '<h2>Penarium Game Trailer</h2>\r\n<p>I love the game trailers. Getting the chance to be a part of an awesome game like this makes this job all the better. I am also playing the voice of the narrator in the game.</p>\r\n\r\n<p><em>Penarium is set in a unique world; a sinister circus show where contestants, much like gladiators, are forced to entertain a sadistic crowd at the risk of losing their lives. Guide poor little Willy through this evil madness and become the champion of Penarium! Every kid wants to go to the circus but no kid wants to die in one.</em></p>', 'penarium-game-trailer-voice.jpg', 'zxxR7tENfcE', 'Penarium Game Trailer â€“ Retro Voiceover - Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a voice for your game trailer or a <a href=\"character-voiceover\" target=\"_blank\">character voice</a> for your game or app, then get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your brand.</p>', 'Aug 2015', '1', 'Penarium Game Trailer Voice', '3', '', 'British Promo Trailer Voice', '', '', '', '', '', '', '', '', '');
INSERT INTO `messages2` (`id`, `url`, `page_title`, `info`, `search_terms`, `page_desc`, `text1`, `text2`, `image`, `video`, `meta_title`, `bottomtext`, `date`, `whatvideo`, `alt`, `rating`, `twitter`, `hometext`, `santa`, `ntext1`, `ntext2`, `ntext3`, `ntext4`, `nimage1`, `nimage2`, `nimage3`, `nimage4`) VALUES
(627, 'seat-hidden-heroes-adrian', 'Seat Hidden Heroes Adrian', '<p>A pleasure to be working with SEAT on a series of videos. The Hidden Heroes will reveal some of the incredible people working behind the scenes to bring you their incredible vehicles.</p>', 'Natural soft', 'Seat Hidden Heroes Adrian Mateo. While listening to a track while driving in your SEAT, spare a thought for one of the people who made the sound possible.', '<h2>Check out the video</h2>\r\n<p>Next time you\'re listening to a cool track while cruising down the motorway in your SEAT, spare a thought for one of the people who made the superior sound possible - Adrian Mateo Presser, SEAT\'s guru behind the impressive car acoustics.</p>\r\n<p>So nice to be working with SEAT on the Hidden Heroes and more so to deliver this job in a very relaxed pace. Especially when compared to some of my other work. If you\'d like to listen to my voiceover work on some other car-related videos, check out my <a href=\"rac-car-passport-voiceover\" target=\"_blank\" title=\"RAC Car Passport\">RAC Car Passport</a> video.</p>', '<h2>Seat Hidden Heroes Adrian</h2>\r\n\r\n<p><em>You might think a pumped-up sound system is a given for quality cars nowadays, but to get the perfect audio balance takes a blend of technological know-how and a finely tuned ear. Adrian Mateo Presser is SEAT\'s man behind the music, providing a premium listening experience for every SEAT owner. His office is a 34m2 soundproof studio hidden deep inside the Spanish car company\'s HQ just outside Barcelona, where he experiments with sound to find out how to strike the right note with motorists.</em> You can find out more the range of cars and services available on Seat\'s website.</p>', 'seat-hidden-heroes-adrian.jpg', 'TV5U0bZm32g', 'Seat Hidden Heroes â€“ Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>This is the Seat Hidden Heroes Adrian Mateo Presser video. There are more in this series. If you are looking for a voice similar to this tone and pace for your <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo video</a> or <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a> , then <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your brand.</p>', 'Oct 2015', '1', 'Seat Hidden Heroes Adrian', '3', '', 'Calm Natural British voice for SEAT', '', '', '', '', '', '', '', '', ''),
(628, 'penarium-opening-credits', 'Penarium Opening Credits', '<p>It was many months ago I put my voice to this game and the Trailer. So, as soon as I saw the game was live and available I had to have a look. The game fromÂ <a href=\"https://www.selfmademiracle.nl\" target=\"_blank\">Self Made Miracle</a> and <a href=\"https://www.team17.com\" target=\"_blank\">Team 17</a>Â is getting great reviews so it makes it all the more a pleasure to have worked on it with them. I love the video game market and it\'s one I am moving into more.</p>', 'Video Game', 'Penarium - The sinister circus show where contestants are forced to entertain a sadistic crowd at the risk of losing their lives. They needed a narrator...', '<h2>But, what is Penarium?</h2>\r\n\r\n<p><em><a href=\"https://www.penarium.com\" target=\"_blank\">Penarium</a> is a frantic 2D arena arcade game where you control quirky anti-hero Willy. Willy is a kid trapped inside a sinister circus called the Penarium. Willy\'s only hope of ever returning to his beloved father\'s farm is to run, jump and avoid an array of killer deathtraps while being cheered on by a sadistic crowd that is out for blood; his blood.</em></p>\r\n', '<h2>Penarium Opening Credits</h2>\r\n\r\n<p>Video game character voices are so much fun to do. Show me a visual and I\'ll try and give you the character\'s voice.</p>\r\n\r\n<p><em>Penarium is set in a unique world; a sinister circus show where contestants, much like gladiators, are forced to entertain a sadistic crowd at the risk of losing their lives. Guide poor little Willy through this evil madness and become the champion of Penarium! Every kid wants to go to the circus but no kid wants to die in one.</em></p>', 'penarium-opening-credits.jpg', 'kGrF8K8mm2w', 'Penarium Opening Credits - Voice of Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a voice or voices similar to this for the Penarium Opening Credits for your video game or a <a href=\"character-voiceover\" target=\"_blank\">character voice</a> for your game or app, then get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the character linesÂ andÂ I\'d be more than happy to send you some samplesÂ to check if my voice isÂ right for your brand.</p>', 'Oct 2015', '1', 'Penarium Opening Credits', '0', '', 'A sinister circus show entertainer voice', '', '', '', '', '', '', '', '', ''),
(631, 'sage-one-accounting', 'Sage one Accounting', '<p>It\'s great to continue the voiceÂ work with the brand behind the nations favourite accounting software.</p>', 'Explainer', 'Sage one Accounting Voice - Online accounting and payroll software for start-ups, small and micro businesses - Explainer video voice-over from Guy Harris', '<h2>Watch the Sage One Accounting Video</h2>\r\n<p>Here\'s nnother explainer video voice â€” this one for Sage accounting. They asked for a nice relaxed natural read and I\'m very pleased with how it turned out. Often, a good explainer video is created by a clear-to-understand script, and that\'s exactly what they gave me. Check out the >SAGEÂ You Tube Channel for more tutorials and product videos. If you\'d like to watch a couple more explainer videos like this one, check out my <a href=\"wirecard-male-voice-over\" title=\"Wirecard\">Wirecard</a> and <a href=\"crowd-hub-x-explainer-video-voiceover\" title=\"Crowd Hub X\">Crowd Hub X</a> explainer videos.</p>', '<br>\r\n<h2>Sage one Accounting</h2>\r\n<br>\r\n<p>Sage One is online accounting and payroll software, with different accountancy and payroll packages available for start-ups and small businesses. So many businesses around the World use Sage One Accounting, so it was a great opportunity for me to get exposure across the business world. And I think the video turned out pretty great, in the end!</p>', 'sage-one-accounting.jpg', 'qlG1294fq9c', 'Sage One Accounting â€“ Explainer Voiceover Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are looking for a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial voiceover</a> or an <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a> voice similar to this for Sage one accounting, then pleaseÂ get in touch. To make the process easier, let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your brandÂ or project.</p>', 'Oct 2015', '1', 'Sage one Accounting', '0', '', 'SAGE Brand Voice', '', '', '', '', '', '', '', '', ''),
(632, 'dpd-predict-voice', 'DPD Predict Voice', '<p>Another explainer video voice for DPD. This is service is called Predict. But what is the service all about?<p>', '', 'DPD Predict Voice - Online shopping is made even easier by DPD\'s Predict and Live-Tracking services.Check out the explainer video by Voiceover Guy Harris', '<h2>Check out the video</h2>\r\n<p>I think explainer videos like this are the perfect choice for any company with a product or service that is complex enough that its customers (or potential customers) might not understand just how good your product/service is. If you\'ve gone above and beyond, as DPD have, to provide a thoughtful service, then an explainer video is the best way to get this information across. Check out my <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video voiceover showreel</a> for more examples. You may also like my <a href=\"crowd-hub-x-explainer-video-voiceover\" target=\"_blank\" title=\"Crowd Hub X\">Crowd Hub X</a> or <a href=\"michelin-cross-climate-voiceover\" target=\"_blank\" title=\"Michelin Explainer Video\">Michelin cross climate</a> explainer videos.</p>', '<h2>DPD Predict Voice</h2>\r\n<p>I\'ve been working with <a href=\"https://www.dpd.co.uk\" target=\"_blank\" title=\"DPD\">DPD</a> for a couple of years now and their service just gets better and better. You can change the delivery, track it, or postpone the delivery however you like. DPD also keep you fully up to date (up to the exact hour) DPD will deliver your parcel. As the world has completely embraced online shopping, DPD has risen to the challenge to provide a vastly superior delivery service and I\'m glad I was able to provide voiceover for their explainer video.</p>', 'dpd-predict-voice.jpg', '142793003', 'DPD Predict Explainer â€“ British Voiceover - Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are working on an explainer video, or perhaps just a shorter <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">promo video</a>, and you need a voice,Â then please et in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your brand.</p>', 'Oct 2015', '0', 'DPD Predict Voice', '3', '', 'DPD Predict\'s Explainer video voice...', '', '', '', '', '', '', '', '', ''),
(633, 'world-of-warships-tutorial-voice', 'World of Warships Tutorial Voice', '<p>The hit game World of Warships asked me to voice all the Naval academy video tutorials. of course I said yes.</p>', 'Promo', 'World of Warships Tutorial Voice - In this episode of Naval Academy - Aircraft carriers - This is one of a series of voiceovers for this awesome video game', '<h2>Video game voices</h2>\r\n<p>It\'s been fun working on this collection of videos. As the game continues to get bigger hopefully the Naval academy will keep me as the captain of their updates. I\'m used to shorter <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV ads</a>, <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer videos</a>, and <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailers</a>, so it\'s a breath of fresh air to spend more time proving voiceover for World of Warship\'s tutorials. There is so much detail in this tutorial and I think I\'ve made the information as easy as possible to absorb.</p>', '<br>\r\n<h2>What is World of Warships?</h2>\r\n<br>\r\n<p><a href=\"https://worldofwarships.eu\" target=\"_blank\" title=\"World of Warships\">World of Warships</a> is a naval action-themed massively multiplayer online game produced by international game developer and publisher <a href=\"https://wargaming.net/en\" target=\"_blank\" title=\"Wargaming\">Wargaming</a>, which is headquartered in Nicosia, Cyprus. Wargaming is a great company and it was great to work with them on this longer voiceover project\r\n</p>', 'world-of-warships-tutorial-voice.jpg', '142797080', 'World of Warships Voiceover â€“ British Style - Guy Harris', '<h2>Get in touch</h2>\r\n<p>I\'m very comfortable with regular work and if you need fast delivery like the regular updates for World of Warships tutorial voice, so if you are looking for a voice to be available daily and to deliver last minute, then please feel free to get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Oct 2015', '0', 'World of Warships Tutorial Voice', '0', '', 'World of Warships Voice Actor', '', '', '', '', '', '', '', '', ''),
(635, 'renault-uk-service', 'Renault UK Service', '<p>I was asked by Renault to voice a series of videos highlighting their servicing products.</p>', 'Explainer', 'Renault UK Service Explainer Videos - I was asked to voice a series of videos explaining about Renault UK Service. Check their YouTube channel for more.', '<h2>Renault explainer videos</h2>\r\n<p>I\'ve never actually owned a Renault. Not for any reason, but I never got round to it. However, I saw the animation and did some more research into the company and said yes, this ad is for me!<br>\r\nThis is another one of my conversational voices. It\'s natural but gets the message across to the target audience.\r\nShort videos like this can engage the viewer better, as long as the product\'s appeal is simple. Check out my <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover showreel</a> for more examples. For a more complex product, you may need to take more time to explain the product; check out my <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video showreel</a>!</p>', '<br>\r\n<h2>More about Renault Servicing</h2>\r\n<p>As the say, Who better than <a href=\"https://www.renault.co.uk\" target=\"_blank\" title=\"Renault\">Renault</a> to care for your Renault?<br>\r\nBenefits of a Renault service:\r\nSafety - full vehicle health check\r\nReliability - Renault approved parts\r\nTransparency - Fixed price on Service and Maintenance\r\nCustomer excellence - vehicles returned washed and clean, and all repairs benefit from 1 year guarantee on parts and labour.<br>\r\n</p>', 'renault-uk-service.jpg', 'o1K-OdQFxL8', 'Renault UK Service â€“ British Voiceover Videos', '<h2>Get in touch</h2>\r\n<p>If you have a product that needs an explainer video voice, then do get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Oct 2015', '1', 'Renault UK Service', '0', '', 'A series of Renault Explainer Videos...', '', '', '', '', '', '', '', '', ''),
(639, 'viva-bahrain-voiceover', 'VIVA Bahrain Voiceover', '<p>Another VIVA Bahrain Voiceover. I\'ve been the English promo voice of VIVA for quite a while now which is pretty cool. They do have some good products for customers.</p>', 'Explainer', 'VIVA Bahrain Voiceover -Â Â I\'ve been the English promo voice of VIVA for quite a while now which is pretty cool. They do have some good products.', '<h2>Check out the video</h2>\r\n\r\n<p>Another product video. I seem to be asked to voice lots of these and I love them. There is not a day goes by without someone asking me to be the voice of a new product. This conversational read style suits this type of video. Not shouting or in your face antics; it\'s just important to get the message across clearly. If you\'d like to hear this style, check out my <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceovers</a> or my longer <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a>.</p>', '<h2>A little more about VIVA Bahrain</h2>\r\n<p><a href=\"https://bhr.voxcinemas.com\" target=\"_blank\" title=\"VIVA\">VIVA</a> is a subsidiary of the Saudi Telecommunications Company (STC) and it was formed to help transform Bahrain\'s telecommunications landscape by offering unrivaled phone and internet services. VIVA is one of the biggest names in Bahrain, so it was great eexposure for me to provide voiceover for this promotions. With this promotion, they are teaming up with a food-delivery service to offer people a chance to win one of 3 mini coopers, a range rover, or air tickets! That\'s a pretty great deal.</p>', 'viva-bahrain-voiceover.jpg', '150623402', 'VIVA Bahrain Voiceover - English product video', '<h2>Get in touch</h2>\r\n<p>If you have a brandÂ that needs something similar to the VIVA Bahrain Voiceover, then do get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. If you\'d like toÂ send a short sample of the script, I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or brand.</p>', 'Jan 2016', '0', 'VIVA Bahrain Voiceover', '0', '', 'VIVA Bahrain Voiceover?', '', '', '', '', '', '', '', '', ''),
(641, 'zalando-voiceover', 'Zalando Voiceover', '<p></p>', 'natural explainer Zalando', 'Zalando VoiceoverÂ -Â This was the after the promotion video. The campaign featured the very beautiful Cara Delevingne and was a great success.', '<h2>Check out the video</h2>\r\n<p>This was the after the promotion video with my Zalando Voiceover. The campaign featured the very beautiful Cara Delevingne. Looking at the video it looks like it was very successful for the brand. It\'s nice to be trusted to complement a brand in this way. If you\'d like to see a range of my work, so see (or hear) if my voice is right for your brand, make sure you check out my <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial voiceover</a> and <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a> pages.</p>', '<h2>A little more about Zalando<h2>\r\n<p>Zalando is the online fashion brand that does everything it can to pull all of the best clothing into one convenient place, including high-street fashion and high-end fashion. These guys are huge and it\'s always flattering when a big brand decides my voice is a good fit for their big advertising campaigns.  Zalando have clearly put a lot of work into this campaign and it\'s paying off!</p>', 'zalando-voiceover.jpg', '8tRtA1ghHIE', 'Zalando Advert Voiceover â€“ Commercial by Guy Harris', '<h2>Get in touch</h2>\r\n<p>For product videos or marketing campaigns maybe I can help with a voice similar to theÂ Zalando Voiceover. Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. If you\'d like toÂ send a short sample of the script, I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or brand.</p>', 'Jan 2016', '1', 'Zalando Voiceover', '0', '', 'Natural Voiceover with Zalando ', '', '', '', '', '', '', '', '', ''),
(644, 'xs-poker-voice', 'XS Poker Voice', '<p>My voice on another great mobile app!</p>', '', 'XS Poker Voice -Â Join players from all over the world! Chat, bluff, improve your skills, win tournaments and become a poker shark! Promo voice by Guy Harris', '<h2>Check out the video</h2>\r\n<p>I just became the XS Poker Voice. Friends of mine have developed this site and asked me to be part of it. Now I\'m not a gambler but they were looking for a posh dry wit eccentric voice and I thought this fit the product. The gamble paid off and they were happy with the result.Join players from all over the world! Chat, bluff, improve your skills, win tournaments and become a poker shark! This voice is a little like my <a href=\"minecraft-backpack-patrick-stewart-style-voiceover\" title=\"Patrick Stewart Voice\">Patrick Stewart impression</a> and I think it works really well with this video.</p>', '<h2>A little more about XS Poker</h2>\r\n<br>\r\n<p>XS Poker is a great little poker game for mobile that lets you practice your skills and enjoy the game without losing money. The game can\'t be played for money, so it isn\'t gambling. It\'s great for people who love poker but would rather not gamble on their phones. It\'s also great if you\'ve just started playing poker and you\'d like to get a little better at it.</p>', 'xs-poker-voice.jpg', 'zaQscCLhj_Y', 'XS Poker TV Promo â€“ Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you have a product or <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a>Â that needs an <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a>, the XS Poker voice then get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Jan 2016', '1', 'XS Poker Voice', '0', '', 'Quirky Older voice', '', '', '', '', '', '', '', '', ''),
(645, 'macc-lads-documentary-voice', 'Macc Lads Documentary Voice', '<p>A documentary I voiced on the 80\'s band Macc Lads. A film short by one of the sons of the band. </p>', 'narration', 'Voiceover for The Macc Lads documentary â€” Guy Harris brings a tongue-in-cheek narration style, blending gritty northern tone with warm nostalgic delivery.', '<h2>A step back in time for me.</h2>\r\n<p>When I got the email it reminded me of my old skateboarding days hanging out with my mates who were even bigger fans than I was. Not sure I\'d play their music loud in front of my family but it was quite funny. One of the Macs Lads sons got in touch asking if I\'d narrate it. Watch the documentary and see the crazy world in the late 80s. If you\'re looking for a voice for your own documentary, check out my <a href=\"narration-voice\" target=\"_blank\" title=\"Narration Voiceover\">narration voiceover page</a> or maybe something from my <a href=\"character-voiceover\" target=\"_blank\" title=\"Character Voiceover\">character voiceover page</a>.</p>', '<br>\r\n<h2>Who are the Macs Lads?</h2>\r\n<p><a href=\"https://themacclads.co.uk\" target=\"_blank\" title=\"The Macc Lads\">The Macc Lads</a> were a punk and hard rock band from Macclesfield, England. Self-proclaimed the \"rudest, crudest, lewdest, drunkest band in Christendom\".<br>\r\nThe Macc Lads used zany, foul-mouthed and politically incorrect lyrics; common themes were drinking, sexism and homophobia. <br>Active from 1981 to 1995 and were banned from numerous UK venues. Like them or loath them, they were a big part of the UK punk scene and this documentary is a fascinating look at that time. \r\n</p>', 'macc-lads-documentry-voice.jpg', 'tWOaNxD-utI', 'Macc Lads Documentary Voiceover â€“ Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you have a documentary that needs a voice similar to this for the Macc Lads then do get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Jan 2016', '1', 'Macc Lads Documentary Voice', '0', '', 'Documentary narration voice - Macc Lads', '', '', '', '', '', '', '', '', ''),
(648, 'dead-daises-promo-voice', 'Dead Daises Promo Voice', '<p>I\'m back and the Dead Daises Promo Voice back in full swing for this next promo.</p>', 'Hard sell promo', 'Dead Daises Promo Voice - This great band asked me to voice the next promo for them. Check out my site for other commercials and trailers - Guy HarrisÂ ', '<h2>Check out the video</h2>\r\n\r\n<p>This hard sell voiceover style is perfectly suited for this type of advert. The tone of the <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a> has an unmistakable radio feel to it that many people have come to expect from music adds. This was the tone I was asked for by the client and I\'m really chuffed with the result. I like voicing music acts and other events; check out my <a href=\"https://www.youtube.com/watch?v=RPOCEix4cDQ\" target=\"_blank\" title=\"BC Big Weekend Voiceover\">BBC Big Weekend opener</a>. The Dead Daises is a great band and I\'m proud that my voice is associated with their new album. </p>', '<h2>A Little More about The Dead Dasies</h2>\r\n<br>\r\n<p><a href=\"https://thedeaddaisies.com\" target=\"_blank\" title=\"The Dead Daisies\">The Dead Daisies</a> is an Australian-American rock band and musical collective formed in 2012 in Sydney, Australia and Los Angeles, California. This mixture of American and Australian sounds gives them a slightly different sound than many of the other classic rock bands out there. With plenty of attitude, The Dead Daisies is making waves and it was a pleasure to provide the voiceover for their commercial. </p> ', 'dead-daises-promo-voice.jpg', 'Z4oP6c1ebjI', 'Dead Daisies Promo â€“ Rock Music Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you have a promoÂ thatÂ needs a little edge somethingÂ like the Dead Daises Promo Voice then do get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Jan 2016', '1', 'Dead Daises Promo Voice', '3', '', 'Hard British promo voice style...', '', '', '', '', '', '', '', '', ''),
(649, 'this-war-of-mine-trailer-voiceover', 'This War of Mine Trailer Voiceover', '<p>Another game for 11bit studios, This War of Mine Trailer Voiceover.</p>', 'deep', 'This War of Mine Trailer Voiceover - It\'s war from a new angle. You don\'t play as a soldier, but a group of civilians trying to survive a besieged city.', '<h2>Check out the video</h2>\r\n<p>I love providing voiceover for <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailers</a> as they\'re all so different and often a little more creative than some standard <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercials</a> for other products. Along with <a href=\"movie-trailer-voice\" title=\"Movie Trailer Voiceover\">movie trailers</a>, game trailers are trying to tell a story in a short period of time. They asked me to provide a tough, grizzled American accent â€” someone who\'s been through the wars (literally) and I\'m really chuffed with the end result!</p>', '<h2>What is This War of Mine?</h2>\r\n<br>\r\n<p><a href=\"https://store.steampowered.com/app/282070/This_War_of_Mine/\" target=\"_blank\" title=\"This War of Mine\">This War of Mine</a> provides an experience of war seen from an entirely new angle. For the very first time you do not play as an elite soldier, rather a group of civilians trying to survive in a besieged city. The trailer perfectly captures the game\'s tone, which tries to offer gamers a gritty, realistic look at war. This is a tough game to play, but it was a breeze to provide the voiceover for! It\'s also worth saying that this game got 8.4 on IGN\'s review and 10/10 on Steam.</p>', 'this-war-is-mine-voiceover.jpg', 'z4KMUa14NfM', 'This War of Mine Trailer â€“ Dark Game Voiceover', '<h2>Get in touch</h2>\r\n<p>If you have a game trailerÂ thatÂ needs somethingÂ likeÂ This War of Mine Trailer Voiceover then do get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Jan 2016', '1', 'This War of Mine Trailer Voiceover', '0', '', 'This War of Mine Trailer Voiceover', '', '', '', '', '', '', '', '', ''),
(651, 'unesco-water-voiceover', 'Unesco where is water?', '<p>Following a call from director Steve Cutts, I was asked to voice this very important video about water for Unesco.</p>', 'Explainer web video', 'Unesco voiceover -Â \'The Water Rooms\' journey into the world of freshwater resources. A film by UNESCO WWAP -Â a real poignant film. Watch and be inspired.', '<h2>Water rooms explainer video</h2>\r\n<p>The Unesco voiceover came following a call from director Steve Cutts asking if i\'d like to be involved in the Water Rooms project. The project was \"The Water Rooms\" a journey into the world of freshwater resources. A really interesting topic and great short film. We felt this style of delivery really suited the piece. It\'s a real poignant film. Watch and be inspired (I hope). This is an example of how effective <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer videos</a> can be; they help you get across complex subjects with the combination of animation and voiceover â€” a little like this <a href=\"home-composting-explainer-voice\" target=\"_blank\" title=\"Home Composting Explainer Video\">home composting video</a> . \r\n</p>', '<br><h2>Who are Unesco?</h2>\r\n<p><a href=\"unesco-water-voiceover\" target=\"_blank\" title=\"UNEsCO\">UNESCO</a> is responsible for coordinating international cooperation in education, science, culture and communication.<br> It strengthens the ties between nations and societies, and mobilizes the wider public so that each child and citizen. <br>UNESCO\'s messages are of increasing importance today, in a globalized world where interconnections and diversity must serve as opportunities to build peace in the minds of men and women. This is the kind of explainer video I love to be part of as I\'m sure it\'ll help make a difference. Sometimes, the only way to get the message across is to produce a particularly high-quality video.\r\n</p>', 'unesco-water-voiceover.jpg', '150788840', 'UNESCO Voiceover â€“ Where Is Water? by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Looking for an explainer, <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a>, or short film voice similar to the Unesco where is water voiceover? Please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your brand or project.</p>', 'Jan 2016', '0', 'unesco-water-voiceover', '3', '', 'British Explainer Video Voiceover', '', '', '', '', '', '', '', '', ''),
(653, 'star-wars-character-voices', 'Star Wars character voices', '<p>We thought we\'d ask the question, what would happen if C-3P0 & R2D2 worked in Starbucks?</p>', 'C3 P0 Yoda darth vader', 'Star Wars Character Voices Â - All the voices you hear are mine -Â What would happen if C-3P0 & R2D2 worked in Starbucks? Need a Character? Get in touch.', '<h2>Starbucks Star Wars</h2>\r\n<p>Quite an unusual setting, so we then threw in some of the other <a href=\"character-voiceover\" title=\"character voices\">character voices</a> from Star Wars to see what happens. <br>For as long as I can remember i\'ve imitated Obi Wan Kenobi, C-3P0, Jar Jar Binks and Yoda for fun. <br>A friend of mine had a voice part in one of the other films and it would be a dream to do something similar. I can only but dream.</p>', '<br>\r\n<h2>Disney Movies</h2>\r\n<p>So good that Disney bought the rights to the franchise. Amongst their theme parks opening new Star Wars lands in the <a href=\"https://disneyparksblog.com\" target=\"_blank\" title=\"Star Wars in the Magic Kingdom\">Magic Kingdom</a>, it\'s great to see what they are doing with the new movies. I absolutely loved The Force Awakens, and can\'t wait to see the next. in the new series. <br>More chance for my impersonations to get some time in the sun. \r\n</p>', 'star-wars-character-voices.jpg', 'Fm0qSBLhA6A', 'Star Wars Character Voices - sketch by Guy Harris', '<h2>Use the force!</h2>\r\n<p>If you looking for Star Wars character voices or something new and fresh, let me have a play around with some styles for you. Please <a href=\"contact-guy\" title=\"Contact VoiceverGuy\">get in touch.</a> To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a sample of the script andÂ I\'d be more than happy to send you an audition to check if my voice isÂ right for your project.</p>', 'Jan 2016', '1', 'star-wars-character-voices', '3', '', 'Star Wars character voices in Starbucks', '', '', '', '', '', '', '', '', ''),
(654, 'farm-heroes-saga-voiceover', 'Farm Heroes Saga Voiceover', '<p>My voice on the trailer of another great mobile game!</p>', 'American', 'Farm Heroes Saga Voiceover - Stop Rancid Raccoon in this fun & fruity game & play your way over 700 levels of strawberry-switching, carrot-matching madness', '<h2>Watch the Farm Heroes Saga Game Trailer</h2>\r\n<p>Here is the Farm Heroes Saga trailer voiceover. In my voiceover journey, I\'m a big fan of <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">app and video game trailers</a> as the the name of the game is fun, so the trailers are usually packed full of personality, and so are <a href=\"movie-trailer-voice\" title=\"Movie Trailer Voiceover\">movie trailers</a>, although to a lesser degree. I think this Farm Heroes Saga trailer turned out great!</p>', '<h2>What is Farm Heroes Saga?</h2>\r\n\r\n<p><em>\"Play <a href=\"https://www.king.com\" target=\"_blank\">Farm Heroes Saga</a> online and help the adorable Cropsies! Stop Rancid the Raccoon in this fun and fruity game and play your way through over 700 levels of strawberry-switching, carrot-matching madness! Collect the Cropsies and save Happy World Farm!\"</em> Available on the App stores. They wanted the big american style announcer and I think we got what was needed. For more of my game trailers, take a look at my <a href=\"warwings-game-trailer-voice\" title=\"Warwings Trailer\">Warwings</a> and <a href=\"robocide-game-trailer-voice\" target=\"_blank\" title=\"Robocide\">Robocide</a> videos.</p>', 'farm-heroes-saga.jpg', '7QXZdT4y0uI', 'Farm Heroes Saga â€“ Energetic Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you looking for an over the top announcer just like this Farm Heroes Saga Voiceover or something new for an app or video game trailer, let me have a play around with some styles for you. Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Jan 2016', '1', 'Farm Heroes Saga Voiceover', '0', '', 'Fun American Commentator Voice', '', '', '', '', '', '', '', '', ''),
(656, 'salter-blender-pro', 'Salter Blender Pro', '<p>The Salter Blender Pro is an awesome bit of kit.</p>', '', 'Salter Blender Pro -Â a high performance blender.Â Stainless steel blades, supercharged with 1500w of power, you can smash, blend, grind with ease.', '<h2>Check out the video</h2>\r\n<br>\r\n<p>I\'ve been working with Ultimate Products for a while now and it\'s always much nicer when the products I\'m voicing are ones I\'d actually buy.  This blender is great and I love how the video came out. I also voiced the <a href=\"https://www.youtube.com/watch?v=6RKxbr0D9uk\" target=\"_blank\" title=\"Salter Pan for Life\">Salter Pan for Life</a> ad and I hope to work with them in the future. Bigger brands, like Salter, often need a bigger, more recognisable voice, so I\'m very pleased they chose to work with me!</p>', '<h2>A Little More about Salter</h2>\r\n<p>The Salter Blender Pro 1500 is a high performance blender. With its stainless steel blades which are supercharged with 1500w of power, spinning at 25,000 RPM â€” you can smash, blend, grind and whip up many different foods, drinks, glazes, spices, and soups with ease.</em> Salter is widely regarded as one of the top kitchen and catering specialist companies in the World</p>', 'salter-blender-pro.jpg', '155575313', 'Salter Blender Pro â€“ Product Voiceover by Guy Harris', '<h2>Get in touch</h2>\r\n<p>Got a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial</a> or <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer video</a> in need of a voice? Maybe one like this one for Salter? Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the tv advertÂ and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Feb 2016', '0', 'Salter Blender Pro', '0', '', 'The Salter Blender Pro Voiceover', '', '', '', '', '', '', '', '', ''),
(660, 'euroseal-windows-tv-advert', 'EuroSeal Windows TV advert', '<p>Yes, that\'s my voice you\'ve heard on the latest Euroseal Windows advert!</p>', 'Storyteller kids tv', 'EuroSeal Windows TV advert -Â One of the most recognised names in the replacement window industry - Guy Harris, one of the industries most recognised voices', '<h2>Voiceover on the EuroSeal Ad, working with Starts and Heroes Animation</h2>\r\n<p>Have you seen the new EuroSeal Windows TV advert? They asked me to provide a clean, clear voiceover for the ad and I think it\'s turned out really well. The whole video was taken to the next level with a beautiful animation by Stars and Heroes. Having seen these guys\' work, I\'m really hoping to get involved with another project of theirs. Voiceover is only part of the puzzle, after all, and great animations always make me look even better!</p>', '<h2>Who are Euroseal windows?</h2>\r\n<br>\r\n<p><em>EuroSeal prove that not all uPVC suppliers are the same. To be able to expand, yet keep quality and service to the highest standard, takes a special kind of company.</em> This seems like a great company and it was a pleasure to work with them. if you\'d like to see a little more of what I can do, make sure you check out my <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover page</a> and perhaps my <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video voiceover page</a>, if your product or service is a little more complicated and you think you need a more in-depth video to get the message across to your audience.</p>\r\n', 'euroseal-windows-tv-advert.jpg', 'JWrRydey1bw', 'EuroSeal Windows TV advertÂ Voiceover - Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you have a <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV ad</a> or video and wanting a style similar toÂ this EuroSeal Windows TV advert? Please get in touch. To make the process easier, just let me knowÂ the intended usage of the production, and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your productionÂ or project.</p>', 'Feb 2016', '1', 'EuroSeal Windows TV advert', '0', '', 'Kids TV Storyteller voice', '', '', '', '', '', '', '', '', ''),
(661, 'super-hero-voice', 'Super Hero Voice', '<p>Who are you going to call for your next superhero voice? Of all the characters I voice, I do love to dabble in the world of superheroes.</p>', 'fespa', 'Super Hero Voice -Â When you need a full on Hero - You need voiceover Guy Harris. FESPA Digital, the largest digital wide format print exhibition in Europe.', '<h2>Check out the video</h2>\r\n<p>In my career I\'ve worn more lycra suits while in the booth than I\'ve had hot dinners. Event <a href=\"voice-of-god\" title=\"Voice of God\">voice of God</a> and <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">video games</a> and apps, whatever the project, does this voiceover style suit what you are looking for? You may also like to check out my <a href=\"marvel-superheroes-voiceover\" target=\"_blank\" title=\"Marvel Superheroes Voice\">Marvel Superheroes Voice</a> and my <a href=\"marvel-spiderman-voiceover\" title=\"Spiderman Voice\">Marvel Spiderman voice</a>.</p>', '<br>\r\n<h2>Enough about the voice, but what is Fespa Digital?</h2>\r\n<br>\r\n<p>FESPA Digital is one of the most creative and inspirational platforms for innovations in the wide format digital printing industry. They\'ve had exponential growth year-on-year with more and more print service providers switching from analogue to digital print.</em> I think Fespa Digital is clearly doing everything right... including hiring me to provide the voiceover for their promo!</p>\r\n', 'super-hero-voice.jpg', '91_4NJA5U_Y', 'Super Hero Voice Characters of Guy Harris', '<h2>Get in touch</h2>\r\n<p>Do you haveÂ a project, event or a gameÂ in need of a super hero voice? Please fill in the form and say hi. To make the process easier, just let me knowÂ the intended usage of the production, and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your productionÂ or project.</p>', 'Feb 2016', '1', 'Super Hero Voice', '0', '', 'American Super Hero Voice!', '', '', '', '', '', '', '', '', ''),
(666, 'walkers-crisps-spell-go', 'Walkers Spell Go - Computer Voice', '<p>Walkers Crisps Spell Go is an incredible promotion giving away a whole bunch of holidays for collecting letters.</p>', '', 'Guy Harris voices Walkers Crispsâ€™ Spell & Go promo with his signature gameshow flair â€” boosting excitement and energy for this unforgettable snack giveaway.', '<h2>My voice on Walker\'s Amazing Competition Promo</h2>\r\n<p><em><a href=\"https://twitter.com/walkers_crisps\" target=\"_blank\" title=\"Walkers Crisps\">Walkers</a> were giving away up to 20,000 4-star holidays for seven nights for four people. You had to start collecting letters for your chance to win!Â Enter the code to reveal your letter. Keep collecting until you have all the letters to spell one of 26 set destinations.</em> I really like providing voiceover for competitions and this Walkers promo was a lot of fun to work on; you may also like to check out my performance on <a href=\"this-morning-spin-to-win-gameshow-voice\" target=\"_blank\" title=\"This Morning Competition\">This Morning\'s competition</a></p>', '<h2>How it works...</h2>\r\n<p>To collect letters from promotional packs, simply enter the 12 digit code starting with WH from the back and you will be provided with a letter. Each individual pack will give you one letter. Youâ€™ll only be able to collect 5 codes from packets of Walkers crisps per day.</p>\r\n<p>Youâ€™ll also need to be on the lookout for letters that will appear elsewhere in other unsuspecting places like Facebook, in the newspapers, or even on TV. To collect these letters, input the code directly into your dashboard. In certain instances, you can use image recognition to take a photo and upload the image to your dashboard to redeem that letter.</p>\r\n', 'walkers-crisps-spell-go.jpg', 'l8COVPnDp9Y', 'Walkers Crisps Spell Go - Voice by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you\'ve got a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a> you need a voice for? Maybe one like this Walkers Crisps Spell &amp; Go? Please <a href=\"contact-guy\"  title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'May 2016', '1', 'Walkers Crisps Spell Go', '3', '', 'The voice of the screen!', '', '', '', '', '', '', '', '', ''),
(667, 'disney-store-marvel-voiceover', 'Disney Store Marvel Voiceover', '<p>This time I was asked for a powerful read for the Disney Store Marvel Voiceover. Well, it was Disney, so of course, I jumped at the chance. I think it\'s turned out really nice.</p>', '', 'Disney Store Marvel Voiceover -Â Great to be working with Disney & Marvel on the TV advert for Team Challenges. A deep powerful voice requested & delivered.', '<h2>Check out the video</h2>\r\n<p>The Challenge will see kids pick a side, either Team Captain America or Team Iron Man. I know who I\'d choose... I love doing anything like this and much of my work seems to revolve around kids games and toys, especially superhero-themed toys, such as <a href=\"marvel-spiderman-voiceover\" title=\"Spiderman Voiceover\">Spiderman</a> and <a href=\"marvel-superheroes-voiceover\" title=\"Avengers Voiceover\">Avengers costumes</a>! As a Big fan of Disney and now that my daughter is at an age to appreciate it, I count them as an awesome client to have onboard.</p>', '<h2>How it works</h2>\r\n<p><em>The Marvel Team Challenge will give guests the chance to either support Captain America on his quest to remain independent or Iron Man, who wants to support the government in their mission to protect the people.</em></p>\r\n\r\n<p><em>Disney store guests get to pick their teams and are then taken on a quest to complete four team-building tasks in order to win puzzle pieces.</em></p>', 'disney-store-marvel-voiceover.jpg', 'HN6J5H4XpNo', 'Disney Store Marvel Voiceover -Â Great to be working with Dis', '<h2>Get in touch</h2>\r\n<p>If you\'ve got a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promotion</a> you need a voice for? Maybe one like this Disney Store Marvel Voiceover? Please do get in touch. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'May 2016', '1', 'Disney Store Marvel Voiceover', '3', '', 'Powerful British Voice for Disney Store.', '', '', '', '', '', '', '', '', ''),
(670, '123-casinos-voiceover', '123 Casinos Explainer Voice', '<p>My 123 Casinos Voiceover is another one of a short series of really snappy explainer videos which I\'m seeing more and more of these days.</p>', '', '123 Casinos Voiceover - What do they do? The focus is simple: to help make your choice of casino as easy as 123. Another great short Explainer video voice', '<h2>My voice in another great explainer video</h2>\r\n<p>Summing up a product in a nice 30 seconds really keeps the attention of the viewer. As I always learnt in radio (although not always adhered too), less is more. I\'ve got a lot of experience with <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer videos</a>, which is probably why they\'re becoming the most common job I\'m asked to do. They\'re very effective and I\'m particularly proud of this one for 123 Casinos!</p>', '<h2>So who are is Casino123.com?</h2>\r\n\r\n<p><a href=\"https://123casinos.com\" target=\"_blank\" title=\"123Casinos\">123Casinos</a> have been at the centre of the industry forÂ over 15 years. Their original site was the first Casino Review site in the UK and it\'s grown considerablyÂ since 2001.Â Their focus is simple: to helpÂ make your choice of casino as easy as 123. They help fellow gamers get real insight into which casinos offer the best experiences and the best chance of winning.</p>', '123-casinos-voiceover.jpg', '167811481', '123 Casinos Voiceover - Explainer video voice by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you\'ve got a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a>Â or a shortÂ <a href=\"explainer-video-voice\">explainer video</a>Â andÂ you need a voice for it,Â maybe like this 123 Casinos Voiceover, then doÂ get in touch. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'July 2016', '0', '123 Casinos Voiceover', '3', '', 'Simple Explainer Voiceover', '', '', '', '', '', '', '', '', '');
INSERT INTO `messages2` (`id`, `url`, `page_title`, `info`, `search_terms`, `page_desc`, `text1`, `text2`, `image`, `video`, `meta_title`, `bottomtext`, `date`, `whatvideo`, `alt`, `rating`, `twitter`, `hometext`, `santa`, `ntext1`, `ntext2`, `ntext3`, `ntext4`, `nimage1`, `nimage2`, `nimage3`, `nimage4`) VALUES
(671, 'mmx-hill-climb-trailer-voiceover', 'MMX Hill Climb Trailer Voiceover', '<p>Another day, another job, MMX Hill Climb Trailer Voiceover. I downloaded this game after the trailer was released. WOW! It\'s awesome!</p>', '', 'MMX Hill Climb Trailer Voiceover -Â The most crazy, addictive & FUN physics based racing game ever made. The explosive follow up to the awesome MMX Racing', '<h2>Check out the video</h2>\r\n\r\n<p>It\'s awesome! It never ceases to amazing me what these game designers can now squeeze onto a mobile phone. This is a world I love being part of. Made by Hutch Games of which I\'ve voiced trailers for them before including <a href=\"https://www.youtube.com/watch?v=xyqZ7MDBO-Y\" target=\"_blank\">Smash Bandits</a>. You might also like to check out some of my other <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailer voiceovers</a></p>', '<h2>MMX Hill Climb Trailer Voiceover</h2>\r\n<p>The most crazy, addictive &amp; FUN physics based racing game ever made.</p>\r\n\r\n<p><em>- Upgrade your truck and own the leaderboard.</em></p>\r\n<p><em>- Race your friends &amp; let them know who\'s the best.</em></p>\r\n<p><em>- Loads of courses and vehicles including the Big Rig, the Tank and the Muscle Classic</em></p>\r\n\r\n<p>MMX Hill Climb is the explosive follow up to massively successful MMX Racing. Download and play today.</p>\r\n', 'mmx-hill-climb-trailer-voiceover.jpg', '17XTUByi28Q', 'MMX Hill Climb Trailer Voiceover - Voiced by Guy Harris', '<h2>Get in touch</h2>\r\n<p>HaveÂ you got a <a href=\"game-trailer-voice\" title=\"Game Trailer Voiceover\">game trailer</a>Â or a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">promo video</a> andÂ you need a voice for it,Â maybe like thisÂ MMX Hill Climb Trailer Voiceover? Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'July 2016', '1', 'MMX Hill Climb Trailer Voiceover', '0', '', 'American Promo Trailer Vocie', '', '', '', '', '', '', '', '', ''),
(674, 'eze-group-explainer-voice', 'Eze Group Explainer Voice', '<p>Another job as Eze Group Explainer Voice. I\'ve talked about it many times but I do seem to have found my niche in this market. <a href=\"explainer-video-voice\" title=\"Explainer Videos\">Explainer Videos</a> are big business and also, important to websites. Whilst the viewer is happy to read content on a page, they are happier to watch compelling content instead. Short 1 - 2 minute videos are much easier to consume and quite frankly more interesting.</p>', '', 'Eze Group Explainer Voice -Â To launch the music concert in Exeter I worked with the guys at R1 to be a part of this incredible promo. Wow, it\'s BIG!', '<h2>Check out the video</h2>\r\n<p>Take this one. Working with <a href=\"https://spark-media.co.uk\" target=\"_blank\">Spark Media</a>, the animation is spot on and done well, the music has been carefully chosen to match the product and compliments my voice track.</p>', '<h2>Who are the Eze Group?</h2>\r\n\r\n<p>Welcome to EZE Group â€“ and your passport to an exciting world of travel, leisure and lifestyle opportunities. We offer a whole new approach to planning your leisure time that makes it easy to enjoy countless activities and destinations â€“ as well as huge savings on a vast range of products and services.</em></p>', 'eze-group-explainer-voice.jpg', 'UZgnAiQayxI', 'Eze Group Explainer Voice - Voice by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you\'ve got an explainer video or a webvideoÂ andÂ you need a voice for it,Â maybe like this Eze Group Explainer Voice, then put it in the hands of my 16 years experience. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately too. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'July 2016', '1', 'Eze Group Explainer Voice', '0', '', 'The Eze Group voice. ', '', '', '', '', '', '', '', '', ''),
(675, 'rise-project-explainer-video-voiceover', 'Rise Project Explainer Voiceover', '<p>Welcome to the Rise Project Explainer Video Voiceover. Another great explainer video which hits the mark in terms of graphics, music and voice.</p>', '', 'Rise Project Explainer Video Voiceover -Â Rise Project is your data driven performance-marketing partner. Explainer voice by Guy Harris. Uk based voiceover.', '<h2>Check out the video</h2>\r\n\r\n<p>As said previously this is my area of speciality. 99% of all <a href=\"explainer-video-voice\" title=\"explainer videos\">explainer videos</a> are voiced, edited and returned the same day back to the client. I\'ll include minor amends and pickups too.</p>\r\n\r\n<p>Have you got an explainer video on your website? If not, you should. Get in touch and I can recommend some awesome web video production companies.</p>', '<h2>Who are Rise Project?</h2>\r\n\r\n<p>Rise Project is your data driven performance-marketing partner. We structure traffic supply relationships with successful online companies looking to grow their customer base exponentially. We specialize in Big Data and build our acquisition and ROI strategies around social and programmatic display marketing.</p>', 'rise-project-explainer-video-voiceover.jpg', '5E3jSEGRdBY', 'Rise Project Explainer Video Voiceover - Voice by Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you\'ve got a promo or an event andÂ you need a voice for it, please get in touch. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Feel free to send a short sample of the script. I\'d be more than happy to send you a short audition to check my voice isÂ right for your show or project.</p>', 'July 2016', '1', 'Rise Project Explainer Video Voiceover', '0', '', 'Simple English Explainer Video Voice', '', '', '', '', '', '', '', '', ''),
(676, 'cbbc-pirate-week-voice', 'CBBC Pirate Week Voice', '<p>I went to London for this CBBC Pirate Week Voice. </p>', '', 'CBBC Pirate Week Voice -Â Ahoy there! The voice of a Pirate by uk based voice Guy Harris. Character voice demos on the website www.voiceoverguy.co.uk', '<h2>Check out the video</h2>\r\n<p>I\'d not yet been to the new Broadcast Centre for the BBC. What a great building and set up! Such amazing studios and I was using exactly the same mic as I do in my own studio. The Neumann U87. <a href=\"https://www.bbc.co.uk/cbbc\" target=\"_blank\" title=\"CBBC\">CBBC</a> ran Pirate Week on television and as a new daddy to my adorable daughter, the chance of working with CBBC was an easy decision in saying yes. Note: I\'ve since gone on to provide the <a href=\"santa-voice\" title=\"Santa Voiceover\">voice of Santa</a> for the Cbeebies\' show <a href=\"https://www.youtube.com/watch?v=yi-4Fm40nmE\" target=\"_blank\" title=\"GoJetters\">GoJetters</a>!</p>', '<h2>CBBC Pirate Week Voice</h2>\r\n<br>\r\n<p>I do get asked for my <a href=\"pirate-voice\" title=\"Pirate Voiceover\">Pirate voice</a> quite a lot in all fairness. Since my Lego Pirates trailer, <a href=\"pop-up-pirate-voiceover\" title=\"Pop up Pirate\">Pop up Pirate</a> and various other projects. With a few good pirate voiceovers in the bank, I find that I seem to be right at the front of the queue when someone is looking for a top quality pirate voice!</p>', 'cbbc-pirate-week-voice.jpg', '173228052', 'CBBC Pirate Week Voice - Pirate voice character by Guy Harri', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a promo, presentation or a product andÂ you need a voice for it? Maybe like this CBBC Pirate Week Voice. Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the production to quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. This way you can check if my voice isÂ right for your show or project.</p>', 'July 2016', '0', 'CBBC Pirate Week Voice', '3', '', 'Promo for CBBC Pirate Week....', '', '', '', '', '', '', '', '', ''),
(678, 'betfred-football-commentator', 'Betfred Football Commentator', '<p>It wasÂ EURO 2016 and I was asked to become the Betfred football commentator. </p>', '', 'Betfred Football Commentator -Â A fun viral video for Betfred. The UK-based bookmaker. As the main voice over and the character it was a fun project to voice', '<h2>Betfred Football Commentator Voice</h2>\r\n<p>Whenever a big football moment comes around, I always seem to get the call to bring my football commentator voice to life. It still makes me laugh, as I donâ€™t actually watch any footballâ€¦ yet I end up voicing campaigns for brands like <a href=\"manchester-city-football-commentry-voice\" title=\"Manchester City Football Voice\">Manchester City</a>, <a href=\"etisalat-celebrating-victory-football-commentator-voice\" title=\"Etisalat Football Commentator\">Etisalat</a>, <a href=\"just-eat-uefa-football-commentator-voice\" title=\"Just Eat UEFA Voice\">Just Eat</a> and <a href=\"turkish-airlines-football-commentator-voiceover\" title=\"Turkish Airlines Voice\">Turkish Airlines</a>.</p>\r\n\r\n<p>This Betfred campaign was a fun one. Fast-paced, character-driven and full of energy â€” the sort of tone clients ask for when they want a big, lively commentator read. My commercial work ranges from <a href=\"explainer-video-voice\" title=\"Explainer Voiceovers\">explainer videos</a> through to <a href=\"commercial-voiceover\" title=\"Commercial Voiceovers\">commercial campaigns</a>, so adapting the style is all part of the job.</p>', '<h2>Who Are Betfred?</h2>\r\n<p>Betfred is one of the UKâ€™s largest bookmakers, founded in 1967 in Salford by Fred and Peter Done. Today it has thousands of shops nationwide and a huge online presence. For this campaign they wanted a bold, energetic football commentator voice, and thatâ€™s exactly what I delivered.</p>\r\n\r\n<p>If youâ€™d like to hear more of this style, try my <a href=\"football-commentator-voice\" title=\"Football Commentator Voice\">main football commentator voice page</a> where youâ€™ll find extra demos and more brand examples.</p>', 'betfred-football-commentator.jpg', '173935797', 'Betfred Football Commentator - Video Character by Guy Harris', '<h2>Get in Touch</h2>\r\n<p>If you need a football commentator voice for your promo, online campaign, stadium content or comedy sketch, I can help. Just let me know the intended usage so I can quote accurately. If youâ€™re still pitching the idea, Iâ€™m happy to send over a short custom sample from your script.</p>\r\n\r\n<p>You can also explore other character styles I perform, such as my <a href=\"apple-voice-style\" title=\"Apple Style Voice\">Apple-style voice</a>, my <a href=\"david-attenborough-voice\" title=\"Attenborough Voice\">David Attenborough narration</a> or my <a href=\"santa-voice\" title=\"Santa Voice\">Santa voice</a>. Whatever your project, Iâ€™ll aim to record on the same day.</p>\r\n\r\n<div style=\"margin:20px 0;\">\r\n    <audio controls style=\"width:100%; max-width:420px;\">\r\n        <source src=\"https://www.voiceoverguy.co.uk/assets/audio/football-commentator-showreel-guy-harris.mp3\" type=\"audio/mpeg\">\r\n        Your browser does not support the audio element.\r\n    </audio>\r\n    <p style=\"font-size:0.9em; opacity:0.8; margin-top:5px;\">\r\n        Football Commentator Showreel â€“ Guy Harris\r\n    </p>\r\n</div>', 'July 2016', '0', 'Betfred football commentator voiceover Guy Harris', '0', 'betfred voiceover\",\"football commentator voice\",\"sports betting commercial voice', 'Betfred\'s football commentator voice...', '', '', '', '', '', '', '', '', ''),
(679, 'batelco-wifi-voice', 'Batelco WiFi Voice', '<p>An awesome animation and my Batelco WiFi voice over. Batelco is huge in Bahrain and now too is their WiFi Network.</p>', 'Explainer', 'Batelco WiFi Voice -Â You\'ll have heard my voice on other Batelco products. But check out how amazing the WiFi is in Bahrain thanks to these guys at Batelco.', '<h2>Check out the video</h2>\r\n<p>I voice quite a few products for Batelco on TV &amp; Radio in Bahrain so it was a pleasure to voice this too. <br>\r\nCheck out their <a href=\"https://www.youtube.com/channel/UCidTju2GUE0SzTclE_kJIZg\" target=\"_blank\">YouTube channel</a> for more of their products. Proud to voice Batelco\'s new explainer video, which is just one of the many <a href=\"explainer-video-voice\" title=\"Explainer Videos\">explainer videos</a> I\'m asked to voice every week. If you\'d like to see a couple of others, check out my <a href=\"bbk-travel-insurance-voiceover\" title=\"BBK Travel Insurance\">BBK Travel Insurance</a> and my  explainer video.</p>', '<br>\r\n<h2>Who are Batelco and what is special about their WiFi?</h2>\r\n<br>\r\n<p><em> <a href=\"https://batelco.com\" target=\"_blank\" title=\"Batelco\">Batelco</a> is the first and most advanced nationwide WiFi digital network in the Kingdom of Bahrain. Bahrain WiFi is a growing network of WiFi spots around Bahrain that help enhance connectivity. Look for Bahrain Wi-Fi icon to connect to Wi-Fi  on the go around the kingdom and upgrade the way you communicate.</em></p>', 'batelco-wifi-voice.jpg', 'fmvwqZ7ItxY', 'Batelco WiFi Voice - Explainer Video by Guy Harris', '<h2>Get in touch</h2>\r\n<p>DoÂ you have an explainer video, presentation or a <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">TV commercial</a> you need a voice for? Maybe like this Batelco WiFi voice over? Please <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage of the production to quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. This way you can check if my voice isÂ right for your show or project.</p>', 'July 2016', '1', 'Batelco WiFi Voice', '3', '', 'Batelco WiFi voice...', '', '', '', '', '', '', '', '', ''),
(680, 'voiceover-studio-finder', 'Voiceover Studio Finder ', '<p>Voiceover Studio Finder allows voices to book one while travelling, and agencies the chance to book one nearer the artist.</p>', 'recording', 'Voiceover Studio Finder -Â Find your nearest voice over studio. Hire yours to make extra money. Need to find a studio? Studios listed worldwide. Add yours today!', '<h2>Why create this listings site?</h2>\r\n<p>Firstly, I\'ve made money hiring my studioÂ to other voices including actors from Emmerdale. Secondly, I read a blog from a fellow voice artist He talked of looking for nearby studios when he was away.<br>\r\nI felt there was a gap in the market to create something that not only helped other voices but a facility to help agencies book actors or voices into nearby studios without the expense of getting them to major cities. <em>\"There are some great studios outside the big cities\"</em></p>', '<h2>How does it work?</h2>\r\n<br>\r\n<p>Sign up for free. Create a profile and add some pictures and header. Detail what you offer and highlight your location anywhere in the world. Thats it!<br>\r\n\r\nNot only does having a page have some nice benefits back to your own site, but if you have a web site thats a bit out of date or it costs you lots to update it, then we\'ve made it super easy for you to customise and update your page.</p>', 'voiceoverstudio-finder.jpg', 'VO0jENx53VE', 'Voiceover Studio Finder - Hire or Be Hired - List yours Free', '<h2>Using Studio Finder</h2>\r\n<br>\r\n<p>Everything begins at the search bar on the <a href=\"https://voiceoverstudiofinder.com\">homepage</a>. Either click Current Location, or enter the destination you are at and click Find Studios. Choose a radius of how far you are prepared to travel. If something pops up, click the page to read more.<br>\r\n\r\nIf you want to book the studio, the contact form allows you to deal direct with the studio. The website acts purely as a listing service.<br>\r\n\r\nWe\'ve also teamed up with <a href=\"http://source-elements.com/\" target=\"_blank\">Source Elements</a> to allow you to embed Source Connect NOW into your profile. This is an awesome feature. Add your SCN username and thats it. It allows your client to connect with you on your profile page where they can also read more about you during a voice session.<br>\r\n\r\nWe do have the voiceover studio finderÂ <a href=\"https://voiceoverstudiofinder.com/upgrade\" target=\"_blank\">premium membership</a> which allows a whole bunch of extra features for very little money too. (This helps fund the development of the site)<br>\r\n\r\nThere is also the option to become a verified studio. With a great profile of quality content and active social media activity, will give you a chance to be verified.<br>\r\n\r\nSo, why not sign up? If you are a recording studio or a voiceover with a great studio and you\'d like to make some extra money when you are not working, <a href=\"https://voiceoverstudiofinder.com/register\" target=\"_blank\">join for free</a> today.<br>\r\n\r\nPlease do also visit <a href=\"https://voiceoverstudiofinder.com/VoiceoverGuy\" target=\"_blank\">my page</a> on the site.</p>', 'Oct 2016', '1', 'Voiceover Studio Finder', '0', '', 'How do I find a Voiceover Studio?', '', '', '', '', '', '', '', '', ''),
(681, 'worms-wmd-character-voices', 'Worms WMD Character Voices', '<p>Back in the booth for Worms WMD Character Voices.</p>', '', 'Worms WMD Character Voices - Back again with Team 17. This is my 4th game in the WORMS series. Based on the doorstep it\'s great to be voicing again.', '<h2>Check out the video</h2>\r\n<br>\r\n<p>This is now the 4th WORMS game I\'ve provided voices for, so it\'s safe to say I have a good relationship with Team 17. I love working with them, and it helps that they\'re not based too far away from my house, so I can go to their studios directly. Although it\'s fun, providing various characters\' voices is an exhausting session as each character has pages of lines for the games. The most fun part is providing all the jumping and landing noises. I\'ve provided plenty of <a href=\"game-trailer-voice\" title=\"Games Trailer Voiceovers\">games trailer voiceovers</a>, such as Draw Slasher and the tutorial voice for the <a href=\"world-of-warships-tutorial-voice\" title=\"World of Warships Tutorial Voice\">World of Warships game</a>.</p>', '<h2>What is Worms WMD?</h2>\r\n<br>\r\n<p>WORMS WMD  is available in August and no doubt will be another hit with fans of this iconic game. Much of the game play is the same as in previous games, it\'s just that there are even more weapons for you to reign down destruction on your pals! It\'s strange hearing all of the different individual worms\' voices and to recognise my own voice there...</p>', 'worms-wmd-character-voices.jpg', 'ttcUCCYa7Uk', 'Worms WMD Character Voices - Voice Acting - Guy Harris', '<h2>Get in touch</h2>\r\n<p>If you are working on a game and looking for more something like Worms WMD Character VoicesÂ then please do <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage of the project and I can quote you more accurately. Feel free to send a short sample of the script andÂ I\'d be more than happy to send you a short audition to check if my voice isÂ right for your show or project.</p>', 'Aug 2016', '1', 'Worms WMD Character Voices', '0', '', 'Worms WMD Character Voices...', '', '', '', '', '', '', '', '', ''),
(682, 'winterstate-trailer-voice', 'Winterstate Trailer Voice', '<p>I\'ve said it many times, I love game trailers. Working with some fantastic production houses, the end result is always spectacular.</p>', '', 'Winterstate Trailer Voice - \'Tactical Combat Trader\' for touch screen devices! I love voicing game trailers. If I can do yours, let me know - VoiceoverGuy', '<h2>Check out the video</h2>\r\n<p>It was a lot of fun to provide a different voice style for Winterstate\'s trailer. They asked me for an army-style American accent and, although it\'s not my most common voiceover style, it\'s a voice I have plenty of experience with. If you\'re interested in this kind of voiceover, you should check out my <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voiceover\">game trailer voiceovers</a> and for more examples of my American voiceovers, check out my <a href=\"a-team-voice\" title=\"A Team Voiceover\">A Team Voice</a> and my <a href=\"lifeless-game-trailer-voice\" title=\"Lifeless Game Trailer\">Lifeless game trailer</a>.</p>', '<h2>What is <a href=\"https://twitter.com/winterstategame\" title=\"What is Winterstate\">Winterstate</a>?</h2>\r\n<br>\r\n<p>Knuckle Sam needs YOU - download now to reclaim the nation! Take command of a convoy of deadly fighting vehicles, as you hit the road with the legendary Knuckle Sam and his band of Runners. Under the banner of Sam\'s Winterstate youâ€™ll build a powerful force, repel the raiders and take the fight back to The Code - a mysterious, deadly threat emerging from the West.</p>', 'winterstate-trailer-voice.jpg', 'FpXaS3fvggI', 'Winterstate Trailer Voice | Game Trailer | Guy Harris', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a game waiting to finish it with a trailer?Â Do you need a voice track similar to thisÂ Winterstate Trailer VoiceÂ ? Please <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Do send a sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your show or project. Please do get in touch today.</p>', 'Aug 2016', '1', 'Winterstate Trailer Voice', '0', '', 'Winterstate trailer voice...', '', '', '', '', '', '', '', '', ''),
(687, 'phoenixpb-explainer-video-voice', 'PhoenixPB Explainer video voice', '<p>Here is my PhoenixPB Explainer video voice. I really love this video. First, I had an awesome voice session with the client listening in and directing it. Second, the script was written beautifully. Third, the end product looks fantastic.</p>', '', 'PhoenixPB Explainer video voice -Â Media monitoring, media evaluation, journalist databases, social media and more. Another great animated Video Voiceover.', '<h2>Check out the video</h2>\r\n<br>\r\n<p><a href=\"explainer-video-voice\" title=\"Explainer videos\">Explainer videos</a> make up a huge amount of my work. This kind of video is getting more and more popular as businesses realise how effective they are â€” especially if you have a complex or high-tech product or service that you need to explain to your target audience. Explainer videos are easy to consume and it\'s a genre I feel most comfortable in. If you\'d like to see more, you may like to check out my <a href=\"home-composting-explainer-voice\" target=\"_blank\" title=\"Home Composting Explainer Video\">home composting</a> explainer video.</p>', '<h2>Who are PhoenixPB?</h2>\r\n<br>\r\n<p>PhoenixPB is a specialist agency focusing on media monitoring, media evaluation, journalist databases, social media and more...</em> PhoenixPB has a complex offering of services and an explainer video is the best way to do justice to everything it offers clients!\r\n<p><em>Whatever you need, our bespoke cost effective service will be created around you and your budget.</em></p>', 'phoenixpb-xplainer-video.jpg', '22hxKsJPEpI', 'PhoenixPB Explainer video voice | animated videos | Guy Harr', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style? Or perhaps something else from my <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover showreel</a> Please get in touch. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Aug 2016', '1', 'PhoenixPB Explainer video voice', '3', '', 'PhoenixPB Explainer video voice...', '', '', '', '', '', '', '', '', ''),
(689, 'david-attenborough-impression', 'David Attenborough Impression', '<p>Here is my David Attenborough Impression for Biffa. I really love this video. First, I had an awesome voice session with the client listening in and directing it. Second, the script was written really well. Third, it turned out amazing.</p>', 'explorer, Biffa, impersonation', 'David Attenborough Impression - Biffa wanted to promote Wasteaters. They wanted a fun voice to accompany this beautiful shot video. I think we nailed it.', '<h2>Who are the Wasteaters?</h2>\r\n<p>Towns and cities across the UK are currently being invaded by mysterious creatures known as the â€˜Wasteaters\'. These elusive beasts set off in the middle of the night to scour the streets for anything they can get their teeth into. <br>\r\nMilk cartons, magazines, anything you might have thrown away during your busy day is being eaten by the Wasteaters. <a href=\"https://www.biffa.co.uk/\" target=\"_blank\" title=\"Biffa\">Biffa</a> specialises in domestic and business waste removal, which is a necessary, but not-so-glamorous service, so it\'s great to see them putting so much work into their commercials.</p> ', '<br>\r\n<h2>David Attenborough Impression</h2>\r\n<p>I\'ve been practicingÂ impressions for as long as I can remember. I used to mimic the teachers at school and I did a pretty spot-on impression of my doctor. But everyone interested in impressions will always gravitate to the biggest, most iconic voices, and it\'s hard to think of a voice more iconic that Sir David Attenborough\'s. If you\'d like to hear more like this, check out my <a href=\"david-attenborough-voice\" target=\"_blank\" title=\"David Attenborough Voiceover\">David Attenborough voiceover page</a>. I love voiceover, but I never thought I\'d be get so many jobs because of my David Attenborough voice!. Even BBC\'s Strictly Come DancingÂ is now on my client list for this style too.</p>', 'david-attenborough-impression.jpg', '09ulDo-3reM', 'David Attenborough Impression | Biffa Waste Eaters', '<h2>Get in touch</h2>\r\n<p>I think we pulled this off fantastically. I\'m really happy how it turned out. DoÂ you have <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a> that needs a <a href=\"character-voiceover\" target=\"_blank\" title=\"Character Voiceover\">character voice</a>? One similar to thisÂ David Attenborough Impression? Please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your show or project. Please do get in touch today.</p>', 'Sep 2016', '1', 'David Attenborough Impression', '3', '', 'Biffa David Attenborough Impression', '', '', '', '', '', '', '', '', ''),
(691, 'vodafone-natural-voiceover', 'Vodafone natural voiceover', '<p>A beautifully shot piece for personal tariffs on the phone network giant Vodafone.</p>', 'explainer web video', 'Vodafone Natural Voiceover -Â A beautifully shot promo for Vodafone. Turned out really nice. I was asked for a casual read style. For more check my website.', '<h2>A natural voice style</h2>\r\n<p>When Tom approached me, I had a look at his work and immediately jumped at the chance to work with him. Just take a look at some of his other projects. He\'s an incredibly creative guy.<br>\r\nTom had heard my natural voiceover work on some of my various <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial ads</a> and <a href=\"explainer-video-voice\" title=\"Explainer Video Voiceover\">explainer videos</a> and wanted something similar. I was so proud when I saw how it sounded on the video itself. I love the way this was shot. The grading on it too is beautiful.</p>', '<br>\r\n<h2>Who is Tom?</h2>\r\n<p>Tom Schlagkamp infuses his work with his love of music so itâ€™s not surprising when he won the first place prize at the Cannes Young Director Awards for â€œRock â€˜nâ€™ Roll Manifesto.â€Â  He transitioned into film at RTL Germany, where he learned editing and motion graphics, and began shooting commercials, shorts, and music videos. He went on to study at UCLA and Filmakademie Baden-Wuerttemberg, and was quickly pegged as a rising director?</p>', 'vodafone-natural-voiceover.jpg', 'eNfJBWtsHc4', 'Vodafone Natural Voiceover | Voice over by Guy Harris', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a promo or explainer video in need of a voice? SimilarÂ to thisÂ Vodafone voiceover? To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Send a sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your show or project. Please use the form and  say hi.</p>', 'Oct 2016', '1', 'Vodafone Natural Voiceover', '5', '', 'My natural voiceover for Vodafone...', '', '', '', '', '', '', '', '', ''),
(693, 'pop-up-pirate-voiceover', 'Pop up Pirate Voiceover', '<p>AnotherÂ television commercial featuringÂ my Pop up Pirate Voiceover. Clearly another winner by TOMY. A sure fire hit for kids at Christmas.<br>\r\n\r\nAlthough I\'m quite comfortable doing lots of <a href=\"character-voiceover\">Character voices</a>, I do like to specialise in a handful. I don\'t want to be the guy that claims to do hundreds of voices. However I do feel very at home as the voice of a Pirate.</p>', 'kids toys', 'Pop up Pirate Voiceover -Â New from TOMY. So, they needed a Pirate voice. For the authentic voice of a pirate, ye knows where to come!. Check me Pirate page!', '<h2>Check out the video</h2>\r\n<br>\r\n<p>From television and radio to events and video games, I\'ve voiced quite a lot in this <a href=\"pirate-voice\" title=\"Pirate voice\">Pirate voice</a> style. Working with Lego, I not only voiced the trailer for it but I also played the <a href=\"lego-minifigures-pirate\" title=\"Pirate Captain Voice\">Pirate Captain Voice</a> in the game too. I base my characterisation on that of Captain Barbossa from the Pirates of the Caribbean movie. CBBC loved my <a href=\"cbbc-pirate-week-voice\" title=\"Pirate Voice for CBBC\">Pirate Voice</a> on a promo too. If ye be looking for a pirate, you just found him.</p>', '<h2>Pop up Pirate Voiceover</h2>\r\n<br>\r\n<p>Pop up Pirate works like all the best suspense games, where you have to each take it in turns putting swords into the barrel. If you put the sword into the wrong place, the pirate will pop out and you\'ll have lost. It\'s funny how many great kids games games have been based on Russian roulette! This game is great fun and it was really enjoyable to provide my voiceover for the TV ad.</p>\r\n', 'pop-up-pirate-voiceover.jpg', 'PasOj-DR9Es', 'Pop up Pirate Voiceover | Need a Vader voice? | by Guy Harri', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a event, a gameÂ or featureÂ in need of <a href=\"pirate-voice\" target=\"_blank\" title=\"Pirate Voiceover\">pirate voiceover</a> Pirate? A styleÂ similarÂ to this Pop up PirateÂ Voiceover? DoÂ get in touch. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your show or project, <a href=\"mailto:guy@Voiceoverguy.co.uk?subject=VoiceoverGuy Website Enquiry\" title=\"Email Guy direct now\">Get in touch</a> today!</p>', 'Sep 2016', '1', 'Pop up Pirate Voiceover', '0', '', 'TV AD VoiceOver for Pop up Pirate!', '', '', '', '', '', '', '', '', ''),
(694, 'change-challenge-gameshow-voice', 'Change Challenge Gameshow Voice', '<p>PAYM needed the Change Challenge Gameshow Voice. Having voiced many videos and promos and even tv commercials in this style, it was a pleasure to help.</p>', '', 'Change Challenge Gameshow Voice -Â PAYM was touring round the country promoting the mobile payments service. They needed this quiz show host voice. They WON!', '<h2>Check out the video</h2>\r\n<br>\r\n<p>Another <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercial voiceover</a> in the bag! This series of videos ran on social media to promote the events happening around the UK in September and October 2016.<br>\r\nEmbarrassingly for PAYM, this has still not been paid for. I\'m so angry with the production company Burning Desire.</p>', '<h2>What is PAYM?</h2>\r\n<br>\r\n<p><em>Well, they are the UK\'s mobile payments service.</em></p>\r\n\r\n<p><em>You can now pay friends, family and small businesses using just their mobile number.\r\nThereâ€™s no need to tell people your sort code or account number, or ask for theirs (provided theyâ€™ve done the sensible thing and registered too).</em></p>', 'change-challenge-gameshow-voice.jpg', 'B3FiqvXTeX8', 'Change Challenge Gameshow Voice | Character voice | Guy Harr', '<h2>Get in touch</h2>\r\n<p>For more of my <a href=\"gameshow-host\" title=\"Gameshow Host Voiceover\">gameshow host</a> work in this style, have a listen to the promo I voiced for BBC Radio 1. DoÂ you have a product or website video in need of a voice? A styleÂ similar to theÂ Change Challenge Gameshow Voice? Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your show or project. Please do get in touch today.</p>', 'Sep 2016', '1', 'Change Challenge Gameshow Voice', '0', '', 'Change Challenge Gameshow...', '', '', '', '', '', '', '', '', ''),
(695, 'greedy-granny-tv-commercial', 'Greedy Granny TV Commercial', '<p>TOMY called wanting a voice for the Greedy Granny TV Commercial.</p>', 'kids toys', 'Greedy Granny TV Commercial -Â Another great toy from TOMY. Sure to be another big toy of 2016. This hushed voiceover style by Guy Harris. Check the website.', '<h2>Check out the video</h2>\r\n<br>\r\n<p>In 2016 I voiced many Kid\'s TV adverts and rapidly becoming more well known for doing so. <br>\r\nUsually the brief asks for energy and excitement, something I find rather easy to deliver.<br>\r\nJust like <a href=\"pop-up-pirate-voiceover\" title=\"Pop-up Pirate\">Pop-up Pirate</a>, it\'s always a pleasure working with TOMY.</p>', '<h2>So you want to know more about Greedy Granny?</h2>\r\n<p><em>Granny loves biscuits! So much so that she\'s fallen asleep with a whole tray of them on her lap. Your mission is to take a biscuit of each type from Granny\'s tray as carefully and quietly as you can. One wrong move will wake her and send her teeth flying! Greedy Granny is a new and mischievous game from <a href=\"https://uk.tomy.com\" target=\"_blank\" title=\"TOMY\">TOMY</a>. Greedy Granny is full of suspense and will have everyone on the edge of their seats. Will you risk it for a biscuit? Or will your move wake Granny?</em></p>', 'greedy-granny-tv-commercial.jpg', '184425977', 'Greedy Granny TV Commercial | Hushed voice | Guy Harris', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV commercial or promoÂ in need of a voice</a>? A style hushed or whispered one similar to this Greedy Granny TV Commercial? Please get in touch. To make the process even easier, just let me knowÂ the intended usage of the production and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your show or project. Please do get in touch today.</p>', 'Oct 2016', '0', 'Greedy Granny TV Commercial', '0', '', 'The Voice of Greedy Granny TV Advert', '', '', '', '', '', '', '', '', ''),
(698, 'lifeless-game-trailer-voice', 'Lifeless Game Trailer Voice', '<p>This is the Lifeless Game Trailer Voice over. Not quite my <a href=\"movie-trailer-voice\" title=\"Movie Trailer Voice\">movie trailer voice</a> but they wanted something American and dark. </p>', 'Deep american', 'Lifeless Game Trailer Voice -Â A close mic voice delivery for this awesome game. Stunning gameplay and an awesome soundtrack. Will you survive?', '<h2>Check out the video</h2>\r\n<br>\r\n<p>I opted for a very close mic delivery and I think the end result is pretty cool. Video games are becoming more and more incredible and my <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Game Trailer Voice\">computer game trailer voice</a> is becoming a bigger part of my workload! The gaming industry is huge, so budgets are getting bigger, technology is getting more advanced and the game play is stunning. <br>I\'m still proud to be working in this area of voice over.</p>', '<h2>So, tell me more about Lifeless</h2>\r\n<br>\r\n<p>Lifeless is set in May 2021, ten years have passed since patient zero. Ten years since the world turned into an infected wasteland... Two factions fight over resources, whilst battling an ever growing menace of infected humans. How will you choose to survive?<br> This is a great game and it\'s proving very popular. If it sounds like your cup of tea, make sure you check it out!</p>', 'lifeless-trailer-voice.jpg', 'dPuhuNi6NQw', 'Lifeless Game Trailer Voice | Sargeant Major Voice |', '<h2>Get in touch</h2>\r\n<p>DoÂ you have an game or trailer in need of a powerfulÂ or deep voice for your <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">web or TV commercial</a>? Maybe a voice with impact like this Lifeless Game Trailer Voice? Please get in touch. To make the process even easier, just let me knowÂ the intended usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your show or project. Please do get in touch today.</p>', 'Oct 2016', '1', 'Lifeless Game Trailer Voice', '0', '', 'My Lifeless Game Trailer Voice', '', '', '', '', '', '', '', '', ''),
(700, 'war-friends-army-voice', 'War Friends Army Voice', '<p>I loved providing the War Friends Army Voice for the game trailer. </p>', 'game trailer sergeant major', 'War Friends Army Voice -Â My 4th game playing worms characters, I was asked back in the voiceover booth to play a Sargeant Major Voice. A great end result.', '<h2>Check out the video</h2>\r\n<br>\r\n<p>Yes, Chillingo are back with a fantastic new game. <i>Go to war with your friends and become the worldâ€™s best squad.</i> The first request to try was an army sargeant style. I tried it, they liked it and that was that. Nice! I love voicing <a href=\"game-trailer-voice\" target=\"_blank\" title=\"Computer Game Voiceover\">game trailers</a> as I\'ve said on so many occasions. I do seem to get a lot of this style of work, so I must be doing something right! This trailer plays on their <a href=\"https://play.google.com/store/apps/details?id=com.chillingo.warfriends.android.gplay&hl=en_GB\" target=\"_blank\" title=\"War Friends Google Play\">Google Play</a> page and I think the game looks like a lot of fun. I\'ve also voiced game trailers for <a href=\"siegecraft-commander-trailer-voice\" target=\"_blank\" title=\"Seigecraft Commander\">Seigecraft Commander</a>, <a href=\"warwings-game-trailer-voice\" target=\"_blank\" title=\"War Wings\">WarWings</a> and <a href=\"worms-wmd-character-voices\" target=\"_blank\" title=\"Worms WMD\">Worms WMD</a> , so it\'s quickly becoming one of my most common voiceover jobs!</p>', '<h2>War Friends Army Voice</h2>\r\n<br>\r\n<p>So, lets look closer at War Friends.</p>\r\n<p><em>Â Join together with your friends against your enemy. Create a powerful team and go to the battle field. Dynamic battles and engrossing missions are waiting for you. Be attentive as your enemy may hide anywhere!</em> This looks like a really fun game and I think my voiceover complements it well. I\'m always enthusiastic about my work, but it\'s even easier to be enthusiastic when I\'m talking about toys, games, and movies!</p>', 'war-friends-army-voice.jpg', '-rAockr9los', 'War Friends Army Voice | Sargeant Major Voice | Guy Harris', '<h2>Get in touch</h2>\r\n<p>Are you looking for this voice style? Please <a href=\"contact-guy\" target=\"_blank\" title=\"Contact Guy\">get in touch</a> and let\'s chat. I\'d be veryÂ happy to send a short sample of your script to you before you book me. Please send a few lines of the script first so you can be sure I\'m right for your brand. I make theÂ whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Oct 2016', '1', 'War Friends Army Voice', '3', '', 'War Friends Army Sergeant voice', '', '', '', '', '', '', '', '', ''),
(703, 'girafun-voiceover', 'Girafun Voiceover', '<p>The amazing Girafun Voiceover was one that required a really big voice for the brand new trailer.</p>', 'kids toys', 'Girafun Voiceover -Â Another tv commercial for Girafun. I do get a lot of work for Kids toys. I think it\'s just that excitable smily voice. Need one?', '<h2>Girafun TV Ad</h2>\r\n<p>I think it\'s safe to say that I\'ve cracked the toy and board game markets... I\'ve provided voiceover for loads of these kinds of ads, including <a href=\"pop-up-pirate-voiceover\" title=\"Pop-up Pirate\">Pop-up Pirate</a> and <a href=\"articulate-game-voiceover\" title=\"Articulate\">Articulate</a>. Take a look at a range of my other <a href=\"commercial-voiceover\" title=\"Commercial Voiceover\">commercials</a> to get a feel for my different voices, styles, and capabilities.</p>', '<h2>What is Girafun?</h2>\r\n<p>Girafun is a great little board game is a giraffe-based game where you eat fruit to lengthen your neck, collect a hat and then rush back home to win the game. Giraffes are clearly a fun animal, so I wonder why no one else made a giraffe game before this! Girafun was made by Megableu, one of the biggest toy company in Europe. IIt was lots of fun working with the folks at Megableu again. They\'re one of the biggest names in the toy industry and I have a good working relationship with them.</p>', 'girafun-voiceover.jpg', 'GwbZCNQ1BPw', 'Girafun Voiceover | Kids Toys TV Adverts | voice of Guy', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a commercialÂ in need of a voice? Maybe a voice like this Girafun Voiceover? Please get in touch. To make the process even easier, just let me knowÂ the intended usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. For rates and availability, <a href=\"mailto:guy@Voiceoverguy.co.uk?subject=VoiceoverGuy Website Enquiry\" title=\"Email Guy direct now\">Get in touch</a> today!</p>', 'Nov 2016', '1', 'Girafun Voiceover', '0', '', 'Wacky kids tv promo voice', '', '', '', '', '', '', '', '', ''),
(707, 'marvel-superheroes-voiceover', 'Marvel Superheroes Voiceover', '<p>My Marvel Superheroes Voiceover approved by the big guys too. This for the kids brand Rubie\'s to promote their amazing range of outfits.</p>', '', 'Marvel Superheroes Voiceover -Â Kids tv commercials are another of my favourite genres, not just because my daughter will get to hear me. Full of energy', '<h2>Marvel Superheroes Voiceover</h2>\r\n<p>I\'m asked to voice a lot of kids\' toys TV adverts these days. I\'d like to think it\'s because I can approach the script with a youthful energy... But I also suspect it\'s because my voice is gradually featuring in more and more kids\' ads, so brands hear my voice in an ad and decide they want me for their kids\' product. Take a look (or a listen) at my other Marvel costume ad, this time for <a href=\"marvel-spiderman-voiceover\" target=\"_blank\" title=\"Spiderman Kids\' Costume\">Spiderman</a>. As I mentioned with this Spiderman costume ad, Marvel had to approve my voice before I was booked. That was a long five-week wait. Still, the end result is awesome and I\'m proud to be associated with one of the biggest brands in the World!</p>', '<h2>Check out the video</h2>\r\n<p>Lets face it, Marvel is huge and children absolutely love dressing up as their favourite heroes! Rubie\'s has been around since 1951, and it makes the best kids costumes and they\'ve been updating many of their superhero costumes recently. If you have a fancy dress party coming up for your children, you should absolutely check them out. Check out their website, which has a huge range of costumes at very competitive prices. This isn\'t the first time my voiceover has been associated with Marvel, and I hope it won\'t be the last; you might also like to check out my <a href=\"disney-store-marvel-voiceover\" target=\"_blank\" title=\"Disney Store Marvel Ad\">voiceover for the Disney Store Marvel ad</a>!</p>', 'marvel-superheroes-voiceover.jpg', 'iWokTfshIxM', 'Marvel Superheroes Voiceover | Kids Toys TV Advert | by Guy ', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial</a>Â in need of a voice? Maybe a voice like this Marvel Superheroes Voiceover? Please get in touch. To make the process even easier, just let me knowÂ the intended usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your project. Please do get in touch today.</p>', 'Nov 2016', '1', 'Marvel Superheroes Voiceover', '0', '', 'Disney - Marvel Superheroes Voiceover', '', '', '', '', '', '', '', '', ''),
(709, 'bank-sohar-explainer-voiceover', 'Bank Sohar Explainer Voiceover', '<p>One of the many explainers I voice each week. A market I know well and I\'m trusted by well known brands on a daily basis.</p>', '', 'Bank Sohar Explainer Voiceover -Â If you are looking for an experienced pro male voiceover artist for your explainer video, then you\'re in safe hands.', '<h2>Check out the Bank Sohar App Explainer video</h2>\r\n<p>I\'m a trusted and well-respected British male voice over. I\'ve spent a lot of time and effort developing my natural and conversational style and, as as result, I get many requests for this kind of voiceover each week. It was great working with the team at Bank Sohar and I think they have a pretty nifty app, so it was easy to do it justice with my voiceover. Since the <a href=\"apple-voice-style\" target=\"_blank\" title=\"Apple Commercial Voiceover\">Apple commercials</a>  a few years back, <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video voiceover </a> is the style I\'m asked for most often. It\'s used on web videos and short promotional videos when the product or service is complicated enough that a normal <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial ad</a> isn\'t long enough to do it justice.</p>', '<br>\r\n<h2>Bank Sohar Explainer Voiceover</p>\r\n<p><em><a href=\"https://twitter.com/Sohar_intl\" target=\"_blank\" title=\"Bank SoharÂ S.A.O.G\">Bank SoharÂ S.A.O.G</a> is one of the fastest growing banks in Oman. They help consumers and corporate businesses to fulfill their banking needs.</em> In recent years, all of the best banks have dedicated time and money to developing banking apps. Modern life can get more than a little hectic and we don\'t often have time to visit an actual bank in person, so banking apps allow us to stay on top of our finances easily, when it suits us. You can get hole of the Bank Sohar app on both android and Apple iOS !</p>', 'bank-sohar-explainer-voiceover.jpg', 'Pmc1xV_EOPE', 'Bank Sohar Explainer Voiceover | web videos voiced by Guy', '<h2>Get in touch</h2>\r\n<p>DoÂ you have an explainer video in need of a professional male voice over artist? Maybe a voice like this Bank Sohar explainer voiceover? Please <a href=\"contact-guy\" title=\"Contact Guy\">get in touch</a>. To make the process even easier, just let me knowÂ the intended usage, and I can quote you more accurately. Send a sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your project.</p>', 'Nov 2016', '1', 'Bank Sohar Explainer Voiceover', '3', '', 'Explainer video voiceover for Bank Sohar', '', '', '', '', '', '', '', '', '');
INSERT INTO `messages2` (`id`, `url`, `page_title`, `info`, `search_terms`, `page_desc`, `text1`, `text2`, `image`, `video`, `meta_title`, `bottomtext`, `date`, `whatvideo`, `alt`, `rating`, `twitter`, `hometext`, `santa`, `ntext1`, `ntext2`, `ntext3`, `ntext4`, `nimage1`, `nimage2`, `nimage3`, `nimage4`) VALUES
(710, 'marvel-spiderman-voiceover', 'Marvel Spiderman Voiceover', '<p>Here is my Marvel Spiderman Voiceover for Rubie\'s. The 2nd advert broadcast on TV in 2016. Kids toys adverts seem to like my energy and excitement I put into this genre.</p>', '', 'Marvel Spiderman Voiceover -Â Approved by Marvel, Back on your tv for Rubies, advertising the Spiderman Costumes. Got a fancy dress coming up? Check them out', '<h2>Marvel Spiderman Voiceover</h2>\r\n<p>Marvel is such Â huge company, so getting the call was quite exciting. Waiting for approval was a little nerve racking. After a five-week wait, I finally received a yes and was over the moon. I tend to get a lot of children\'s adverts, which I think is down to the bright tone of voice I use in most of my kids ads in my <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">commercial voiceover showreel</a>. Listen to the whole showreel and explore my <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Video Voiceover\">explainer video</a> and <a href=\"movie-trailer-voice\" target=\"_blank\" title=\"Movie Trailer Voiceover\">movie trailer voiceovers</a> to hear the different styles available for your next project. Rubies\' Spiderman suit is just one of my many commercials for kids toys you\'ll see on the television. Especially close to Christmas. Of course, if I\'m not voicing toy ads, I\'m usually the <a href=\"santa-voice\">voice of Santa</a>.</p>', '<h2>Check out the video</h2>\r\n<p>Rubies know a thing or two when it comes to kids\' costumes. They\'ve been in the industry since 1951, when they were founded in Queens, in New York City. They started out as a candy story, but gradually expanded to sell comics and other comic book paraphernalia. Today, Rubie\'s is an international costume designer, specialising in kid\'s costumes. Rubie\'s designs look great and they\'re very hard-wearing, which shows that they clearly understand their target audience. This job was also done in collaboration with Marvel and the final product can be found at Smyths. I\'ve voiced so many toy commercials, including a <a href=\"bugs-in-kitchen-voice\" target=\"_blank\" title=\"Bugs in the Kitchen ad\">Bugs in the Kitchen ad</a> and a <a href=\"pop-up-pirate-voiceover\" target=\"_blank\" title=\"Pop-up Pirate ad\">Pop-up Pirate ad</a>!</p>', 'marvel-spiderman-voiceover.jpg', 'kQlB8iO4ZUc', 'Marvel Spiderman Voiceover | Kids fancy dress costumes ', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a TV advertÂ or promo in need of a voice? Maybe one just like this Marvel Spiderman Voiceover? Please get in touch. To make the process even easier, just let me knowÂ the intended usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your project. Please do get in touch today.</p>', 'Nov 2016', '1', 'Marvel Spiderman Voiceover', '0', '', 'Marvel Spiderman Voiceover for Rubies', '', '', '', '', '', '', '', '', ''),
(711, 'hill-climb-racing-2-voiceover', 'Hill Climb Racing 2 Voiceover', '<p>My Hill Climb Racing 2 Voiceover on part 2. They asked me for a movie trailer voice and a hill billy. I gave it a try and I think it turned out really nice. </p>', 'Hill billy', 'Hill Climb Racing 2 Voiceover - A movie trailer Voice and a Hill Billy? That was the request. I said lets give it a go. I like how it turned out.', '<h2>Check out the Hill Climb Racing 2 video</h2>\r\n<p>It\'s not oftenÂ I\'mÂ asked to combine an <a href=\"movie-trailer-voice\" target=\"_blank\" title=\"Movie Trailer Voiceover\">epic movie trailer voice</a> with a hill biilly voice... But the unpredictability of this job is part of what I love so much about it! I hope they ask me back for trailer 3 too! <a href=\"game-trailer-voice\">Game trailers</a>Â are fun to do and I\'ve done a lot more in recent years.Â Do check out some of my others on the link above! I love this genre of work because there is emphasis on fun right from the start and I get to work with some incredibly talented graphic and game designers.</p>', '<h2>Hill Climb Racing 2 Voiceover</h2>\r\n<p><em>Newton Bill is Back! After journeying to where no ride has been before, Bill is ready to challenge the whole world in Hill Climb Racing multi player madness.</em> Hill Climb Racing 2 is the sequel to the most addictive and entertaining physics-based driving game ever! And it\'s free on <a href=\"https://apps.apple.com/us/app/hill-climb-racing-2/id1146465836\" target=\"_blank\" title=\"Hill Climb Racing 2 iOS\">iOS</a> and <a href=\"https://play.google.com/store/apps/details?id=com.fingersoft.hcr2&hl=en_GB\" target=\"_blank\" title=\"Hill Climb Racing 2 Google Play\">Google Play</a>! This game takes a lot from motocross and dirt-bike racing, inviting anyone with a smart phone to do some crazy jumps on a variety of vehicles whilst staying in one piece. It\'s impressive that a mobile game like this has an online-play feature. This game is a lot of fun and it was great fun to provide two different voices for the trailer.</p>', 'hill-climb-racing-voiceover.jpg', '193248580', 'Hill Climb Racing 2 Voiceover | Game Trailers | voice of Guy', '<h2>Get in touch</h2>\r\n<p>DoÂ you have a commercialÂ in need of a voice? Maybe a voice like this Girafun Voiceover? Please get in touch. To make the process even easier, just let me knowÂ the intended usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your project. Please do get in touch today.</p>', 'Dec 2016', '0', 'Hill Climb Racing 2 Voiceover', '3', '', 'They asked me for my movie voice...', '', '', '', '', '', '', '', '', ''),
(712, 'rakbank-voiceover', 'Rakbank Voiceover', '<p>This Rakbank voiceover was used on this promotion for Home in One. On a daily basis I\'m asked to put my voice on many <a href=\"explainer-video-voice\">Explainer videos</a>. I understand this genre very well and am very comfortable working with big name brands. If your looking for a natural delivery on your next project, do check out some of my <a href=\"crowd-hub-x-explainer-video-voiceover\">other work</a> with big brands.</p>', 'Explainer', 'Rakbank Voiceover -Â Working with Rakbank for many years, I\'ve been busy working on more explainer videos. Here is a nice natural conversational voiceover.', '<h2>Check out the video</h2>\r\n<p>Explainers are big business and a website almost feels incomplete unless there is a short video highlighting the reasons for using them. Explainer videos are especially useful when you have a product or service that is a little too complex to explain with a normal ad. If your product or service is better than your competitors, then an explainer video can help you explain why this is. If you\'re convinced that an explainer video will help your business, you\'ll need a production company. Once you\'ve found a great production company, let them know about my work. Or, if you need a few pointers, I\'m more than happy to recommend one of the many awesome creative teams I work with every week.</p>', '<h2>Here is more information about Home in One.<h2>\r\n<p><em>Rakbank Home in One is a mortgage loan that pays you interest. Home in One links your current account balances to your mortgage facility, in order to reduce the mortgage balance youâ€™re charged interest on. This will help reduce your mortgage payments each month and can make a huge difference to your overall outgoings over a longer period of time.</em></p>', 'rakbank-voiceover.jpg', '185199848', 'Rakbank Voiceover | Explainer video voices | by Guy Harris', '<h2>Get in touch</h2>\r\n<p>DoÂ you have an explainer video or <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV/Radio ad</a> in need of a voice? Maybe one like this Rakbank Voiceover? If so, please feel free to get in touch. To make the process even easier, just let me knowÂ the intended length and usage, and I can quote you more accurately. Send a short sample of the script and I\'ll send you a short audition. Check to see if my voice isÂ right for your project. Please do get in touch today.</p>', 'Dec 2016', '0', 'Rakbank Voiceover', '5', '', 'Rakbank Voiceover - Home in One', '', '', '', '', '', '', '', '', ''),
(713, 'father-christmas-santa-voiceover', 'Father Christmas Santa Voiceover', '<p style=\"font-size: 18px;\">\r\nExperience the ultimate <strong>Father Christmas Santa voiceover</strong> with my demo, showcasing delightful interactions from <a href=\"https://www.santaradio.co.uk\" target=\"_blank\" style=\"color: #0073e6;\">Santa Radio</a>, the Worldâ€™s No.1 Christmas radio station. Broadcasting 24 hours a day, 365 days a year, Santa Radio offers much more than just back-to-back Christmas music.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\nWith Father Christmas himself as the DJ, youâ€™ll hear celebrity messages, festive humour, and engaging interactions with listeners. Itâ€™s the perfect blend of holiday cheer and entertainment!\r\n</p>\r\n', '', 'Father Christmas Santa Voiceover -Â The UK\'s busiest voice of Santa, A selection of fun calls with listeners to Santa Radio. The Worlds No.1 Christmas Radio.', '<h2 style=\"font-size: 24px; color: #AD030C;\">Check Out the Video</h2>\r\n\r\n<p style=\"font-size: 18px;\">\r\nDiscover the magic of <a href=\"https://www.santaradio.co.uk\" target=\"_blank\" style=\"color: #0073e6;\">Santa Radio</a>, the go-to destination for a festive Christmas soundtrack. Available on all mobile devices, including iOS and Android, you can also enjoy it on Apple TV and as a downloadable app for your iMac or MacBook.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\nAdvertised as Christmas radio with personality, Santa Radio is rapidly becoming the top choice for holiday entertainment online. Iâ€™m proud to be a part of this incredible platform, spreading holiday cheer to listeners around the world.\r\n</p>\r\n', '<h2 style=\"font-size: 24px; color: #AD030C;\">Voice of Santa</h2>\r\n\r\n<p style=\"font-size: 18px;\">\r\nIâ€™m proud to help the Real Santa during the festive season, having established myself as the official <strong>Voice of Santa</strong> for <a href=\"https://www.voiceoverguy.co.uk/bbc-radio-2-voice-of-santa\" target=\"_blank\" style=\"color: #0073e6;\">BBC Radio 1</a>, <a href=\"https://www.voiceoverguy.co.uk/bbc-radio-2-voice-of-santa\" target=\"_blank\" style=\"color: #0073e6;\">BBC Radio 2</a>, and the Heart Radio Network, among many others.<br>\r\nI also had the honour of voicing Santa in the <a href=\"https://www.youtube.com/watch?v=ZEwMyp2Z530\" target=\"_blank\" style=\"color: #0073e6;\">CBeebies Go Jetters Christmas Special</a>, bringing joy to families across the UK.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\nA true Santa or Father Christmas voice goes beyond just an accentâ€”it needs to capture the fun, warmth, and magic of Christmas. Iâ€™d like to think my voice conveys the true feeling of the season, making every project a little more magical.<br>\r\nMy work as Santa often begins as early as August, and itâ€™s a character Iâ€™ll never tire of. After all, I love Christmas too!\r\n</p>\r\n', 'father-christmas-santa-voiceover.jpg', 'Ps8zvdz-7rg', 'Father Christmas Santa Voiceover | Busiest voice of Santa', '<h2 style=\"font-size: 24px; color: #AD030C;\">Get in Touch</h2>\r\n\r\n<p style=\"font-size: 18px;\">\r\nAre you looking for a credible and professional <strong>Voice of Santa</strong> or <strong>Father Christmas voiceover</strong> for your radio station, promo, or festive project? Look no further!<br>\r\nSimply <a href=\"mailto:santa@voiceoverguy.co.uk\" style=\"color: #0073e6;\">get in touch</a> today and letâ€™s discuss how I can bring the magic of Christmas to your project.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\nTo make the process simple, let me know the intended usage of the voiceover, and Iâ€™ll provide an accurate quote. Send over a short sample of your script, and Iâ€™ll be happy to record a brief audition to ensure my Father Christmas voice is the perfect fit for your needs.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\nDonâ€™t waitâ€”contact me today and letâ€™s make your project truly magical!\r\n</p>\r\n', 'Dec 2016', '1', 'Father Christmas Santa Voiceover', '3', '', 'Awesome Father Christmas Voice.', '', '<h2 style=\"font-size: 24px; color: #AD030C;\">Why Choose a Professional Father Christmas Voice?</h2>\r\n\r\n<p style=\"font-size: 18px;\">\r\nA truly memorable <strong>Father Christmas voiceover</strong> can elevate your project and connect with audiences of all ages. As a seasoned voiceover artist, I bring authenticity, warmth, and a touch of cheeky charm to the role of Santa. <br>\r\nWhether youâ€™re producing a festive radio ad, a heartwarming TV promo, or an engaging social media campaign, a professional voice ensures your message is delivered with credibility and festive magic.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\nWith years of experience working with top brands like <a href=\"https://www.voiceoverguy.co.uk/bbc-radio-2-voice-of-santa\" target=\"_blank\" style=\"color: #0073e6;\">BBC Radio 2</a>, ITV, and the Heart Radio Network, I understand what it takes to make your project stand out. Letâ€™s make this Christmas unforgettable!\r\n</p>\r\n', '<h2 style=\"font-size: 24px; color: #AD030C;\">FAQs About Father Christmas Voiceovers</h2>\r\n\r\n<p style=\"font-size: 18px;\">\r\n<strong>Q: What makes your Father Christmas voice stand out?</strong><br>\r\nA: My voice combines authenticity, warmth, and a cheeky charm that resonates with audiences. Iâ€™ve worked with leading brands, so you know youâ€™re getting a professional result.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\n<strong>Q: How quickly can you deliver a project?</strong><br>\r\nA: Most projects can be delivered within 24 hours, but Iâ€™m happy to accommodate tight deadlines when needed.\r\n</p>\r\n\r\n<p style=\"font-size: 18px;\">\r\n<strong>Q: Can you provide a sample before I book?</strong><br>\r\nA: Absolutely! Send over a short script, and Iâ€™ll record a quick audition so you can hear how it sounds.\r\n</p>\r\n', '', '', 'bbc-radio-2-voice-of-santa.jpg', 'bbc-radio-2-voice-of-santa.jpg', '', ''),
(717, 'reset-app-voice', 'The Reset App Voice', '<p>Following the crazy busy Christmas period I had as a voice over, it was nice to start 2017 as the voice of an App that I felt I needed.</p>', 'natural conversational', 'The Reset App - The voice over from the tv advert. Experience the benefit that meditation can bring to your daily life with just a few minutes practice a day.', '<br>\r\n<h2>The Voice ofÂ the Reset App TV Advert</h2>\r\n<p>So, here we have the Reset App and my voice of the brand. I voiced it and then downloaded it to check it out. It\'s actually a really good product if you want to unwind, relax and just chill out. They wanted a natural and conversational tone for the ad and I think my voice is a natural fit. This kind of relaxed, neutral voice is also my go-to for many of my <a href=\"explainer-video-voice\" target=\"_blank\" title=\"Explainer Videos\">explainer videos</a>.\r\n<br>There\'s some beautifully drawn animation too, on this ad, which was done by a great company in London I work with regularly. </p>', '<br><h2>What is it all about?</h2>\r\n<p>Experience the benefit that meditation can bring to your daily life with just a few minutes practice a day. Take some time to boost your energy levels & reduce stress, helping you sleep better & feel positive. You\'ll be better equipped to cultivate better relationships with those around you and to meet the challenges the day brings. With Reset, you can enjoy a slice of mindfulness anywhere, anytime. If you liked the ad for Reset app and you\'re looking for something similar, you may like to check out my <a href=\"https://www.voiceoverguy.co.uk/apple-voice-style\" target=\"_blank\" title=\"Apple Voiceover\">Apple-style voiceover showreel</a>.</p>', 'reset-app-voice.jpg', 'iVotWtmRc_o', 'The Reset App - TV advert voiced by Guy Harris', '<br>\r\n<h2>Get in touch</h2>\r\n<p>Are you looking for a voice similar to this one for the Reset App? Do get in touch via the <a href=\"contact-guy\" target=\"_blank\" title=\"Contact VoiceverGuy\">contact page</a> \r\nand let\'s chat. You may like to check out some of my other <a href=\"commercial-voiceover\" target=\"_blank\" title=\"Commercial Voiceover\">TV commercial voiceovers</a> first. If you send me a few lines, I\'d be very happy to send a sample of your script to you before you book. This way you can be sure I\'m right for your brand. \r\nI make the whole process as easy as possible with 99% of the jobs delivered the same day.</p>', 'Jan 2017', '1', 'reset-app-voice', '3', '%23ResetApp', 'Relax with the Reset App...', '', '', '', '', '', '', '', '', ''),
(718, 'halloween-voiceover', 'Halloween Voiceover Showreel', '<p>Each and every October I\'m asked to add my voice to many a spooktacular production. Time for yours?</p>', 'Halloween spooky scary vincent price evil devil twisted', 'Halloween Voiceover Showreel -  Each and every October I\'m asked to add my voice to many a spooktacular production. Time for yours? Ha ha ha ha!!!', '<h2>Spooky Voices</h2>\r\n<p>For as long as I can remember I\'ve been putting on voices and imitating people and sounds. I love the spooky styles, especially when close on the mic.<br>\r\nI\'ve been lucky enough to work with some excellent script writers and have used this voice style for major brands including BBC & ITV. Can I help you?\r\n</p>', '<br>\r\n<h2>What is Halloween?</h2>\r\n<p><i>Halloween or Hallowe\'en (a contraction of All Hallows\' Evening), also known as Allhalloween, All Hallows\' Eve or All Saints\' Eve, is a celebration observed in a number of countries on 31 October, the eve of the Western Christian feast of All Hallows\' Day. It begins the three-day observance of Allhallowtide, the time in the liturgical year dedicated to remembering the dead, including saints (hallows), martyrs, and all the faithful departed.</i></p>', 'halloween-voiceover.jpg', '143288786', 'Halloween Voiceover Showreel - Spooky voices by Guy Harris', '<h2>Do get in touch if you dare...</h2>\r\n<p>If you have a production, event or film that you need a Halloween Voiceover,  do get in touch. Use the <a href=\"contact-guy\" title=\"Contact VoiceverGuy\">contact page</a> \r\nand lets chat. <br>Send a few lines and I\'d be very happy to send a short sample before you book me so you can be sure I\'m right for your brand. <br>\r\nI\'ll make the whole process scarily easy, with 99% of the jobs delivered the same day.</p>', 'Oct 16', '0', 'halloween-voiceover', '3', '%23Halloween %23Spooky', 'Looking for a spooky voice for Halloween?', '', '', '', '', '', '', '', '', ''),
